window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_023"]={"n":"顾清","dyn":"明","poems":[{"t":"首夏即事","f":"七言律诗","c":["金兽香残昼漏稀，嫩槐庭院午风微。","蜜房分子蜂初静，书阁垂帘燕自飞。","小碾试茶催瀹鼎，轻刀裁葛已成衣。","故园遥忆三江外，梅豆青青笋过扉。"]},{"t":"白燕","f":"七言律诗","c":["海国年年傍社归，春来争讶羽毛非。","不经乳穴移仙骨，似剪齐纨作舞衣。","已化玉钗空怅望，未消红缕故依稀。","月明昨夜风帘动，惊起还随白练飞。"]},{"t":"谒文山祠用杜韵","f":"七言律诗","c":["碧殿长松锁十寻，晚云将雪助萧森。","貂蝉不改厓山制，金石疑闻孔壁音。","南去星潮嗟往事，北来祠庙岂公心。","春风一掬唐衢泪，几为先生湿短襟。"]},{"t":"十四日雪后朝回史馆作","f":"七言律诗","c":["紫宸晴雪映蓬莱，独出东厢候锁开。","学士履声云里下，君王銮驾月中回。","争先皓鹤羞初日，失喜遥林见早梅。","坐听角门宣唤急，却思授简惧非才。"]},{"t":"以灯圆饷陆太仆","f":"七言律诗","c":["三五新正忆故园，屑云糜玉闹春盘。","小奴解作江南意，远客都忘岁暮寒。","梅欲斗圆忙著子，雪如争巧故成团。","玉厓太仆真清吏，莫认明珠按剑看。"]},{"t":"三月廿一日书事 其一","f":"七言绝句","c":["只合清江坐钓矶，等閒谁遣著朝衣。","绿阴门巷青绳路，心逐南云一片飞。"]},{"t":"三月廿一日书事 其二","f":"七言绝句","c":["小阁垂帘相对红，窄衫低帽一丛丛。","归来有语那能记，坐倚东风忆梦中。"]},{"t":"送徐中行南京工部","f":"七言律诗","c":["瘦石亭前倚晓风，十分凉意小桥东。","雨馀杨柳秋仍绿，露下芙蓉晚更红。","情至怕闻千里别，会疏犹喜一尊同。","留都宫苑稀程作，高咏还应不负公。"]},{"t":"钱思孝挽诗","f":"七言律诗","c":["芳草春深满绿园，王孙归去已消魂。","人怀故国流风远，堂有旌书节孝存。","辽鹤何年返华表，楚歌当日怨修门。","惟应黄泗源头水，流得馀波到子孙。"]},{"t":"宫体四首次良金韵 其一","f":"七言绝句","c":["鳷鹊楼深月到迟，倚阑閒弄玉参差。","侍鬟记得新腔去，又向花间教雪儿。"]},{"t":"宫体四首次良金韵 其二","f":"七言绝句","c":["水殿凉多梦易醒，昭阳歌吹隔青冥。","绛纱还有同来伴，奉帚金门候晓星。"]},{"t":"宫体四首次良金韵 其三","f":"七言绝句","c":["领得银环奈别何，更烦同伴画双蛾。","一般昨夜龙池雨，偏有垂杨叶上多。"]},{"t":"宫体四首次良金韵 其四","f":"七言绝句","c":["玛瑙阶边蛱蝶花，玉阑低转画廊斜。","大家近日亲经史，不向宫门候小车。"]},{"t":"次石楼太史和陈时雨大行刘汝中中舍东圃联句韵","f":"七言律诗","c":["病学安心未有方，清斋聊欲寄僧廊。","檐花细雨思公甚，尘海西风为底忙。","薝卜定应谁共嗅，醍醐遥羡独先尝。","石翁妙语清人骨，吟断东轩一缕香。"]},{"t":"时雨用东圃韵写怀兼惠柳木壶矢","f":"七言律诗","c":["束矢形裁出蓟方，几陪陈榻署东廊。","争枭解夺由基巧，失笑曾闻玉女忙。","分遗却随诗并至，试投谁合酒先尝。","春风有约应非远，拍瓮新醅夜已香。"]},{"t":"腊月廿三日饮德卿宅用涯翁斋居联句韵","f":"五言古诗","c":["良游集南园，秉烛向深夜。","盟寻旧雨馀，坐想重茵藉。","墙阴有残雪，邻酒方索价。","西瞻太行峰，皓白欺二华。","兹惟藏春坞，岂伊淩风榭。","洪炉赫彤霞，馀香袅檀麝。","窗明疑若空，檐短不留罅。","吟苦愁后成，棋勍斗先下。","翻思前夕里，高宴久已罢。","远钟送深更，疲仆催早驾。","顾兹蚓窍鸣，试我蝇头写。","得隽豪屡挥，沈思首频亚。","忽看山月高，顾影独惊诧。","情兼宾主忘，气已芝兰化。","诸公信自贤，此夕颇堪讶。","招要入拘牵，窘迫自閒暇。","词非石鼎工，酒罄金罍泻。","明朝逐馀欢，此榻宁许借。"]},{"t":"书所见 其一","f":"七言绝句","c":["垂杨十里拂金堤，走马东来不记谁。","飞虎两鞬摇玉带，盘雕双袖蹙金丝。"]},{"t":"书所见 其二","f":"七言绝句","c":["马首东风吹柳丝，碧桃红杏斗芳菲。","游人不是金丸客，说与流莺莫乱飞。"]},{"t":"为杜庠题山水横幅","f":"七言古诗","c":["屋头众山森戟戟，屋下寒溪深见石。","溪流循山若萦带，别馆离亭纷向背。","茅堂近水景绝幽，绕檐万竹风飕飕。","主人自得濠上意，终日俯槛临寒流。","东寮把酒呼促席，隔屋糟床晚犹滴。","清谈北馆风满衣，折梅寄远情依依。","山童晨起扫落叶，不知松露沾荆扉。","经营布置各有态，颇学画者劳天机。","东吴杜郎江海客，览胜搜奇遍京国。","家园十亩画不如，犹向丹青爱陈迹。","西风八月南雁飞，扁舟远自长安归。","高堂无事兄弟乐，终日鸡黍要邻比。","新图便是君家事，何必区区询画师。"]},{"t":"为潘克承题林良芦雁","f":"七言古诗","c":["林郎花鸟今代奇，水墨到处皆天机。","长缣阔幅信手挥，妙处不属丹青围。","江头雨深菱荇肥，枯槎折苇纷离披。","鴐鹅羽冷畏远飞，雄雌两两相猥依。","灵苕翠羽不自危，鸲鹆噤语晞玄衣。","依栖俯仰各有姿，乍见几欲呼鹰师。","乃知此老笔不疲，市朝山林时见之。","鸡林相君知白诗，君家此本吾无疑。","北风渐高禾黍稀，云飞日见江南归。","吴江洞庭三泖涯，天空水远无拘羁，焉得扁舟从尔嬉。"]},{"t":"斋居独坐寄三江","f":"七言律诗","c":["我马今晨已自东，入门灯火夜堂空。","浮云不放中天月，古木频号别院风。","梦绕白楼千里远，坐围红烛几人同。","春来点检诗多少，扈宿陪祠亦有功。"]},{"t":"安山待闸憩大柳下见蜣螂转丸及窟穴薶藏之状甚悉村童语其故词甚鄙而近于人事戏以韵语记之","f":"五言古诗","c":["蜣螂抟土丸，其智竟莫测。","中包实粪秽，外裹疑橡栗。","后推前复挽，圜转何捷疾。","端如趁严程，又似衒巧术。","趋洼真一泻，过隘亦屡兀。","中途遇强暴，奋斗几撑突。","归来不少暇，坎土启藏室。","既以首为畚，复以股为橛。","爬沙兼负戴，下上几颠越。","室成拥丸下，劣隘四无隙。","周旋巧斡运，每动辄有入。","须臾丸尽隐，谓尔功已毕。","潜身复旁搜，坯壤时臲卼。","村童恶剧戏，寸筳时一搰。","室开丸反流，惊救走连蹶。","双趋共抚抱，有类拱珠砾。","前功已尽弃，馀念犹未歇。","想其推挽去，行复事钻穴。","物生均有智，小大理难一。","蚕丝利万世，蝥网为口实。","蜂房及蚁冢，致用等轩闼。","尔丸独何为，久念理未彻。","村童前致词，此实神所訹。","转丸输鬼藏，功满蜕凡骨。","飞腾作风蝉，清响哕云月。","营营苟为此，蜣计诚已劣。","丸也神所须，得无秽明烈。","物性尔岂知，神奸我能别。","纷纷讵为信，琐琐焉足说。","聊戏答村童，鼓响官舟发。"]},{"t":"穫稻用分秧韵","f":"七言律诗","c":["负郭园池带宅田，老晴天气太平年。","穫来黍稻丛高廪，散出牛羊满近川。","饙启甑山腾雾霭，蚁香醅瓮起沦涟。","斜阳一枕西窗梦，纵有丹青不与传。"]},{"t":"十二月十八日大雪登楼作寄进之天锡时诸君方修府志","f":"七言古诗","c":["酸风割耳须作虬，闻雪强起开西楼。","西楼一望几十里，玉田瑶圃烂不收。","两年粳稻化鱼鳖，穷计每日占来牟。","眼前富贵已如此，何苦更作明年愁。","书生耐冷自常事，北窗清坐端谁留。","神游不到党家帐，意行屡上山阴舟。","淮南山海诞莫考，吴中沟浍须精求。","映雪著书堪一笑，却似五月披羊裘。"]},{"t":"次晚风雪又作用前韵","f":"七言古诗","c":["玉龙飞天从万虬，下与白凤窥红楼。","天人剪水碧云霄，幻作万宝无人收。","晚来疾风振林谷，时复乱牛同一牟。","蒋生扁舟泊何处，纵有美酒还堪愁。","进之病骨近始苏，旅食岂为鱼羹留。","炉灰拨残红烛短，谁与再倾双玉舟。","一夫失所是予责，二气迭胜非人谋。","夜阑寒甚欲就枕，解带却愧狐重裘。"]},{"t":"进之天锡舜弼有和章再用韵","f":"七言古诗","c":["冻指握笔如拳虬，犹有雪诗来北楼。","北楼几日不一到，寒阵未许阳乌收。","瑶琨鹭羽孰坚脆，往往精辩闻龙牟。","长安书生四十韵，远喜不救沟中愁。","颍阴禁体亦何事，雕刻但有空言留。","凭高极目意颇豁，滉漾如驾虚空舟。","珠宫玉宇隔人世，一暖谁为苍生谋。","洛阳尽覆吾亦愿，尚恐目前无此裘。"]},{"t":"东园饯别太守酒酣剧论至于得失宠辱之际听之洒然是夕被酒齿痛不寐辄用苏长公过清虚堂韵歌以扬之卒章颂言为将来世讲之张本也","f":"七言古诗","c":["人间万事真握沙，黄堂昨日犹早衙。","春风留人苦无计，漫天扑路飞杨花。","杨花飘扬泊何处，碧山梦绕先生家。","邯郸已为鲁酒误，忧喜更足凭晨鸦。","东园雨馀绿满树，犹有青子粘残葩。","抚时惜别万感集，飘萧短发手屡爬。","众宾微酣我轻汗，论功莫计酒与茶。","花奴羯鼓不解事，落日猛向红阑挝。","盛时会须有代谢，末俗正尔堪吁嗟。","归舟安稳足春梦，梦抱玉燕吞流霞。"]},{"t":"壬申正月十九日过北野同南村访北花园废址明日北野有诗仍用清虚堂韵走笔奉答","f":"七言古诗","c":["筑堤不拟长安沙，鸣鼓已放西曹衙。","夜游泾南鹤城北，随处幅巾宜看花。","花林高下映丛冢，池台旧属淇水家。","当时笙歌沸邻里，只今古树啼寒鸦。","先生读书洞千古，过眼富贵如春葩。","时人不识竞模拟，往往背痒连衣爬。","消忧满贮北海酒，破闷亦有南山茶。","家生小奴解新曲，时复羯鼓当轩挝。","邮筒往复方此始，一倡何止三人嗟。","诗成挥翰向落日，墨光绕笔飞玄霞。"]},{"t":"四月十二日定庵先生过访诵东坡过清虚堂诗用韵奉谢","f":"七言古诗","c":["夜窗急雨鸣撒沙，晨鼓不辨州官衙。","村童晏眠蓬户闭，榆荚一径交残花。","经年不及长者室，泥水真作田农家。","高轩何自忽戾止，豁若暝雾腾金鸦。","清容穆穆峙霜柏，妙语郁郁飞天葩。","尘埃塞胸不自理，次第一一烦梳爬。","盘飧菲恶愧草草，幸有杞蘖供春茶。","此时天公亦助喜，列缺捲焰雷停挝。","骚坛夙昔愿奔走，世事八九堪咨嗟。","酒阑公去倚江阁，遥见一鹤冲高霞。"]},{"t":"陪定庵过北野再用韵","f":"七言古诗","c":["河洲浅水笼银沙，高柳隔岸排晨衙。","湿云晴旭互吞吐，时复映空飞雨花。","人间岁月总能几，三年不到先生家。","诸孙迎拜肃有礼，别时稚语犹轧鸦。","不知甘露何日降，亲见紫芝团玉葩。","山林朝市各有适，如痛须抑痒须爬。","羊羹鼋炙岂不美，陆羽独好山中茶。","惜哉祢衡傲一世，营门乃作渔阳挝。","先生归来万事足，耳目所及堪吁嗟。","尊前有酒便一笑，不用导引吞朝霞。"]},{"t":"涯翁七十寿诗二首 其一","f":"七言律诗","c":["睿皇初运岳生贤，留付神孙秉化权。","一代盛名今古绝，五朝隆眷始终全。","山龙不露弥纶手，桃李都归长养天。","回望玉堂趋走地，不知何以祝长年。"]},{"t":"涯翁七十寿诗二首 其二","f":"七言律诗","c":["午桥长夏日如年，吏散瀛洲聚锦筵。","黄阁衣冠诸老外，清时钟鼓百花前。","閒情好鸟鸣深树，往事浮云澹远天。","惟有老人南海上，祥光夜夜绕台躔。"]},{"t":"崔世兴宅奉次涯翁韵","f":"七言律诗","c":["酒敌棋朋四坐分，不知何处是东君。","屏间拂石疑生雨，画里看花半作云。","白雪词章随笔散，红尘车马隔墙纷。","平生六一堂前士，到处春风挹令芬。"]},{"t":"四月十三日同时敏送仲玉景和归途有感作","f":"七言律诗","c":["漠漠轻云淡淡风，御沟溶漾落花红。","一番离别中年后，千里河山夕照中。","垂角故人霜两鬓，关心岐路草连空。","归来稚子迎门笑，何日亲交送阿翁。"]},{"t":"斋居览菽园杂记有感呈三江","f":"七言律诗","c":["东观紬书共几篇，南宫题草又三年。","风流未敢忘前辈，名姓多应愧后贤。","云里泰阶星近远，天涯岐路草芊绵。","夜来梦好君知否，一棹扁舟野水边。"]},{"t":"题计郎中汝和墨菊曹汝学家藏","f":"古风","c":["郎中画菊真是菊，蒙泉蒲萄太常竹。","一时能事并驰声，岂直文章难继续。","狂挥急扫皆称意，不特品高机亦熟。","西涯坐间生色障，一见当时已心服。","不知何日到君家，净洗朱铅斗清淑。","疏篁古木交映带，深浅生枯俱入态。","欹风一枝惊欲折，倚竹数丛如有待。","飞鸾坠羽时自压，老蛟蜕骨令人骇。","张颠草圣久寂寞，何意兹晨忽倾盖。","郎中郎中今有无，后来尚远眼中疏。","柔肌脆骨争媚妩，不然蔓草纷黄垆。","颓波一去谁与返，把卷抚玩增长吁。","君不见近时淮海上，亦有菊花一派往往传京都。"]},{"t":"出郊","f":"七言绝句","c":["小队黄衫簇绛灯，春来几度出郊行。","桃花结子杨花尽，只有蘼芜满路生。"]},{"t":"冬至谒陵次三江送行韵","f":"七言古诗","c":["初阳映雪暖欲蒸，千门瑞气通诸陵。","朝廷报本严奠扫，秩礼远自前王兴。","秋霜春雨意惨惨，奁香篚帛心兢兢。","高皇统天祀万世，奋自垄亩挥戟矜。","两都并建始文祖，鼎命重为诸孙凝。","传闻桥山初启邑，鸾舆玉趾几降登。","小臣何幸得将事，敢论暑雨仍寒冰。","经涂百里净如扫，舆夫踊跃誇力胜。","回龙小憩才半道，瞬息已睹洪仁灯。","入门弛担随所适，东寮西馆各有朋。","山僧频见头亦白，为我载演牛车乘。","寒光淩乱入窗户，起视海月摩空升。","瑶宫银阙自万古，虽有晦蚀无亏增。","嫦娥悄立如有恨，欲斩桂树嗟谁能。","斋居元不碍酬咏，公诗险语何层层。","磨崖拟刻永昭颂，挽断千仞寒溪藤。"]},{"t":"归途再次韵","f":"七言古诗","c":["燎烓长烟升槱蒸，百官星拥桥山陵。","鸾车龙驭想戾止，玄云郁勃中天兴。","六飞南巡知近远，为感岁时还惕兢。","江淮民力惟国本，先皇子育多悯矜。","乌号空抱鼎湖月，血泪几与山泉凝。","翻思年少上陵日，隔城望山飞欲登。","来时不愁沙河涨，归路曾踏章村冰。","年华不留心独在，踞鞍十里已弗胜。","出山望城喜月上，骑火夹道如春灯。","化人楼殿锁寥寂，金碧斩新无与朋。","茫茫缘业谁为考，无乃劫运相凭乘。","再吟嘉赠拟赓属，一韵费酒几盈升。","我才白发梳渐短，君思川流来日增。","聊将岁月纪行役，敢与斤垩论工能。","尘途纷扰又三日，冈垄下上应千层。","明年再到知健否，归问老韩寻赤藤。"]},{"t":"敬亭见和山行有李杜齐能之句虽主押韵而亦非所当也因歌奉答拜写近怀","f":"七言古诗","c":["梧槚不杂中林蒸，诗人以来称杜陵。","公才本高心独下，退与元白图中兴。","山行一篇如见我，扪萝踏雪几凛兢。","时从雅淡出奇丽，少年敛手不得矜。","三阳改岁万物泰，和气上与游云凝。","清河沙河柳色动，近山已有游人登。","南飞六骥想回首，足底不见阴山冰。","甘泉荷橐事已远，洛桥轫车材弗胜。","破除寂寞赖公等，往往邮筒侵夜灯。","朝来雪篇更雄富，无复珠贝论升朋。","五湖烟艇未许上，灞桥驴子还堪乘。","已闻羔韭毕春祀，伫见柴燎中天升。","平安夜火报不绝，似有车骑来增增。","兰台执简公未老，长杨奏赋吾犹能。","扫妖灭怪止一笔，取青媲白应千层。","眼前却有两物恼，中山狡兔剡溪藤。"]},{"t":"春雪敬亭用前韵再答","f":"七言古诗","c":["西山落日云蒸蒸，漫衍涧谷弥冈陵。","晓窗梦破闻扫雪，失喜一笑披衣兴。","天街大有隔岁伴，羸马前日犹凌兢。","常言三白兆丰稔，民病亟矣天须矜。","从风初学柳絮舞，缀树旋作梅花凝。","素娥晨朝纷下女，玉龙夜战迷先登。","瓦垆烟焰坐不暖，起视胆瓶胶作冰。","前年冬温人苦疾，往岁雨多苗弗胜。","新春得此喜可说，光景十倍鳌山灯。","忘怀一任鸿寄迹，耐久正爱霜为朋。","淮西剡曲总佳话，万骑孰与扁舟乘。","愁来呼酒径一醉，斟酌不计斗与升。","长安薪炭已如玉，又报米价江南增。","开门高卧吾岂敢，手挽沟壑嗟无能。","登楼望山一舒啸，银屏玉案高崚层。","何当致我此中去，看煮雪茗烧枯藤。"]},{"t":"戏和石潭尝酒 其一","f":"七言律诗","c":["不惜糟床劈作柴，已呼儿子旋安排。","只愁新瓮能几榼，遂有高轩驻两阶。","永夜烛光邻壁骇，他年谈苑几人偕。","细君不学刘伶妇，晚出双鱼更自佳。"]},{"t":"戏和石潭尝酒 其二","f":"七言律诗","c":["城西门掩夕阳柴，剥啄寻常不用排。","况是新篘方满屋，何妨曳履日登阶。","愁来白发欺簪短，老去黄花有竹偕。","既醉莫嫌诗晚就，行年不似丙丁佳。"]},{"t":"戏和石潭尝酒 其三","f":"七言律诗","c":["无问登龙与叩柴，酒魔诗祟要人排。","不冲京兆行春马，便踏先生系马阶。","桂屑捣残犹自辣，雪儿歌后许谁偕。","逃虚避俗吾何敢，正若君言也复佳。"]},{"t":"乙亥元日十峰饮师邵东斋出予家桂饼师邵有诗自墙上递至次韵奉答","f":"七言律诗","c":["宝钿和露压金英，为趁秋光一日成。","月殿有人留素影，花林无物称佳名。","携来不觉乡关远，吟罢犹令客梦清。","茗盌酒杯皆可意，好将新岁作传生。"]},{"t":"明日师邵有墙上传诗之作次韵","f":"七言律诗","c":["似有虹光射屋头，不知人语夜堂幽。","呼墙忽得渊明信，能赋真同子建流。","便拟续貂嘘冻笔，却惭烧蜡变更邮。","玉堂本与兰台近，珠璧寻常岂外求。"]},{"t":"师邵出意作纶竿于墙上以便递诗名曰诗钓首倡一篇词意兼美依韵奉酬","f":"七言律诗","c":["巧心文思孰兼长，诗钓诗成又几章。","千里浮沈谢江路，一竿风月共邻墙。","君如缘木求鲂鲤，我正怀砖想佩璜。","毕竟两无名利念，五湖烟水旧同乡。"]},{"t":"夏日感事次味苓韵","f":"七言律诗","c":["陶翁正好北窗眠，也为閒情一怆然。","水屋自应荷作盖，金貂定以玉为蝉。","祥云捧日群龙拥，巨堰浮山一蚁穿。","神运斡旋俄顷事，未须低首拜啼鹃。"]},{"t":"南村约庵雨中过访喜新街成饮平胃散酒是日谈论间多可慨者别后赋此寄之","f":"七言律诗","c":["白云本是青云侣，今雨依然旧雨人。","舆力竞誇新路稳，酒奴还说近方醇。","纷纷且置人间事，皦皦谁全物外身。","毕竟浮生几两屐，欲将泰华等游尘。"]},{"t":"杜竹泉六十二寿诗","f":"七言律诗","c":["竹林娟好石泉纡，林下幽人六十馀。","裹药岁烦红印纸，画容新试碧霞裾。","尧年舜历资延引，二竖三彭待扫除。","慎勿求仙想遗世，羡门依旧海滨居。"]},{"t":"寄储丽中时京中客舍犹未售","f":"七言律诗","c":["浮名紫陌万风花，客舍红亭一传车。","阅岁流光驹过隙，关心朋旧手抟沙。","未能遗迹同寒雁，想见空庭噪晚鸦。","捲却双鱼还自笑，故人秋早又星槎。"]},{"t":"游鹤径田舍过黄耳祠","f":"七言律诗","c":["山灵应道我归来，一径新添雨后苔。","高柳直从江路见，细花还傍竹丛开。","百年天际云千变，万事林间酒一杯。","记得吾家老开府，当年曾劝陆郎回。"]},{"t":"诸广文饯予龙潭僧舍别后有怀味苓","f":"七言律诗","c":["听鹤亭前欲上潮，龙潭落木晚萧萧。","愁来别酒难成醉，老去诗翁不可招。","地下骚坛自旗鼓，人间博局几卢枭。","翠萝金盌当时句，残月空梁独自谣。"]},{"t":"甲申三月望日识奠三江舟中有作 其一","f":"五言律诗","c":["浅碧娄江水，蘼芜被两涯。","平生到曾未，此日看成悲。","怅望云龙会，淹留絮酒期。","中冈知近远，烟树郁参差。"]},{"t":"甲申三月望日识奠三江舟中有作 其二","f":"五言律诗","c":["忆昔曹园别，公西我自东。","竟成千载恨，犹幸一尊同。","往事鸿飞外，浮生蝶梦中。","有怀知莫问，梁月穗帷空。"]},{"t":"甲申三月望日识奠三江舟中有作 其三","f":"五言律诗","c":["多暇推南省，公来日纠纷。","执经辞断断，尊主意勤勤。","盐鼎虚黄阁，飙车已白云。","向来庭左辨，列柏想犹闻。"]},{"t":"甲申三月望日识奠三江舟中有作 其四","f":"五言律诗","c":["进退关忧乐，哀荣具始终。","策名龙首重，节惠奉常公。","桃径春阴遍，槐庭晚色浓。","濮园初议在，天下想遗忠。"]},{"t":"絅庵和前韵再叠","f":"七言律诗","c":["千舻并进一舠还，五色泉南屋数间。","渐近夕阳宜少息，未先朝露敢希閒。","案头缃帙茫如海，足底青鞋剩有山。","最喜鲈鱼不时样，登盘依旧玉鳞斑。"]},{"t":"淑人迁柩至祖送还书感八首 其三","f":"七言绝句","c":["此路同君两度归，归时长是泪沾衣。","如今不减当时泪，湿尽麻衣君不知。"]},{"t":"淑人迁柩至祖送还书感八首 其四","f":"七言绝句","c":["路转河桥客欲辞，黯然东望一沾衣。","来时记得停舆处，茅屋垂杨映酒旂。"]},{"t":"淑人迁柩至祖送还书感八首 其五","f":"七言绝句","c":["三十年前二十时，小窗灯火对鞶丝。","如今此意从谁语，头白伤心只自知。"]},{"t":"淑人迁柩至祖送还书感八首 其六","f":"七言绝句","c":["长安初到忆搬家，幼女娇儿共一车。","死别生离三十载，老怀争遣不成麻。"]},{"t":"淑人迁柩至祖送还书感八首 其七","f":"七言绝句","c":["京华桂玉两关心，粗得心閒病已侵。","伴我一生成底事，诰鸾空印紫泥深。"]},{"t":"淑人迁柩至祖送还书感八首 其八","f":"七言绝句","c":["长途极目四千里，往事伤心五十年。","正到不禁凄断处，一声哀雁过楼前。"]},{"t":"涯翁与二汪饮襄陵酒闻清来留一尊见待已而尽之赋一醉二首清至首以见示敬和 其一","f":"七言绝句","c":["江湖无地著心宽，梦里尊前一笑欢。","来晚尚馀三日恨，春风只得半醒看。"]},{"t":"涯翁与二汪饮襄陵酒闻清来留一尊见待已而尽之赋一醉二首清至首以见示敬和 其二","f":"七言绝句","c":["黄阁归来绿野宽，诸生时得奉清欢。","吴泉晋水皆名胜，正要先生次第看。"]},{"t":"涯翁示独酌二诗序云是日饮松江酒次韵奉谢 其一","f":"五言律诗","c":["城阙非长往，山林是夙期。","时开问字酒，不赋解嘲诗。","绿树停觞久，红阑点笔迟。","奚童斟酌惯，深浅自能知。"]},{"t":"涯翁示独酌二诗序云是日饮松江酒次韵奉谢 其二","f":"五言律诗","c":["左掖文书静，西亭竹树幽。","几时能独醉，此日是真休。","地远陶潜社，人怀庾亮楼。","赏音知有在，谁复步兵求。"]},{"t":"清明日遣三儿奠李文正公墓时上疏乞归未报","f":"七言律诗","c":["三年不拜先生墓，一滴尤伤此日心。","古道曲村犹历历，旧松新桧想森森。","周旋未敢遗言坠，阅历空嗟往迹深。","愿乞明灵表衷素，早教藜葛返初林。"]},{"t":"岁云晚矣园居独谣追始惟今斐然有述八章 其三","f":"七言律诗","c":["石渠严秘许观书，丈席清华选钜儒。","道术孔颜留至训，文章典诰敕前谟。","月毫霜札来天府，玉馔金茎出帝厨。","回首十年空血泪，碧霄无路挽龙须。"]},{"t":"岁云晚矣园居独谣追始惟今斐然有述八章 其四","f":"七言律诗","c":["玉堂排日趋经幄，丹地分行拱御筵。","龙跃九渊屏隔座，凤回三殿阙中天。","祥云丽日瞻尧表，金尺瑶签启舜编。","长忆讲辰当国忌，素袍玄带俨终篇。"]},{"t":"岁云晚矣园居独谣追始惟今斐然有述八章 其六","f":"七言律诗","c":["周官六典肇升平，《鲁策》、《春秋》并五经。","彤管后先参记载，黄麻郑重入丁宁。","氓编不落涪陵险，米传羞闻晋史腥。","独卧烟江双雪鬓，尚馀幽恨在丹青。"]},{"t":"岁云晚矣园居独谣追始惟今斐然有述八章 其七","f":"七言律诗","c":["书生泥古自家风，曾职容台念始终。","所愿朝廷有夷契，敢将休戚间穷通。","纷纷尚忆盈庭语，凿凿谁收秉笔功。","闻道初阳涣新命，不胜翘望五云中。"]},{"t":"六言 其二","f":"古风","c":["小楼平跨林梢，足底昏明两潮。","藏舟不须巨壑，度鹤即是仙桥。"]},{"t":"六言 其三","f":"古风","c":["乍去还来沙鸟，将开半落林花。","社鼓前村隐隐，机声别院哑哑。"]},{"t":"陪芸轩观海宿村家纪事四首 其一","f":"五言律诗","c":["三月吴江上，垂杨作意青。","两堤烟冉冉，一路雨冥冥。","客况今初识，舟行未可停。","渔翁不愁惧，独立钓前汀。"]},{"t":"陪芸轩观海宿村家纪事四首 其二","f":"五言律诗","c":["云合天如羃，江翻浪若飞。","众山当昼隐，孤树入烟微。","舟楫危前路，庭闱感昨非。","不知天早晚，时见牧童归。"]},{"t":"陪芸轩观海宿村家纪事四首 其三","f":"五言律诗","c":["暝入空江路，茫茫问所投。","电光时掣剑，雨势欲翻舟。","鸿雁鸣何及，蛟龙怒未休。","前村有灯火，渐近复生愁。"]},{"t":"陪芸轩观海宿村家纪事四首 其四","f":"五言律诗","c":["中流失舟楫，一瓠千黄金。","风雨江村暮，野人怀顾深。","沾濡免僮仆，欢会洽朋簪。","惜哉漂母意，当者非淮阴。"]},{"t":"水仙扇面","f":"七言绝句","c":["瑶池不见董双成，清梦依依绕玉京。","岁晚相逢洛川路，一江寒碧月空明。"]},{"t":"绝句","f":"七言绝句","c":["云暗西山雨欲来，好风先到读书堆。","幽人正熟羲黄梦，乱揭床头书卷开。"]},{"t":"庚子秋日书感","f":"七言律诗","c":["槐花如雨落秋金，睡起凭阑思不禁。","满地绿阴容我懒，一篇长句向谁吟。","马因捷步翻成蹶，水到无声始是深。","世事相逢已如此，此生何必漫劳心。"]},{"t":"送沈惟馨赴举和陈刚中韵","f":"楚辞体","c":["朝阳有鸣凤，高冈有梧桐。","男儿生盛时，肯负气吞虹。","君不见饭牛者，长歌白石齐东野。","尧传舜继虽不逢，奋起犹能奠青社。","又不见和氏璧，胚胎本是山中石。","镌磨一日遇良工，遂与镇圭登紫极。","丝衣采采青于蓝，江边握手皆停骖。","便登万里道，肯恋一夕谈。","长风巨浪在足底，莼丝菰米焉足甘。","送子出九山，山鸟鸣间关。","官亭杨柳不用攀，笑指孤鹗青云间。","送子涉淀湖，画桨摇清波。","凤山回首何嵯峨，袖中雄剑鸣蛟鼍。","雍雍鸣凤，菶菶梧桐。","一川秋水，两腋清风。","辍耕鹿门陇，献赋长杨宫。","干羽舞两阶，日月明重瞳。","云梯一回首，扰扰多沙虫。","嗟我此行不得相从兮，但虚窗静夜梦想秦淮四壁之高峰。","秋风好消息，早寄南飞鸿。"]},{"t":"沈惟馨之赴举也予既有诗和陈刚中韵送之矣今再寄七律一首","f":"七言律诗","c":["凤凰台下簇雕鞍，台上云封十二阑。","日炫龙光钟阜晓，空蟠虎气石城寒。","凌风有梦排天阙，鞭石何由泛海澜。","吹彻紫箫天似水，月明犹想独乘鸾。"]},{"t":"题竹","f":"古风","c":["兔颖凉分月魄，凤毛寒湿松烟。","日暮白云飞尽，一天秋色苍然。"]},{"t":"枯木睡禽","f":"五言绝句","c":["皇仁覃八荒，虞网解三面。","小鸟深山中，独宿不惊眄。"]},{"t":"咏二乔得真字韵","f":"七言绝句","c":["铜雀金陵总未真，六朝花月几经春。","阑干误喜逢倾国，却是丹青卷里人。"]},{"t":"北坛斋宿","f":"五言古诗","c":["初月明远树，繁星丽高空。","清坛矗紫垣，周道蟠青虹。","地胜宅壬坎，木秀扶杉松。","惟时八月初，万象呈秋容。","长原锁寒碧，乾树明新红。","嘉谷卧连野，败稂枯作丛。","岁功奄铚艾，吉日临著雍。","时祀不敢后，冠盖来童童。","微名系官府，将送烦仆僮。","追随缙绅后，周旋尊俎中。","仰瞻霄汉间，神光煜昭融。","骏奔既肃穆，对越何昂颙。","官备物有纪，夜寂天无风。","清乐发丝竹，严令闻鼓钟。","笾豆纷夙饤，醢菹簇时供。","长烟起苇炬，画烛辉雕笼。","霓幢隐双凤，云軿留六龙。","和熙洽幽玄，蜚蚃闻苍穹。","由来诚敬孚，不在仪品丰。","吾闻古王都，右社而左宗。","宗以明祖德，社以昭神功。","民非土与谷，生养安所从。","所以古至今，严祀无终穷。","吾侯素勤理，祀事尤寅恭。","饮食神既嗜，茀嘏宜来崇。","君看秋野间，万宝如崇墉。","百室会盈止，醴醪各迎逢。","闾阎礼让行，囹圄莓苔封。","神功不可忘，允侯诚所通。","作诗纪盛事，窃效康衢童。"]},{"t":"破镜篇","f":"楚辞体","c":["破镜宁终破，不愿重入奁。","断弦宁终断，不愿鸾胶粘。","人生一生惟一死，此身岂可轻相许。","因循一语涉狐疑，死向重泉作羞鬼。","所以古志士，跬步不敢轻。","譬逢三岐路，熟问乃敢行。","屹立万仞冈，决眦孤风生。","乾坤落落一身远，风尘混混双眸明。","古人已去不可作，末世吁嗟轻唯诺。","昨日仇雠今友朋，朝哭泣兮暮欢谑。","凉风萧萧吹客衣，苍茫岁晚孤鸿飞。","梅花夹道慵举首，涕泪满襟怀昔时。","我愿天地间，万事皆从愿。","有始必有终，不作风花片。","陶然百岁中，永绝痴儿面。","君不闻蔡琰胡笳十八拍，千载英雄泪如霰。"]},{"t":"征妇词","f":"七言律诗","c":["银灯花落夜迟迟，最忆灯前笑语时。","哀乐易迁惊逝水，关山无路怨娥眉。","风沙漠漠人何在，星汉迢迢鹊亦疑。","见说天山弓未挂，敢将清泪浪沾颐。"]},{"t":"村居杂兴六首 其一","f":"七言绝句","c":["屋东小堤长半里，疏柳成行荫秋水。","无风时复一叶飞，有风终夜鸣不已。"]},{"t":"村居杂兴六首 其二","f":"七言绝句","c":["庭前蔷薇好枝叶，初秋落残冬更发。","虽无颜色媚西风，甘与贞松待霜雪。"]},{"t":"村居杂兴六首 其三","f":"七言绝句","c":["石榴经霜红满枝，前年三月移根时。","珠囊玉醴纤手擘，幽人为尔惊栖迟。"]},{"t":"村居杂兴六首 其四","f":"七言绝句","c":["盆池养莲期看花，两年不发吁堪嗟。","浮萍叶死水痕长，微波蹙蹙跳鱼虾。"]},{"t":"村居杂兴六首 其五","f":"七言绝句","c":["梅花吾侪之故人，寂寞短篱今五春。","迟唤南邻锦囊客，月明为返罗浮魂。"]},{"t":"村居杂兴六首 其六","f":"七言绝句","c":["灵均沈湘陶令死，篱下寒香久无主。","江边一笑倚清秋，烂漫西风几今古。"]},{"t":"秋夕露坐作","f":"五言律诗","c":["玄天大无匹，要亦有穷处。","不知穷处外，旷莽复何寓。","茫然仰太虚，㗳尔消万虑。","规规尘网中，龌龊焉足谕。"]},{"t":"登夏时茂澄碧览翠二楼 其一","f":"七言律诗","c":["澄碧高楼三泖东，阑干如画倚江空。","风传鹤语滩声静，潮挟龙腥海气通。","万象尽沉云影底，八窗都在月明中。","抛书便作南昌梦，秋水长天一色同。"]},{"t":"登夏时茂澄碧览翠二楼 其二","f":"七言律诗","c":["越水吴山指顾中，虚檐百尺卧元龙。","都将宇宙清明气，散入江湖礧磈胸。","天末鸟飞云淡淡，海门烟散树重重。","若为借得湘妃瑟，鼓向江南十二峰。"]},{"t":"寒夜","f":"七言律诗","c":["晚云欲雪寒模糊，微月递明光有无。","枯桑林头北风急，山鬼叫啸林鸦呼。","此时柴门寂如磬，借问夫子何为乎。","一盏油灯照虚壁，梦在洙泗谈黄虞。"]},{"t":"夜半灯尽作","f":"五言古诗","c":["寒鸡声啾啾，阴墙明残雪。","推窗月当户，始闻二鼓歇。","残编有至味，鼋鼎芬在列。","夜阑烛复尽，此意谁共说。","严风逼两袖，揽衾更骚屑。"]},{"t":"雪中对客","f":"七言律诗","c":["茅屋无风已自寒，客来飞雪满遥山。","相看只合围炉坐，欲去谁能放棹还。","梅萼映空增怅望，松枝低槛故阑珊。","平生陶谷多才隽，愁绝佳人一笑间。"]},{"t":"除夜","f":"七言律诗","c":["更无柏酒共桃符，一卷离骚伴竹炉。","短褐有情怜岁月，敝冠无恙笑头颅。","白波东逝伤心远，青鸟西飞入望孤。","久卧沧江惯愁思，不将明日问荣枯。"]},{"t":"辛丑春夜闻雨","f":"七言律诗","c":["破屋寒多怯夜眠，骤闻鸣雨更欣然。","已拚窗下琴书湿，暗喜庭前草木鲜。","檐溜不齐时点点，灯花无谓故娟娟。","清时美景双惆怅，卧听淋浪百虑煎。"]},{"t":"遣兴 其一","f":"五言律诗","c":["门掩青萝月，窗含绿树烟。","咿吾閒白昼，寂寞任长年。","荒野无穷日，沧江不尽天。","伤春复怀友，怅望一凄然。"]},{"t":"遣兴 其二","f":"五言律诗","c":["绿重墙头柳，红欹谷口桃。","燕轻翻水捷，鹳暖入云高。","好景宜佳句，残尊有浊醪。","故人沧海上，相忆钓金鳌。"]},{"t":"雨不止","f":"五言律诗","c":["细雨久不止，江皋泥渐深。","出门妨散步，隐几独长吟。","柳重墙头压，苔添石面侵。","烟云方满眼，花鸟莫关心。"]},{"t":"春日将适郊外忽暴风阻行","f":"七言律诗","c":["二月六日天气恶，捲地黑风吹倒人。","却看花柳俱无色，忽讶江山不似春。","高卧野人滋懒散，欲飞燕子自逡巡。","东园有约不如意，须待来朝理钓纶。"]},{"t":"写怀","f":"五言古诗","c":["美酒新丰市，轻车洛下城。","星霜悲聚散，寒暑递枯荣。","彤管三千字，青冥十万程。","辽天来去雁，华屋短长檠。","烟柳风中乱，溪云席上横。","西山朝有气，北斗夜无声。","病得休文瘦，贫看季子轻。","几年嗟敝褐，此日笑长缨。","茅屋依江静，林花近眼明。","芊绵随绿草，怅望听流莺。","画虎将焉用，屠龙竟未成。","扁舟徒漾漾，春水故盈盈。","尚觉乾坤大，空馀梦寐清。","一枝原树鹊，百丈海天鲸。","落月愁何奈，沧洲岁屡更。","途穷滋懒钝，时屈藉幽贞。","雅郑难同调，枭鸾本异鸣。","永怀萍泛泛，敢谓铁铮铮。","遇竹时题句，逢鸥且问盟。","茂先如可作，雄剑在延平。"]},{"t":"春日杂兴 其一","f":"古风","c":["东风一梦过南园，吴水吴山兴杳然。","经雨落花还似锦，弄风柳絮不成绵。","林?夜啸空哀月，江鸟晴飞欲傅天。","处处兰桡移白昼，边生终日枕书眠。"]},{"t":"春日杂兴 其二","f":"七言律诗","c":["群山西北翠如烟，三女荒冈草树连。","瑶井鹤鸣凡几岁，碧潭龙去不知年。","潮平沪渎城头月，花落云间洞里天。","千古废兴如昨日，几回窗下掩残编。"]},{"t":"春日杂兴 其三","f":"七言律诗","c":["泛观今古不胜哀，又向江边步绿苔。","曾见楚兵回柏举，谁教越女上苏台。","君臣得失馀文史，罗绮繁华遍草莱。","最恨鸱夷五湖去，胥涛空涌浙江雷。"]},{"t":"春日杂兴 其四","f":"七言律诗","c":["千雉孤城枕碧流，晴天望远自生愁。","金羁络绎花边马，玉雾葱茏柳外楼。","何处健儿誇仗剑，几年渔父独垂钩。","白鸥飞入苍烟里，目断斜阳送去舟。"]},{"t":"环溪十咏得莼菜","f":"七言律诗","c":["秋风吹嫩碧溪莼，春韭寒菘别置伦。","入手细牵青不断，盈筐满贮绿仍匀。","许同玉脍成双美，未数金盘馔八珍。","多渴长卿愁内热，谢他清淡养天真。"]},{"t":"锦衣归钓图","f":"七言绝句","c":["天上归来锦作袍，吴江春水泛蒲萄。","傍人未识扁舟意，犹道先生学钓鳌。"]},{"t":"八月十五夜","f":"五言律诗","c":["月色好如此，欲吟谁起予。","钩帘望南极，散履下前除。","润气连沧海，浮光混太虚。","旷然心境会，端坐念玄初。"]},{"t":"秋兴和芸轩韵 其一","f":"七言律诗","c":["海峤千峰插汉齐，每因松竹问幽栖。","江山举目成图画，天地从人作品题。","身隐不妨随鹿豕，门閒应得长蒿藜。","何须绿野功成后，始是黄梁梦破时。"]},{"t":"秋兴和芸轩韵 其二","f":"七言律诗","c":["伏雨阑风日未休，越山吴水共悠悠。","鸾书不返瑶台暮，雁阵争回碧树秋。","敝褐有情依客子，断碑无主怨王侯。","平生宋玉多悲感，拟脱青衫趁白鸥。"]},{"t":"秋兴和芸轩韵 其三","f":"七言律诗","c":["碧海萦回天际还，海山青翠束连环。","铜城北望三千里，金斗西横百二关。","落月有时闻画角，夕阳何处倚危阑。","清江面面芙蓉满，安得凌波却暂攀。"]},{"t":"冬至书怀","f":"古风","c":["阴尽阳复回，年华递相促。","明灯坐深夜，长叹拊髀肉。","忆昨童丱初，未念寒与燠。","依依邻舍儿，游嬉日相逐。","九龄事书史，稍解知捡束。","十三文义通，孜孜务磨琢。","维时心尚孩，寒暴略相续。","逡巡邻弱冠，人事有颠踣。","旧业竟萧条，凄然泣松竹。","系名庠序间，晨暮恒碌碌。","夙心虽未改，奈此尘嚣渎。","翻思少日误，閒暇安可复。","今年值霪雨，积潦弥旬朔。","荒居迫沮洳，下床水没足。","鱼行仅两月，闷绝每思哭。","侵冬始安居，卒岁已无谷。","匆匆日复日，不觉流光速。","朝来日长至，推枕乃惊?。","清晨随冠冕，州衙拜黄屋。","于惟万乘尊，至德春同育。","顾兹岁小歉，圣心已烦蹙。","恭闻遣明诏，四出洗冤狱。","人和天乃应，生意岂长鞠。","惟应西江水，不及辙中涸。","归来茅屋底，寂寞对僮仆。","仰看天意愁，雨雪交相属。","侵陵及兰蕙，摧压倒松菊。","海宫东南天，一望云弥目。","傍村八九家，悄若住空谷。","往来迹已断，况乃相贺祝。","物情厌荒落，天亦恨幽独。","闭门日易暮，忽已见灯烛。","所思渺云汉，谁与论心曲。","须臾雨声歇，窗隙风簌簌。","夜久寒转严，指直不敢触。","寒炉拨残灰，邈矣拱先躅。","因思古达士，涉世多翻覆。","譬之百鍊金，历久乃精熟。","蹇予沙矿姿，敢尔恨幽辱。","顾此年岁长，便便止空腹。","烟云方满眼，何时见清旭。","维东有沧海，浩漫侵坤轴。","其上通星辰，其下连河渎。","吾将驾灵查，一访巫咸卜。"]},{"t":"海棠四首 其一","f":"七言绝句","c":["濯锦江头富贵花，何年流落海天涯。","玉人二八空闺里，岁岁因君感物华。"]},{"t":"海棠四首 其二","f":"七言绝句","c":["屑玉涂坯艳一丛，内园开处锦屏幪。","何人错认杨妃醉，泪湿春风忆梦中。"]},{"t":"海棠四首 其三","f":"七言绝句","c":["日暖风暄人意慵，海棠正向此时红。","谁云花好能消恨，花恨于人更不同。"]},{"t":"海棠四首 其四","f":"七言绝句","c":["香颊潮红亸翠襦，绛唇微吐滴胭脂。","游丝不动日停午，斜倚东风若有思。"]},{"t":"通波塘泛舟沈惟馨王大用钱时敛联句","f":"五言律诗","c":["舟出五里塘，迢迢去路长。","水花红近眼，烟柳绿成行。","茅屋依山小，汀兰拂棹香。","时时见渔父，击楫下沧浪。"]},{"t":"梦登连阁甚高敞前绕群山松影披拂檐下真异境也赋诗八句而记其半漫识于此","f":"七言绝句","c":["高阁凌虚拂紫霄，四檐轩敞接连鳌。","千岩对起龙蛇窟，两足亲登凤鸟巢。"]},{"t":"相先生具庆堂","f":"五言古诗","c":["尧日仁风遍，莱庭瑞气重。","康强惟德召，和乐自天钟。","甲第花迎户，高堂雪覆松。","伯鸾才不衒，德耀礼偏恭。","穆穆金兰契，娟娟玉树容。","纮綖催夜绩，杖屦阅春农。","景入榆林晚，甘回蔗境秾。","鞶缨晨济济，笙鼓日雍雍。","偕老无遗恨，传芳有亢宗。","已全三釜养，行遂五花封。","委曲吴江水，微茫泰岱峰。","题诗遥献寿，春色两融融。"]},{"t":"醉书","f":"古风","c":["车不避太行坂，舟不辞滟滪堆。","男儿生不履穷途，一生肝胆何由开。","君不见东鲁缊袍子，君不见南海伏波老。","二旬九食未为病，白头意气日矫矫。","英雄未遇龙蟠泥，他日何缘悔曩时。","逝将白石砺吾齿，饥来快嚼南山芝。"]},{"t":"巢云为倪举人赋","f":"楚辞体","c":["越山山人迹大奇，卜居直与浮云齐。","诛茅不畏虎争穴，拓地远教龙择栖。","初来尚嫌巾履湿，住久更觉青天低。","飞旌卷旆互明灭，松窗石榻同凄迷。","时时蒸翠落书幌，往往空青沾杖藜。","山人前年不出山，丹崖绿壑时攀跻。","半筇横绝陇头路，一犁耕破芝田泥。","今日山人振衣起，飞云万里随东西。","翻腾百川雨九土，变化岂复知端倪。","云兮能舒复能卷，世间万事如蓬转。","岩崖霄汉各有时，男儿那得长偃蹇。","作歌赠君殊短短，功成旧巢莫相远。"]},{"t":"尝瓜得麻字","f":"七言绝句","c":["旋拔霜刀剖玉瓜，清甘入口四筵誇。","凭君莫问渠家世，见说青门又种麻。"]},{"t":"待月轩为钱塘沈廷璧赋","f":"古风","c":["高轩峨峨临水开，虚檐四敞无纤埃。","主人为此兴不浅，要待嫦娥天际来。","晴空落日清如洗，远水微茫翠烟起。","清簟疏栊半捲帘，思入沧溟几千里。","沧溟迢迢天汉东，玉蟾戏水龙王宫。","清辉只尺不可睹，幽情烂熳迷云空。","有时掀髯琢诗句，乌鹊啁啾隔烟树。","长吟呼起白凤来，恨不同飞碧霄去。","有时凭阑吹洞箫，箫声幽咽惊潜蛟。","倦来梦入水精殿，寒光百道飞银瑶。","香残烛冷催更鼓，遐想苍茫极今古。","牛渚金陵夜夜天，风流百世俱尘土。","感时抚事情依依，东望蓬莱意转迷。","绕阑风露不知冷，隔水松篁应惨凄。","钱塘亦是三江地，风景寻常接宵寐。","抚卷知君信可人，不觉神飞渡江澨。","我歌待月篇，月应解我意，不用阑干苦凝睇。","少迟银桥天际起，与尔同舞霓裳队。"]},{"t":"久雨","f":"七言绝句","c":["江上痴云接地低，闭门终日看凄迷。","东园有约无由到，想见春泥没马蹄。"]},{"t":"癸卯立春日寄陆时敏","f":"七言律诗","c":["五载蓝袍触暗尘，梅花风起又新春。","漫怜司马长多病，自说莱芜已惯贫。","经雪松篁犹在眼，弄晴禽鸟渐宜人。","风光此日催诗梦，已入芳洲采绿蘋。"]},{"t":"初赴举时赋七律一首留别诸公适时敏以诗来即用其韵","f":"七言律诗","c":["同时济济尽英才，况复清朝景运开。","幸与诸公作先路，敢期三策便抡魁。","秦淮山好天开画，扬子江深地走雷。","应到高秋明月夜，思君直上凤凰台。"]},{"t":"奉饯郡守稷山王侯得凤字","f":"七言律诗","c":["南薰不入虞弦弄，两岐每詑渔阳诵。","岂知三年东海头，黍稻连云茧如瓮。","皇华问俗已知本，丹扆思贤每劳梦。","双旌此去谁能留，矫首梧冈听鸣凤。"]},{"t":"初举不第却回书所历","f":"古风","c":["潜鱼不出椮，栖鸟不出林。","不因风雷便，岂识天地之大江湖深。","天风飒飒吹黄槐，江船击鼓凌晨开。","便为万里客，岂复儿女猜。","云帆悠悠渡三泖，已觉从来双眼小。","瞥然一瞬出淀湖，使我尘襟豁如扫。","将军祠前芳草多，阴廊古瓦封苔窠。","英雄恨杀白衣橹，千载此地还来过。","陈湖北来势尤大，气象浑疑在天外。","波光黯惨迷西东，惊雷喷雪吹腥风。","同舟十人半失色，我疑此处藏蛟龙。","湖西一带风初静，呼酒开筵共相庆。","推蓬又觉眼豁然，黄天独墅天相连。","向来颠沛几不免，到此始知应自怜。","出门只尺已如此，况乃天涯千万里。","何处池塘杨柳青，谁家门巷炊烟起。","依稀渐觉风景佳，前头已是姑苏台。","夫差句践两寂寞，倡讴市语喧如雷。","扬帆径逐东风便，不尽平生游览愿。","扁舟信宿过望亭，锡山如画遥相迎。","道傍深刻十三字，千载不磨贤令名。","毗陵郭里舟初住，榆叶零零杂风雨。","綀衾独拥不成眠，是夕方知有羁旅。","丹阳自昔称畏途，我实初行兼病躯。","蹇驴登登不能止，缘崖历谷何萦纡。","日斜憩足句容道，尊酒聊将润枯槁。","当垆可是临邛人，茜裳廉纤不动尘。","人言巫山在平地，对面已隔黄姑津。","风尘浩荡催征马，西望金陵去如写。","片云飞来我已愁，顷刻滂沱遍原野。","道边茅庐大比拳，俛首急入如穷猿。","苍皇已识异乡味，帡幪始知大厦恩。","行行见说宸居近，趣马加鞭气重奋。","此时天公亦开晴，氛埃涤尽穹宇清。","中和桥上初登览，目极遥天发深感。","江山如此不早来，几向此生虚?坎。","钟山如龙云际来，石城双阙中天开。","固知传闻不虚假，神祖规模真壮哉。","长衢荡荡平于砥，井画棋分各条理。","接栋连甍如灌云，去马来轩若流水。","声华文物竞奢豪，公子王孙处处遭。","佳人总为王幼玉，将军不数霍嫖姚。","东山明月西江水，尽日寻游看不已。","细柳深藏朱雀桥，飞花暗满长干里。","自从失脚下青冥，往迹回看如败枰。","束书羞咏月中桂，鼓棹还为江上行。","长江三面山如壁，环拱金陵护宸极。","古称天堑信非虚，自是荒淫足亡国。","波平风稳帆樯健，倏忽金山当我面。","奇形秀色画莫工，信知天巧非人功。","平生梦想不可到，足慰此行樵悴容。","南徐自古雄豪地，到此令人益奇气。","惜无许浑千首诗，洗我胸中不平事。","舟行半日下丹阳，新丰美酒又闻香。","同行半是同来伴，相对不言空感伤。","搴篷径指吴门路，一片归心乱云雾。","江山不学苏秦家，风景苍苍只如故。","故园到日天已寒，江枫落叶秋斑斑。","青尊提携湛绿醑，故人为我开欢颜。","西风落日吹芳菊，共挹寒香散幽独。","困穷拂郁岂徒尔，况我霜毫未应秃。","君不见芙蓉花生江皋，秋风未至宁萧条。","又不见千里驹服盐车，霜蹄一蹶气转加。","丈夫结束自有地，肯学儿女空愁嗟。","风帘日暮展书读，炳炳丹青照人目。","临渊羡鱼知已非，呼童静掩林间屋。"]},{"t":"读庄子有感","f":"七言律诗","c":["落日平林烟雾生，西风茅屋短檠明。","书生已惜三千字，狂客犹誇九万程。","蛮触干戈神独领，蜉蝣日月梦潜惊。","旧游亦有芝兰契，冰雪何人与问盟。"]},{"t":"少年行","f":"古风","c":["驱车上太行，前有九折坂。","回车下平原，毕竟无人挽。","升高望同行，去去日已远。","及今努力尚可追，西山白日下来时。"]},{"t":"甲辰九月五日迎司马兰亭过蔡廷章宿 其一","f":"七言律诗","c":["岸侧野花香拂棹，竹间细水暗通船。","尘中已觉俱成梦，幽处真疑别有天。","红敛江村寒映日，翠浮沙市晚生烟。","平生不为耽幽兴，容易那能到辋川。"]},{"t":"甲辰九月五日迎司马兰亭过蔡廷章宿 其二","f":"七言律诗","c":["清霜未降枫先赤，紫蟹初尝菊半黄。","终岁只闻田舍乐，一时顿觉市朝忙。","清晨雁鹜盈前浦，落日牛羊满近冈。","为问东皋有馀地，便应从此作邻庄。"]},{"t":"感兴六首 其一","f":"五言律诗","c":["青皇播群品，百鸟和声音。","秋风一夜起，绕屋寒蛩吟。","四时有代谢，何况古与今。","怀哉刘文苑，高卧紫山岑。"]},{"t":"感兴六首 其二","f":"五言古诗","c":["凤凰长丹穴，不识乌与鸢。","飞飞度中州，关山郁芈绵。","文翰一震耀，百喙起纷然。","昆崙有瑶树，玄洲多玉田。","下有醴泉流，上有蔚蓝天。","谁能复记虑，一去三千年。"]},{"t":"感兴六首 其三","f":"五言古诗","c":["兀兀深夜坐，迢迢千古思。","弃我万镒宝，坐此一饭羁。","前瞻日既远，内顾心还悲。","兰荆不同长，绿发坐成丝。","彦明古烈士，谁哉继馀辉。"]},{"t":"感兴六首 其四","f":"五言古诗","c":["投鼠且忌器，爱牛搏其䖟。","事固有大体，一怒安可凭。","所以古圣哲，远览穷千龄。","岂无一决勇，而独务含宏。","斯人不可作，彼夫竟凭陵。"]},{"t":"感兴六首 其五","f":"五言律诗","c":["椿寿期万岁，龟龄亦千秋。","伤哉蜉蝣虫，朝生夕不留。","君子与众人，其道亦相侔。","计日不计年，吾生将安投。"]},{"t":"感兴六首 其六","f":"五言古诗","c":["不寐起中夜，钩帘坐前楹。","傍见松桂影，仰看江月生。","银河正无翳，万里亘天横。","晶光动左右，四闼晃虚明。","中怀正如此，安得谢尘缨。"]},{"t":"悦清为卢永清赋","f":"五言律诗","c":["岂无离群意，翛然野鹤姿。","好山时拄颊，幽涧或忘饥。","心赏丹青会，神融翰墨知。","年来渐成癖，无计得中医。"]},{"t":"古松","f":"七言律诗","c":["年来耆旧多零落，如此长松见亦稀。","劲直不随冰雪困，馨香宜得凤鸾依。","流脂化魄皆堪斸，坠子成林又合围。","好在主人封殖厚，清游留待子房归。"]},{"t":"玉扇坠歌","f":"古风","c":["天星夜坠乌玉渠，灵光化作双鲤鱼。","目光夹日摇明珠，昆冈八月秋气孤。","万夫入水群龙逋，玄鬐一跃升天衢。","金索贯颐来献俘，清风先生坐冰壶。","掀髯一笑留坐隅，被以组绶恩礼殊。","金闺窈窕连黄枢，尔我相倚出入俱。","自从倭风入中区，飘然弃予瓦砾如。","时移世变日下趋，何意更逢君子徒。","亦知所好非所须，意气相感终不渝。","河东昔感中厩驹，我歌双鱼双涕濡。","古人中人今岂无，时哉不遇索莫俛首栖寒庐。"]},{"t":"题梅花仙子图盛子昭画","f":"七言古诗","c":["烟林乌啼天未霜，落月漏云金镜光。","美人独宿九华殿，天风吹动金琅珰。","瑶阶露重侵罗袜，冻合梅梢不成雪。","翩然飞下西湖头，独傍寒香倚愁绝。","寒香郁郁愁冲冲，冰魂荡漾迷西东。","星眸欲流滴秋水，霓裳不动萦天风。","天风飒飒鸣璚玖，欲去踟蹰更回首。","武塘仙人五彩毫，偷眼方朔窥金桃。","凌晨写出一时景，清寒入面风萧骚。","苍苔粼粼白石净，空青暗滴阴崖冷。","石畔丛篁低拂云，云外疏桐落金井。","翠禽一声河汉横，辽天回首思冥冥。","云楼雾阁渺何许，冷蕊疏枝空翠屏。","美人只今游太清，武塘遗迹亦晨星。","怅望龙城梦中路，寒绡惨淡来精灵。"]},{"t":"满江红 乙巳元宵","f":"古风","c":["云月澄鲜，重城夜启。","满目繁华，正江南春早，红灯初试。","帘影千门摇粉黛，香尘十里随罗绮。","论今宵、何止刻千金，堪游戏。","欢未已，愁还继。","暗想今年，遥怜往岁。","四时相代如流水。","上林春色三千里。","望鳌山、凤辇是何年，心摇曳。"]},{"t":"送高进之入上海学","f":"七言律诗","c":["企也来时犹稚年，双髫初合未胜冠。","三冬自解攻文史，五色今看振羽翰。","人欲别时情自恶，学粗通处事方难。","重来定有惊人句，不作寻常子弟看。"]},{"t":"与曹宗魏高进之酌别","f":"七言律诗","c":["小石桥西旧草堂，故人停驾速壶觞。","相从未觉当时乐，已别方知此会良。","泼眼生红榴万点，染衣浓绿柳千行。","旧时游处今为客，怪得尊前语话长。"]},{"t":"戊申春雨书寓所壁","f":"七言律诗","c":["去年秋旱深忧稼，今岁春霖复损苗。","圣主不应天有谴，清时宁许物为妖。","浸淫便恐鱼生釜，漂泊谁将蚁渡桥。","江上舍前泥一尺，掩书终夕听飘萧。"]},{"t":"题张性夫小景四绝句 其一","f":"五言绝句","c":["寂寂空山里，春和草自芳。","隔溪人不见，髣髴唤刘郎。"]},{"t":"题张性夫小景四绝句 其二","f":"五言绝句","c":["水木阴森处，茅堂四五间。","主人容直造，携手看青山。"]},{"t":"题张性夫小景四绝句 其三","f":"五言绝句","c":["秋气著林麓，萧条门户閒。","儿童拾松子，日暮不知还。"]},{"t":"题张性夫小景四绝句 其四","f":"五言绝句","c":["积雪断山路，柴扉昼不开。","明朝稍晴霁，先看屋东梅。"]},{"t":"种桂花","f":"古风","c":["桂花分种出蟾宫，柯叶虽异根荄同。","移来植向万仞峰，天高地阔风露浓。","柯如碧琅玕，织网罥出波涛寒。","叶如蓝田玉，金刀刻成光煜煜。","吴刚有斧不敢侵，买臣睥睨停讴吟。","月来清影亦萧瑟，雨后绿叶常阴森。","我昔游广寒，面受嫦娥诀。","世间兰麝竟纷纷，天香自与凡花别。","便须和本移，不必凌风折。","眼明见此秋风前，已觉身在青云边。","还将两袖黄金粟，散作奇香遍九天。"]},{"t":"纪蝉","f":"楚辞体","c":["青林的皪珠月明，有蜩夜栖安不惊。","吸风饮露高且清，忽焉有物来相仍。","扼吭拊背施五兵，失声长号死复生。","命已绝兮犹力争，我方抚卷临前楹。","闻之恻然起再行，脩翎广颡金簧声。","须臾已复不得矜，弱肉强食神所憎。","六王已毕秦亦倾，临危欲援力不能，岂独此蜩伤我情。"]},{"t":"题宋起周扇","f":"七言绝句","c":["马头花雾扑春衣，马尾青山步步随。","归去奚童莫催促，先生得意正吟诗。"]},{"t":"阮庄为张信夫题","f":"七言绝句","c":["张郎别墅阮郎琴，千载风流此会心。","认得湖山佳绝处，绿杨窣地草堂深。"]},{"t":"过吴应文墓","f":"七言律诗","c":["弱龄随伴走红尘，青眼相看独有君。","俯仰十年嗟逝水，凄凉今日拜孤坟。","英雄有恨文章在，忠信无凭夭寿分。","下马不堪重上马，夕阳回首乱浮云。"]},{"t":"己酉西行","f":"五言古诗","c":["出门别亲友，长揖官道傍。","送者或低回，行者何慨慷。","功名来趣人，安得恋旧乡。","千金装湛卢，万斛驾艅艎。","扬帆出三泖，凌空度天潢。","挥刃斩蛟鼍，回首招凤凰。","浮云东南来，矫若游龙翔。","前飞若先驱，遥遥西北行。","西北帝王居，楼阙天中央。","年华际太平，贤俊争趋跄。","一行策奇勋，六辔驰康庄。","致君尧舜上，载歌卿云章。","夙志自耿耿，况当膂力刚。","雨过碧天净，月明仙桂香。","豪饮尽百瓠，长歌激清商。","去去君莫疑，船头起虹光。"]},{"t":"梅竹月横幅","f":"七言绝句","c":["罗浮仙子跨青鸾，午夜凌风觐广寒。","十二楼中都不寐，大家齐凭玉阑看。"]},{"t":"题扇面二绝句 其一","f":"五言绝句","c":["绿树荫重滩，平畴绕故山。","一犁春雨足，万事不相关。"]},{"t":"题扇面二绝句 其二","f":"五言绝句","c":["敲火然青竹，磨刀割素鳞。","江湖真乐事，输与洞庭人。"]},{"t":"泗泾晓发","f":"七言绝句","c":["梦醒沧江月上初，依稀听得唱吴歈。","推篷欲认停舟处，已过前村十里馀。"]},{"t":"泊七宝镇","f":"七言绝句","c":["春来三月未登山，此夜偏舟暂当閒。","怪底剑光藏不得，舟人齐指斗牛间。"]},{"t":"庚戌初度","f":"七言律诗","c":["三十年前此日中，满堂犀玉动春风。","桑弧有事羞长剑，花甲无情恨转篷。","白日啸歌天地老，青衫拜舞岁时同。","云山向晚催诗句，目断天涯没去鸿。"]},{"t":"春日杂书 其一","f":"五言绝句","c":["双翼锦䙰褷，花间任尔栖。","春来自多雨，日暮不烦啼。"]},{"t":"春日杂书 其二","f":"五言绝句","c":["日日花枝上，新声变转娇。","何如逐鸣凤，天上协箫韶。"]},{"t":"春日杂书 其三","f":"五言绝句","c":["清晨戒童子，竹户不须开。","昨夜东风恶，苍苔有落梅。"]},{"t":"春日杂书 其四","f":"五言绝句","c":["庭树谁教种，无端恼客情。","昨宵窗外雨，一半是渠声。"]},{"t":"春日杂书 其五","f":"五言绝句","c":["无事盆池畔，吹萍看藕秧。","金鱼前岁放，长得许来长。"]},{"t":"春日杂书 其六","f":"五言绝句","c":["种花种长春，君子有深意。","愿得堂上人，红颜亦如是。"]},{"t":"春日杂书 其七","f":"五言绝句","c":["凡花皆可爱，萱草更忘忧。","未必真能尔，聊将慰远游。"]},{"t":"王相之画石蝴蝶","f":"古风","c":["处士梦中幽意，美人衣上春风。","日午小轩人静，阑干伫立从容。"]},{"t":"乐归为张椿庭赋","f":"五言古诗","c":["东皇运玄化，百物竞华滋。","金商一司令，黄叶满庭墀。","大块陶我形，有合须有离。","古来贤达人，此事那能违。","桓子治石椁，三年费鑴追。","牛山感夕阳，哀伤涕沾衣。","拳拳惜馀日，欲作无穷规。","竟同草木腐，千秋有馀悲。","贤哉椿庭翁，洞烛今古非。","自言八十载，不蹈危险机。","修身慎吾行，大化从迁移。","幸此手足完，庶不惭恩私。","生乎颓然顺，死当浩然归。","陶潜拟挽歌，生与亲旧辞。","司空游圹中，酣饮仍赋诗。","二子信可人，吾今其庶几。","酌酒自为奠，告终自为词。","琅琅数百言，药石兼蓍龟。","春风动歌吹，宾从相追随。","山丘及华屋，一视了不疑。","旷然世外游，岂为形迹羁。","人生有此身，所贵能不亏。","全归见其亲，此乐知者稀。","尚怀子舆氏，易箦开衾时。","往者信自贤，来日方未涯。","愿翁劭厥德，优游过期颐。"]},{"t":"寄张拱辰","f":"七言律诗","c":["纳纳乾坤一草庐，年来踪迹半樵渔。","龙纹渐涩床头剑，鸿宝虚传枕内书。","霜后菊花香未减，月中杨柳叶全疏。","飞书欲共天公语，矫首青鸾隔太虚。"]},{"t":"秋雨三首 其一","f":"七言律诗","c":["江头雨深泥没膝，闭门十日气欲塞。","黄茅断岸景色异，正昼狐狸啸丛棘。","骑牛小儿誇惯熟，疾走鸣鞭叩牛角。","幽人拄颊楼上坐，欲拔青蛇抉云破。"]},{"t":"秋雨三首 其二","f":"七言律诗","c":["男儿不学资身策，有家不居远为客。","年过三十尚尘土，屡揖庸儿愧腰膝。","堂堂白日閒里过，可怜少年难再得。","呜呼此道亦未丧，且复临风默惆怅。"]},{"t":"秋雨三首 其三","f":"七言律诗","c":["日暮北风捲地来，柴扉无人惊自开。","黄沙飘扬击人面，起看天色如煤炱。","此时高堂坐白首，弱妻供具正奔走。","主人酌酒殷勤劝，不知客心随风乱。"]},{"t":"题柳文裔扇","f":"五言古诗","c":["峥嵘碧琅玕，上有栖凤枝。","凤凰飞不还，山鸟空愁思。","春风开野棠，绿叶含华滋。","岂无好声音，缄口芳菲时。","谅无同心人，欲语先成悲。","佳人惜芳年，壮夫怀远期。","宁能阘两翅，扑簌蒿下肥。"]},{"t":"庚戌岁暮在子南馆梦二人传呼入大门数折而东予问此何处曰内阁也方思所以应对者忽闻百舌鸣而寤以诗记","f":"七言绝句","c":["贾董才名愧不胜，皋夔事业我何情。","春风一刻邯郸路，欹枕窗前百舌声。"]},{"t":"辛亥感兴六首 其一","f":"五言古诗","c":["六籍无孔孟，诸子竞为书。","班马雄两汉，韩柳后驰驱。","斯文虽未丧，元气久已殊。","云胡后来者，每变日下趋。","靡然事华藻，琐甚雕虫鱼。","杳眇乱人耳，黄钟委路衢。","时无欧阳子，谁为扫其芜。"]},{"t":"辛亥感兴六首 其二","f":"五言古诗","c":["秦皇肆吞噬，王白亦雄哉。","汉祖仗黄钺，韩彭后先来。","仁暴虽异趋，戡定各奇才。","悠悠千载下，文胜武略颓。","貔貅百万辈，孰是长城材。","虎卧不脱爪，天行不废雷。","干羽格有苗，兹运久未回。"]},{"t":"辛亥感兴六首 其三","f":"五言古诗","c":["大运日颓下，皇风返无期。","区区二三子，乘时各扬眉。","声名动京阙，举世钦所为。","吾观古人作，举措不如兹。","悠悠叹升沉，我独伤此时。"]},{"t":"辛亥感兴六首 其四","f":"五言古诗","c":["汉王仗三尺，陆贾陈诗书。","齐客工弹瑟，其王乃好竽。","为业非不精，凿枘将焉如。","入水须操舟，陆行须驾车。","君看屠龙手，终年不食鱼。"]},{"t":"辛亥感兴六首 其五","f":"五言古诗","c":["仲淹归乡闾，荣光照江东。","散帛分族人，府藏一时空。","明年买义庄，倾橐无吝容。","向来西山下，平田正春农。","老稚各欣欣，乡里自成风。","仰止慕芳躅，咄嗟吾道穷。"]},{"t":"辛亥感兴六首 其六","f":"五言古诗","c":["急湍无漫波，高冈多烈风。","君子抱奇节，安能与时同。","譬彼松柏姿，岂杂萧艾丛。","水浊不污月，道丧身乃穷。","谁云唐虞远，大运不再逢。"]},{"t":"梦入大第若官府有冠帔如命妇者肃容出果实为礼皆大如瓜将别赠以砚其言意之委曲不能详也记之以诗","f":"七言古诗","c":["海霞流光五色烂，瑶花风吹香不断。","曲廊转入迷近远，朱帘素壁光凌乱。","青衣传言凤凰啭，云鬟十二梳未遍。","金龙水寒粟生钏，银屏窈窕深不见。","朱扉哑然开半扇，屋梁初日晃如练。","当轩揖我使我先，神清度远不敢眄。","遗我五花文玉砚，雕盘异果珠琲粲，入手光辉不能辨。","鸣鞘一声来天上，回身踏破梅花帐。"]},{"t":"题吴子南梅花扇","f":"七言绝句","c":["一枝清绝傍瑶池，消息须从雪里窥。","待得玲珑开满树，狂蜂浪蝶已能知。"]},{"t":"筠屋为徐大章季父廷美赋","f":"古风","c":["徐君爱竹如爱玉，种竹成林密如束。","林间结屋三四楹，自说此生心事足。","阑干一径曲复曲，落翠飞青暗人目。","我疑月明深夜中，定有青鸾屋头宿。","青鸾飞去久不还，满林翠羽秋阑珊。","时时一羽落书幌，清气逼人毛骨寒。","前年识徐君，倾盖即知己。","坐我筠屋中，焚香拂素几。","弹琴瀹茗终日留，知我爱君清莫比。","云萍一散雨经秋，春风想见林塘幽。","晴窗展卷对图画，使我东望心悠悠。","山林诗酒自真味，江湖风波多隐忧。","洛阳红紫易消歇，冰雪此君宜共游。","呼王猷，招蒋诩，便合屋中连日住。","明年骑鹤上扬州，碧云回首知何处。"]},{"t":"花见羞后唐明宗淑妃王氏也予读五代史感其濒死为子乞命数语故为赋之","f":"古风","c":["花见羞，问汝何时生，不得见尔面，徒闻誇尔名。","尔名至今犹在人，尔貌当时知绝伦。","花见羞，双蛾绿，出侯门，入金屋。","君王本代来，不识中州曲。","风尘一朝起，零落随马足。","随马足，事已非，果然摧眉伏沙泥。","游魂茫茫绕青冢，罗衣血染何当归。","花见羞，入黄泉，生时花应妒，死后花反怜。","花谢枝头子还结，妾死心事谁当传。","君王墓草埋寒烟，春风麦饭洒谁边。","花见羞，恨千年。"]},{"t":"赋得碧甃寒根寿胡友松","f":"楚辞体","c":["曲廊阴阴清昼閒，砌台乱匝苔花斑。","苍龙何年蜕寒骨，化为古松根屈蟠。","百折不能去，回戈折戟相撑住。","突然奋起石为裂，散作孙枝不知数。","坚刚不容蝼蚁穴，正直默有神灵护。","主人自是华阳仙，双瞳碧色耳垂肩。","平生丘壑有深癖，爱此松根时醉眠。","薰风四月日正长，松阴满庭天气凉。","我来寿君劝君酒，摩挲铁石龙鳞香。","松兮岁久根益深，流膏渗乳日侵浔。","更千年后重相寻，为君斸取根下苓。","采花酿酒共君斟，飘然轻举紫山岑。"]},{"t":"夜泊凤凰山闻鸟啼有感","f":"七言古诗","c":["吴蚕三眠欲上山，吴禽夜啼吻欲乾。","啼言摘山须看火，天欲明时啼更苦。","伤弓伤虎人物同，此鸟前身是蚕女。","青楼美人红锦帷，歌舞归来月已低。","银釭斜明照春睡，问著摘山浑不知。"]},{"t":"节庵","f":"古风","c":["君不见徂徕松，四时不改叶。","又不见淇园竹，青青傲霜雪。","借问二子何能然，信是平生有奇节。","男儿意气干云霓，草庐抱膝龙蟠泥。","庙廊不改岩穴操，事在他时人未知。"]},{"t":"同以祥赴试过张性夫宿 其一","f":"七言绝句","c":["水底鸡鸣事有无，琉璃千顷浸浮图。","眼中便觉尘嚣尽，他日何烦去五湖。"]},{"t":"同以祥赴试过张性夫宿 其二","f":"七言绝句","c":["落日放舟三泖西，红霞碧浪树参差。","辋川风景还堪画，唤取王维共赋诗。"]},{"t":"同以祥赴试过张性夫宿 其三","f":"七言绝句","c":["梦破沧洲明月低，水村依约有鸣鸡。","江神借我天风便，墙柳枝枝尽向西。"]},{"t":"枫桥望虎丘","f":"七言绝句","c":["阖闾葬后三千岁，霸气销沈虎亦亡。","留得当时旧园寝，重重楼阁祀空王。"]},{"t":"为阮大经题画二首 其一","f":"七言绝句","c":["万里龙沙隔五湖，朔风吹雪点黄芦。","题诗为问沙头雁，来日天骄款塞无。"]},{"t":"为阮大经题画二首 其二","f":"七言绝句","c":["单于羊马汉臣衣，泪洒西风日暮时。","千岁子卿终不死，白头知为李陵悲。"]},{"t":"试后待榜题桂花期顾时亨次舜和韵 其一","f":"七言绝句","c":["花发年年自有时，往年空恨得花迟。","长安归路天香满，唤起黄筌写折枝。"]},{"t":"试后待榜题桂花期顾时亨次舜和韵 其二","f":"七言绝句","c":["忆从年少看花谱，数到红梅已厌迟。","入手天香笑今日，秋风己过第三枝。"]},{"t":"为任芸轩题画兼以识别","f":"七言古诗","c":["先生家住南村头，草堂占绝林塘幽。","阴森竹树交户牖，屏居终岁忘春秋。","家藏旧书三万轴，子孙百世犹堪读。","渔乡松乡及薇庵，后先声价遥相属。","先生读书不为名，春秋四十犹閒身。","弹琴赋诗足真趣，壶矢终日留佳宾。","晴窗时临硬黄帖，铁画银钩照箱箧。","广平老宋何足誇，高意直与钟王接。","新编古制收不遗，珊瑚宝树琅玕枝。","人言一字不充饱，先生把玩恒忘饥。","鲰生忝是龙门客，十载过从如一日。","天风吹人不得留，只尺遂成千里隔。","离筵示我古画图，画景彷佛南村居。","青山九点遥相映，浅水平桥接芳径。","桥上人来知为谁，安丘横云远莫定。","山林朝市不可偕，临图使我心悠哉。","便须立效报天子，还此同歌归去来。"]},{"t":"河间道中遇雪次何汝诚韵","f":"七言绝句","c":["冒雪登车倚酒酣，日高犹自怯风严。","不须更问春消息，已有天花压帽檐。"]},{"t":"陆孝子刲股辞","f":"楚辞体","c":["儿有身兮母之遗。","母疾之殆兮儿生何为。","身死母可代兮儿甘如饴。","残吾身兮寸肌。","免吾亲兮阽危。","孝哉陆生兮人子之仪。","吁嗟生兮当此时。","目见母兮身不为儿。","儿肌断兮母不知。","母命以续兮肌复滋。","嗟生之孝兮于古稀。","彼鄠之对兮理固宜。","情迫于中兮拟议安施。","仁有杀身而成兮身今在兹。","毁以易亲死兮又何惜，夫此而嗟生之孝兮今谁继之。","持以奉吾君兮千秋万岁其无亏。"]},{"t":"朱孺人哀辞","f":"楚辞体","c":["有美人兮山之中，潜玄室兮翳贞松。","明镜掩兮虚夜月，尘机断兮悲秋风。","思夫君兮往日，谐琴瑟兮商宫。","怀德音兮意难穷，怅泉台兮路几重。","良人恸兮惋切，嗟别路兮音尘绝。","升空堂兮迟迟，俨履綦兮成列。","惟勤劳兮未偿，怀贞淑兮心菀结。","凉风动兮中闺，纷綷縩兮罗帏。","知百年兮终尽，羌触物兮增悲。","托文词兮发潜辉，有知无知兮慰尔思。"]},{"t":"辰庆堂辞为赵叔鸣赋","f":"楚辞体","c":["翁生之岁兮龙丽天门。","龙周于天兮挟公子以凌云。","翁寿而燕兮捷书在阍。","翁举觞兮酹苍旻。","纷重拜兮罗众宾。","嘅人生兮不齐，哀夭贱兮纷纷。","孰吉昌兮参会，将厚德兮通神。","淮之南兮江之浒，柳藏其门兮花映其庑。","翁作堂兮承帝之嘏，翁燕而喜兮式歌且舞。","堂之构兮嶙峋，巩厥址兮惟千春。","我作歌兮告尔后昆，尔燕而聚兮无忘尔世勋。"]},{"t":"东山辞","f":"楚辞体","c":["岁峥嵘兮白日驰，朔风晨起兮霜雁飞。","长河千里兮愁欲断，公何为兮忽言归。","挽公兮屡撝，怅别公兮见何时。","渺渺兮寒江，心眷眷兮欲安施。","惟人生兮悦贤，孰憎爱兮予私。","抗予章兮天阍，指肝膈兮敷陈。","忱恳切兮臣志，沛汪濊兮天之恩。","忽东山兮回首，渺白云兮孤村。","别来兮几时，丛桂枝兮轮囷。","顾幅巾兮犹昔，莞一笑兮忘言。","公将行兮裴?，俨东路兮骖騑。","忽回瞻兮天阙，思承恩兮赤墀。","惟人生兮不常，嗟终始兮多违。","不竟兮公施，以张兮世维。","熊蹯兮鲂鲤，审吾择兮奚疑。","荆之山兮湘之江，我思公兮道阻且长。","总羸马兮东路，忽西崦兮斜阳。"]},{"t":"兰谷辞为黄时雍尊人赋","f":"楚辞体","c":["兰之生兮于彼空谷，抱幽贞兮不群以独。","白石兮清泉，纷紫茎兮冒寒。","渌兰之香兮扬扬，汎光风兮朝阳。","谷无人兮自芳，谷有人兮吾与子兮徜徉。","谷中之人兮清且真，不可见兮徒名闻。","仰丹崖兮千仞，思委佩兮江滨。","折芳兮谁赠，羌云路兮愁人。","抚瑶琴兮叹息，长寄情兮斯文。"]},{"t":"石淙辞","f":"楚辞体","c":["山之石兮孱颜，飞淙交兮石之间。","龙跃兮虎斗，砰雷击兮云翻。","寻源兮何处，望极浦兮扬澜。","碧之鸡兮金之马，点苍纷兮高下。","众壑兮争流，指沧溟兮一泻。","舟万斛兮鸿毛，群龙乘之兮以变化。","繄山川之伟绝兮，宜夫子之挺生。","起一邦而天下兮，亦足称其神灵。","京江既已改筑兮，犹眷眷乎兹土。","颍峨嵋、吴蜀山兮孰云今之非古。","石弗泐兮淙弗枯，散为江海蒸为霖雨兮润八区。","吾诚不测夫子之妙用兮，固将等廊庙于江湖。","渺南云兮万里，长寄兴兮桑弧。"]},{"t":"乐间园为同年夏如山赋十二首 其一 仁高峰","f":"楚辞体","c":["天之德兮曰仁，山得之兮镇厚坤。","既雄秀兮又以尊，抚众壑兮如儿孙。","千花兮万卉，吾与尔兮长春。"]},{"t":"乐间园为同年夏如山赋十二首 其二 仙游洞","f":"楚辞体","c":["群仙游兮大罗，时憩息兮岩之阿。","玉柱兮金窗，俯洞庭兮烟波。","忽中宵兮月上，听泠泠兮空歌。"]},{"t":"乐间园为同年夏如山赋十二首 其三 漫兴亭","f":"楚辞体","c":["漫吾出兮周星，忽归来兮亭以成。","嗟平生兮万事，亦何择兮何营。","偶欣然兮终日，孰久近兮千龄。"]},{"t":"乐间园为同年夏如山赋十二首 其四 独憩台","f":"楚辞体","c":["思美人兮不来，步石径兮生青苔。","聊升高兮骋望，揽桂枝兮徘徊。","晴天兮万里，见一鹤兮飞回。"]},{"t":"乐间园为同年夏如山赋十二首 其五 惠脉清流","f":"楚辞体","c":["泉何为兮此流，湛清泠兮岩之陬。","洗京洛兮缁尘，玩濠梁兮浮鯈。","渺真源兮何处，望龙山兮落日幽幽。"]},{"t":"乐间园为同年夏如山赋十二首 其六 涧湾略彴","f":"楚辞体","c":["路转兮山回，望幽岩兮阻深隈。","忽凌空兮飞步，振予策兮丹台。","愿镌崖兮有纪，步灵踪兮天台。"]},{"t":"乐间园为同年夏如山赋十二首 其七 天香屏","f":"楚辞体","c":["结湘筠兮玲珑，交桂枝兮隐隐丛丛。","玉叶兮金英，来清芬兮远风。","将书香兮此类，嗣云仍兮无穷。"]},{"t":"乐间园为同年夏如山赋十二首 其八 岁寒径","f":"楚辞体","c":["竹柏兮成林，中一径兮静以深。","谢红紫兮春阳，饱风霜兮重阴。","怀佳人兮怅望，将千载兮同心烂。"]},{"t":"乐间园为同年夏如山赋十二首 其九 柯枰山","f":"楚辞体","c":["中人兮不归，樵柯烂兮闾里全非。","嗟人生兮几何，奄夕曛兮朝晖。","神仙兮戏予，拂苍珉兮渺遐思。"]},{"t":"乐间园为同年夏如山赋十二首 其十 观鱼处","f":"楚辞体","c":["圉圉兮洋洋，忽吾止兮濠之梁。","绿藻兮青蘋，与尔游兮两忘。"]},{"t":"乐间园为同年夏如山赋十二首 其十一 虚白书舍","f":"楚辞体","c":["室无尘兮更明，晏独处兮憺以清。","左瞻兮右仰，诸史兮群经。","聊逍遥兮永日，孰宠利兮荣名。"]},{"t":"乐间园为同年夏如山赋十二首 其十二 迥碧山房","f":"楚辞体","c":["隐吾屋兮山之东，仰仁高兮一径潜通。","有芭蕉兮夏绿，更芙蓉兮晚红。","忽夕阳兮云合，倚阑干兮意万重。"]},{"t":"画水辞庚辰六月礼部南斋作","f":"楚辞体","c":["群山兮东倾，百川兮与俱。","昆崙兮万里，渺东极兮归墟。","龙门兮三峡，屹峥嵘兮喷鞺鞳。","奠九服兮常宁，疏万派兮终合。","展瑶签兮拂霜藤，目窈窕兮耳泠泠。","江南兮春尽，蘼芜绿兮枫青。","思美人兮何处，抚朱弦兮空复情。"]},{"t":"题画梅 其一","f":"七言绝句","c":["四百峰头霜气横，玉尊零落翠禽声。","寒绡三尺对虚牖，髣髴松林残月明。"]},{"t":"题画梅 其二","f":"七言绝句","c":["江南见梅只是梅，燕山见画殊依依。","西垣夜半草堂梦，青子绿阴雏燕飞。"]},{"t":"送使山东","f":"七言绝句","c":["春云拖影拂轺车，南出都门候吏趋。","两岁青齐仍苦旱，带将甘雨洗焦枯。"]},{"t":"和听鹤亭联句韵送毛太史维之归省","f":"七言律诗","c":["夜闻东壁饯文星，晓起西堂乍酒醒。","未许馀光分末坐，空吟佳句入无形。","歌停渭柳仍翻调，舞爱皋禽拟著经。","更与玉堂添故事，未应寥落叹槐厅。"]},{"t":"午日昭应宫送陈深渊得兽字","f":"五言古诗","c":["危弦激清湍，奇香袅金兽。","佳辰良友集，高宴启清昼。","维时值升平，四郊息烽堠。","缙绅多暇日，遨赏遗俗旧。","况兹金玉人，声价儒林右。","十年期破的，一矢尚虚彀。","于焉送将归，不饮复何有。","薰风晚更起，叠嶂远仍秀。","遐观穷八纮，醉舞翻两袖。","区区蛮触争，琐细安足究。","尚怀禹稷心，未忍苍生瘦。","往者勿复云，来日知未后。","三年家政成，洗耳明光奏。"]},{"t":"送同年周时敏归安陆","f":"七言古诗","c":["男儿意气淩四方，结发万里期翱翔。","槐黄催赴观国光，手携尺书朝帝王。","帝曰汝贤留我傍，往视予宰铨才良。","红帘粉署夏日长，峨冕吁咈谈虞唐。","白云飞来经太行，翩然归思不可当。","帝恩旷荡真无疆，汝暂释事归故乡。","都门朝日天气凉，束装出祖驱骕骦。","关吏旧识趋路将，举鞭挥手振紫缰。","眼中已见荆山苍，男儿名成拜高堂。","人间此乐殊未央，九重待补龙山章。"]},{"t":"送秦国声归省","f":"五言古诗","c":["天上秋光近，人间乐事并。","华轩启澄霁，高宴接恩荣。","鹤寿元无算，鹏飞始发程。","云霄遂归志，闾里溢欢声。","袅袅风生坐，娟娟月傍楹。","酒来吴市美，茶瀹惠泉清。","瓜果纷前馔，诗篇罚后成。","有阶堪报国，随寓足陶情。","绿竹宜镌字，丹台早注名。","他年佐觞豆，应及海波平。"]},{"t":"送朱良翊","f":"七言律诗","c":["翩然聚首忽言归，立遣奚童趣赋诗。","千里畏途当赤日，十分清兴寄乌丝。","贾生世共知才大，李广人犹恨数奇。","悬榻故人专有待，飞腾应不后明时。"]},{"t":"送周兵马之金陵","f":"七言古诗","c":["将军宝剑双龙鳞，锦衣红蹙绣麒麟。","甲第东华接诸贵，楼船南国隘通津。","干戈万里风尘静，两都冠盖如云盛。","朝出长干访原涉，暮入乌衣过剧孟。","书生昔未试吴钩，悲歌三入凤台游。","醉拔霜毫赠君别，三山落日不胜愁。"]},{"t":"送盛斯徵归娶","f":"七言绝句","c":["柳色衣裳玉色鞭，看花归去又逢仙。","黑头事业须君做，洞府星桥别是天。"]},{"t":"夜雨","f":"五言绝句","c":["蓟北雨连晓，江南定若何。","还应碧窗里，灯影暗银荷。"]},{"t":"秋夜叹","f":"七言古诗","c":["银河流光湿垂地，高梧滴露浓如洗。","城头击柝城下杵，幽人已卧中夜起。","东院西院无人声，星下草间蛩对鸣。","一星起来对吴分，恨不从之觅乡信。","诸君走马长安陌，肯信中宵此中立。"]},{"t":"新秋即事","f":"五言古诗","c":["暮雨残暑尽，官居清可挹。","疏栊捲秋幔，流盼伫危级。","温凉四时异，心会各有入。","鸦啼烟树寒，露下银床湿。","抚景怀昔贤，兹地几翔集。","新凉信可爱，雨霰行且及。","愿言惜芳时，功业期早立。"]},{"t":"拟中元谒陵","f":"七言律诗","c":["玉座秋风动紫宸，寝园时祀敕亲臣。","云屯松梓衣冠集，月照庭楹俎豆陈。","天地有灵钟王气，山陵终古享精禋。","词臣欲献甘泉赋，指日皇舆驾翠麟。"]},{"t":"登第后寄所知","f":"七言律诗","c":["春风逐伴上金台，便著青衫未得回。","夜听玉龙官烛冷，晓趋丹凤御香来。","匡时未展江湖志，饱食频惊岁月催。","翘首碧云南国路，美人谁在读书堆。"]},{"t":"送刘文瑞","f":"七言律诗","c":["青袍白马日纷纷，何处秋光忽送君。","天地百年同逆旅，风尘此地独离群。","时平宰相精求士，朝暇将军总好文。","去去江湖莫淹久，有人虚席仰多闻。"]},{"t":"奉饯定庵张先生之南台","f":"七言律诗","c":["四历雄藩秉宪旄，荐更三府肃铨曹。","文章旧是南金重，风节遥淩北斗高。","舆论只今推宋璟，空群他日想方皋。","两京均逸天心在，莫向霜台梦午桥。"]},{"t":"夜坐 其一","f":"五言古诗","c":["仙都閟灵境，假日休官程。","高斋坐来久，夜景湛虚明。","起步视天宇，旷然遗世缨。","素心适有会，幽兴顿此生。","沧波望不极，落月金盆倾。"]},{"t":"夜坐 其二","f":"五言古诗","c":["遥遥天汉津，耿耿横太清。","招摇运珠斗，时节忽已更。","感此念昨日，凄然思友生。","群聚不知乐，已别始牵情。","人事与日长，后期焉可凭。"]},{"t":"明妃和汪抑之 其一","f":"七言绝句","c":["汉朝翁主半家人，临到王嫱国论新。","解道怀戎尚忠信，庙堂谁谓少谋臣。"]},{"t":"明妃和汪抑之 其二","f":"七言绝句","c":["宣王六月驾戎车，武帝旌旗万里赊。","独以一身宁四海，明妃何恨泣琵琶。"]},{"t":"杨妃","f":"七言绝句","c":["汉家妃子度金微，裂面西风损黛眉。","教得后来人解事，只从金屋抚番儿。"]},{"t":"题画送胡友松","f":"七言律诗","c":["画里看山惜别离，松间立马醉题诗。","伏波老去心犹壮，太白狂来酒不辞。","云日九重丹凤阙，风烟千顷白鸥陂。","归舟正及鲈鱼信，应对西风有所思。"]},{"t":"记蝎","f":"五言古诗","c":["读书心二三，耳闻窗蝎走。","捲纸濡馀膏，火起蝎在牖。","抑首伏不行，翘尾若有候。","人言蝎易得，此意殊未究。","怀毒乃忘身，祸起遂莫救。","柳州怜蝮蛇，释械低予首。","因诗戒宵人，阴贼恒反受。"]},{"t":"海屋添筹","f":"七言律诗","c":["沧海尘飞是几秋，北堂花甲数方周。","试寻孝子无穷意，尽下仙人未了筹。","红日傍檐晴可爱，绿萱当砌足忘忧。","只应尽醉长春酒，同送飙轮过弱流。"]},{"t":"秋夜读书","f":"五言古诗","c":["高秋净炎暑，官居若蓬瀛。","落日人吏散，琴书有馀清。","烛至童子去，抚卷临前楹。","仰窥羲皇秘，俯探周孔情。","下上千万年，历历指掌明。","自从大道丧，圣哲希复生。","幸此未坠地，庶以开吾懵。","稍稍庭叶下，凄凄草虫鸣。","初月上东垣，露草光晶荧。","清景与心会，宵眠竟无成。","微吟倚青琐，天风起松声。"]},{"t":"初预丁祭","f":"五言律诗","c":["北阙初鸣佩，东胶肃展仪。","感深思坏木，喜极预承齍。","江汉神如在，山龙服俨垂。","自今期秉德，无愧骏奔时。"]},{"t":"玉堂对月","f":"五言古诗","c":["万古此明月，流看属吾人。","人生见月时，欢寡愁日频。","眷兹玉堂署，清切近帝宸。","金铺启澄霁，光景何鲜新。","古人去日多，后来浩无垠。","而我于其间，渺然凝心神。","不有通夕玩，奈彼风雪辰。","茫茫太无中，置此冰玉轮。","荧光载灵魄，终古如环循。","闻有丹桂树，婆娑映天津。","复有乘鸾女，炼药司大钧。","愿从乞刀圭，驻此尘土身。","青冥无终极，怅望徒逡巡。","人生会有役，玩物丧乃真。","掩扉送馀辉，朝车已辚辚。"]},{"t":"送陈邦直赴西安","f":"五言律诗","c":["千古关中郡，山川号上游。","俗馀周日化，地重禹书州。","别驾聊伸骥，长才类解牛。","词林有遗派，嘉绩会先收。"]},{"t":"送何溥之西川","f":"七言律诗","c":["西望蜀川千万山，美人莲幕暂栖鸾。","云连剑阁春前度，天近青城雪后看。","今日筹边宜得士，古来行道不论官。","务閒好课戎郎学，拭目秋风振彩翰。"]},{"t":"沂州谷生尝从张友山学能诗善医工画梅家有园亭之胜比自京师还同馆陈君德卿作云山别意诗以赠邀予同赋","f":"古风","c":["亭亭空外云，蔼蔼云中山。","云山苍茫自今古，江湖游人时往还。","黄金台前杨柳枯，奚奴青丝提玉壶。","挽君征骖酌君酒，握手目送飞鸿孤。","花光三昧传者少，山翁老去谁同调。","一命常怀拯溺心，十全每奏回生效。","长安车马日逢迎，五侯七贵皆知名。","拂衣东去不返顾，何异黄鹄摩空征。","舞雩坛前春信早，园亭尽说君家好。","肩舆何日径敲门，坐咏云山藉芳草。"]},{"t":"次韵答张拱辰 其一","f":"七言绝句","c":["张籍经年病卧家，纷纷九陌自繁华。","春风为遣江南信，拂杀龙泉旧剑花。"]},{"t":"次韵答张拱辰 其二","f":"七言绝句","c":["中朝文献几名家，每见殷勤访国华。","尽有声名动京邑，未应消瘦学梅花。"]},{"t":"奉饯圭峰董先生之南京","f":"七言律诗","c":["秩宗分务简元僚，学士声华重本朝。","辍讲暂违东殿直，移家初听下江潮。","西风燕市柳条短，春日金陵物色饶。","莫倚官閒疏献纳，左垣踪迹未全遥。"]},{"t":"东洋","f":"五言古诗","c":["东南百川会，入海不复返。","茫洋天地间，今古无潦旱。","吾观玄化初，一气亦微婉。","刚柔相荡摩，积润成浸灌。","天地且有穷，海波宁无岸。","常思淩天行，会应得奇观。","王生东海居，兹兴知不浅。","迟予驾飙轮，携尔出汗漫。"]},{"t":"同年胡镇之挽诗","f":"五言律诗","c":["天道由来远，人生定可疑。","如君便长已，造物竟何为。","旅殡僧房启，科名墓石垂。","九原风雨夕，肠断脊令诗。"]},{"t":"送薛平甫","f":"五言古诗","c":["岁暮行旅稀，官河断舟楫。","朔风吹狐裘，征旆向空揭。","念我同乡彦，孤怀耿冰雪。","南宫既联镳，北门亦并辙。","清词与妙句，脱口人竞说。","方需丽泽资，胡尔当远别。","男儿四方志，岂不在京阙。","顾彼西山景，幽衷日千结。","一行遂素心，万里若踰闑。","因君感予怀，揽辔剧中热。","行尘望欲尽，归意更骚屑。"]},{"t":"送吴南仲","f":"七言古诗","c":["去年放舟过垂虹，霜露尽降湖波空。","三高祠下拂苍石，长啸宇内生雄风。","此时闻君未相识，指点烟芜问君宅。","今年君归我留此，却望江南动颜色。","君才自是当世资，暂蹶霜蹄何必疑。","名场声价蔼然在，故园山水聊栖迟。","春洲二月芳杜长，芦芽抽碧河豚上。","短楫轻舠不用帆，北里南村恣来往。","东家郑郎交最投，新年闻亦理归舟。","诗筒酒榼百里近，慎勿流连负壮游。"]},{"t":"晚归即事","f":"七言绝句","c":["城头官柳绿交加，日日斜阳集乳鸦。","湖海书生羸马背，春来通算九移家。"]},{"t":"卢布政挽诗","f":"七言律诗","c":["早折宫花上玉墀，郎曹五转冠藩维。","西铨藻鉴冰霜在，南国威名草木知。","洛社几年初入会，昴精前夜忽骑箕。","薤歌不尽思贤意，落日长江起碧漪。"]},{"t":"甲寅正月七日迎驾","f":"七言律诗","c":["紫坛成礼当人日，玉佩迎銮望合宫。","辇路暗尘清积雪，御旗晴影动春风。","祥祯协应知天意，对越勤劳仰圣躬。","湖海书生瞻盛典，耻将文笔赋河东。"]},{"t":"初预庆成燕敬赋","f":"七言律诗","c":["半生湖海梦钧天，此日云霄奉御筵。","虞典孟郊神并享，镐京春燕礼无前。","黄分内酝惊殊宠，红戴宫花忆去年。","无限感恩图报意，未论文赋美甘泉。"]},{"t":"柯学士先生所种二柏树歌","f":"古风","c":["君不见刘保斋、柯竹岩，一时名声齐斗南。","文鹓孔翠赤霄上，遗迹世人争竦瞻。","玉堂之南双翠柏，传是竹岩先生手所植。","我来抚玩不忍去，树底犹疑有行迹。","忆初种来今几年，高标已见摩云天。","雨淋日炙长苔藓，虬须龙甲皆苍然。","斜阳独立双树阴，寒天老气转萧森。","丈夫有作期百世，此物岂异甘棠林。","我歌双柏篇，继彼角弓吟。","古人已恨材难用，何处悠悠语此心。"]},{"t":"送许启衷","f":"七言律诗","c":["榕阴垂绿荔支丹，五月南州画里看。","忆别况逢新岁后，赐归犹及未春残。","堂高海日明衣锦，路入乡山信马鞍。","还忆西垣镫火夜，重来不遣旧盟寒。"]},{"t":"送许启衷又二绝句 其一","f":"七言绝句","c":["一自看花入禁垣，清秋憔悴卧春残。","金茎不是君王惜，自忆家山荔子丹。"]},{"t":"送许启衷又二绝句 其二","f":"七言绝句","c":["圣代仁深远俗安，侧生无复上雕鞍。","閒居续得君谟谱，聊为南风一寄看。"]},{"t":"送周都尉告祀孝陵","f":"五言古诗","c":["明明我圣祖，承天驭华夷。","赫怒定海宇，忧勤固皇基。","典则遗子孙，万世如一时。","恭惟衣冠藏，郁郁镇地维。","云车与风马，日夕恒来思。","神灵居帝傍，监观靡有遗。","日闻寝园中，风雨尝纷披。","松柏帝所念，行列恐有欹。","玉帛命专使，洁斋代亲祠。","周侯戚畹英，寅清帝心知。","况此共欣戚，宁为跋涉辞。","都亭三月初，春光照轩帷。","祖席列群彦，载咏皇华诗。","峨峨紫金山，宫阙何崔嵬。","侍卫固有职，汎扫宜如仪。","圣情切注想，归矣无需迟。"]},{"t":"石田野色","f":"七言律诗","c":["茅屋青林映短篱，渺然西崦望东菑。","白羊不起麦平垄，黄犊閒眠水满陂。","远树每于晨雾失，短筇尤共晚晴宜。","南阳未为苍生起，风雨还闻长紫芝。"]},{"t":"毕府丞父母同寿","f":"七言古诗","c":["高槐荫庭风日清，花罗剪春香雾轻。","金屏翠帷尊两楹，门前车马来倾城。","美人一双弹玉筝，双歌南飞献长生。","凤雏衔书仪帝廷，紫鸾诏书天与荣。","瑶环涓秀瑜珥晶，书香三世连科名。","膝前拜舞綵衣明，人间此乐岂易并。","愿吹济水添瑶觥，灵椿不凋萱不零，年年珠履花间迎。"]},{"t":"戏效荆公作四首 其一","f":"五言古诗","c":["城东野意动，名园滋华芳。","弱柳黄晼晚，夭桃映新阳。","循原涉浅渚，连步陟崇冈。","兴至陈尊俎，凭高顾江乡。","生世间逸少，怀归念王章。","东游昨夜梦，川谷永相忘。"]},{"t":"戏效荆公作四首 其二","f":"五言古诗","c":["高柳骈密荫，疏篁延清风。","留客广厦宽，沈李冰壶空。","梁石介清池，绿波缘芙蓉。","日转禽语乐，幽林回短筇。","逍遥崇台上，兴入江南峰。"]},{"t":"戏效荆公作四首 其三","f":"五言古诗","c":["长林过朝雨，高堂生微凉。","帘幕含霁景，临轩送清觞。","遥岑参差碧，远浦明夕阳。","渚宫遂寂寞，登楼望川梁。","何当溯流辉，汀洲采兰香。"]},{"t":"戏效荆公作四首 其四","f":"五言古诗","c":["早寒信已严，颇得羔裘重。","起开西楼钥，坐愁长河冻。","阳和逊重阴，飞雪积危栋。","红炉照邻壁，蓝尾生怜送。","吴江万里天，媚景春如梦。"]},{"t":"东拙为舜和太史祖赋","f":"古风","c":["君不见汉阴叟，抱瓮终朝不濡亩。","又不见愚溪翁，琼琚玉佩分天工。","拙人劳力泰宇定，巧智终以灾其躬。","东城徐翁阅世久，宁为汉阴不为柳。","鸤鸠无能鹊巢坐，庄樗散木偏多寿。","才不用，全其真，功无成，贻后昆。","颓然八十馀，无怀葛天民。","古云大巧外若拙，吁嗟翁乎岂其人。","我本拙者，于时罕通，为翁作歌，仰翁高风。","丹崖青壁不可以力致，幅巾杖履想见城之东。","天子方好古，蒲车起申公。"]},{"t":"送人赴番昜丞","f":"五言律诗","c":["陈子饶阳去，抡才可是宜。","能无愧职事，应不计班资。","宦况湖头月，行装马上诗。","前途犹未晚，努力向明时。"]},{"t":"望云","f":"古风","c":["青天多白云，游子嗟别亲。","白云飞扬随处见，极目亲舍徒伤神。","徒伤神，情何极，一回仰天一沾臆。","春风绿酒金台前，恨不随云堕亲侧。","云可望，不可攀，但愿亲寿如南山，又如长江东注之波澜。","富贵有时来，难驻惟朱颜，亲年无恙百事閒。","劝云一卮，祝云南飞。","向我高堂前，荫我椿树萱花枝。","无使秋霜容易凋华滋，游子西风江上归。"]},{"t":"送徐都阃归宜兴","f":"七言律诗","c":["五色春衫拂地垂，东门高宴驻旌麾。","旧来仲郢人知少，欲去玄成马上迟。","红叶巧当官路坠，白云长傍禁垣移。","鲤庭桃李春阴在，却愧杨生后赋诗。"]},{"t":"送王参政庆贺还河南","f":"七言律诗","c":["流电光中玉佩趋，鸿胪当仗赞嵩呼。","瞻天旧识威颜近，分陕新兼体貌殊。","北阙朝辞云拥陛，东门秋饯士倾都。","雄藩尚有宣房虑，何日玄圭协禹谟。"]},{"t":"读书有感","f":"五言古诗","c":["良宵可虚掷，明镫了残书。","开卷对古人，已隔千载馀。","精神方尺间，恍若倾盖初。","共惟德业光，照耀流中区。","藐予嗣前绪，十年事菑畬。","惜哉无良耜，终亩多薪樗。","幸逢明圣朝，挟册随冠裾。","纷纷杂纂组，琐琐雕虫鱼。","白日无留光，西飞若飙车。","凉风振高树，落叶满庭除。","念此不能寐，摄衣起踌蹰。","盛年无再至，驽驾不可虚。"]},{"t":"送屠都宪元勋巡抚蓟州等处兼督边关","f":"七言律诗","c":["玉节朝辞出凤楼，朱旗遥映塞垣秋。","宁边旧属西台重，当宁今无北顾忧。","铃阁春风閒卫戟，海山晴日动轻裘。","极知根本须才杰，未为还朝是黑头。"]},{"t":"周世贞父六十","f":"七言古诗","c":["海山金桃几年熟，天台灵源流水速。","仙翁六十自世间，老圃西风终日閒。","凤雏衔书赤霄上，五彩朝阳烂相向。","云中有路不可归，春酒盈尊独惆怅。","瓢笙四管寸脍鱼，咀羊城下梅花初。","锦衣他日拜家庆，人看相如驷马车。"]},{"t":"琅琊书屋为石秀才赋","f":"古风","c":["醉翁去来三百年，琅琊山水仍依然。","林芳谷秀谁管领，石家书屋僧庐偏。","主人读书少谐俗，文章往往追古贤。","山中风月足吟弄，世上富贵从推迁。","连连冈阜拥檐牖，郁郁竹树留风烟。","晴猿昼啼白云下，独鹤夜叫长松巅。","冥搜得意或拊几，感慨双涕时沦涟。","悠悠宁逐蠹鱼尽，兀兀已觉筌蹄捐。","君不见玉屏峰南瑁湖上，我家旧屋临清涓。","绿萝摇春拂窗户，纸屏竹几清且便。","十年栖迟不谓好，一日怅望空云天。","终南少室非我有，东华尘土劳鞍鞯。","劝君及时须行乐，豪杰未有终林泉。"]},{"t":"文武传芳为李惟中郎中父寿","f":"七言古诗","c":["公家奕世龙韬学，已会风云取高爵。","百年海宇烟尘清，又向雷门见头角。","峨嵋剑阁横金天，西连草堂锦水边。","雄豪秀润各有得，公独于此当其全。","西风使节相如归，公呼诸孙候江湄。","遂开高堂称寿卮，锦衣前拜绣帽随。","熊罴鹓鹭各有姿，邦人来观啧相语。","谁似公家文更武，文谟庙堂武禦侮。","天佑公家后方钜，万岁千秋奉明主。"]},{"t":"送蒋国器","f":"七言律诗","c":["西风一夕起平原，到处羁人忆故园。","失路未须怜季子，作书方拟贺参元。","功名入手无多事，尘土留人岂足论。","记取他年说今日，冷云疏雨出都门。"]},{"t":"送汤同知督运","f":"七言律诗","c":["兖河秋水不容舠，沽口回风积万艘。","五服上供推袖领，九重深眷想贤劳。","君恩左右惭虚被，民力东南亦孔骚。","眼底白茅连瓠子，夕阳离思满亭皋。"]},{"t":"水仙扇面","f":"五言绝句","c":["银杯侧西风，罗襦不禁冷。","空江月落时，想象孤鸿影。"]},{"t":"送曾执初知嘉定州","f":"七言绝句","c":["都亭杨柳秋来短，独采黄花映别觞。","五马双旌万馀里，西风随处挹清香。"]},{"t":"九日招德卿抑之","f":"七言绝句","c":["小酌无劳折简催，自分花饵饤玫瑰。","只应免得渊明笑，两岁重阳不举杯。"]},{"t":"题戴司寇所藏张翚小景四幅 其一","f":"七言绝句","c":["岱岳东南日观峰，鸡鸣遥见日轮红。","仙家应说人间世，银箭金壶漏未终。"]},{"t":"题戴司寇所藏张翚小景四幅 其二","f":"七言绝句","c":["一色沧波浩渺间，人言此外有三山。","莫欺只尺生绡里，多少楼船去不还。"]},{"t":"题戴司寇所藏张翚小景四幅 其三","f":"七言绝句","c":["老翚笔意师观远，怪石长松气凛然。","四十年来真迹乱，夕阳红树满山川。"]},{"t":"题戴司寇所藏张翚小景四幅 其四","f":"七言绝句","c":["斗帐无风铁砚冰，梅花未要雪天晴。","坐来尚有关心处，时复空山折竹声。"]},{"t":"文华进讲","f":"七言律诗","c":["鹄立朱衣正殿东，炉烟飘动讲帷风。","百年礼乐逢昌运，乙夜勤劳仰圣躬。","毫末岂能裨海岳，精诚直欲感苍穹。","邠风无逸前王训，稽首钧天意万重。"]},{"t":"河浑浑","f":"古风","c":["河浑浑，发昆崙，奔驰万里出龙门。","出龙门，齧金堤，汎瓠子。","鱼鼋蛟鼍，乘时奋起。","城郭坏，丘陵颓，汉帝沉，玉马劳歌入云哀。","河浑浑，洵神灵。","我皇龙飞初，泥沙潜伏波镜澄。","皇钦事，禋孔精。","胡为乎一日骋雄悍，违天经。","奔腾荡潏，岸坼堤倾。","使行者不得遂，居者不得宁，园庐漂溺鱼鳖横。","河浑浑，下民咨。","神禹上天去，贾尉来何时。","三年青兖民亦疲，土牛楗石将恐非。","河浑浑，侧身南望劳我思。"]},{"t":"梦中得四句如咏讲筵事者","f":"七言绝句","c":["翠幕光中黼坐开，觚棱初日照春台。","缃函未启中人捧，玉辇才临正殿回。"]},{"t":"樗老","f":"古风","c":["君不见麝憎脐、鸡恶尾，又不见豹患皮、象患齿。","苏张戮辱韩白菹，全神乃在支离子。","东吴杨翁太古民，妙诀早受南华君。","尽将智巧付时辈，甘与樗栎同轮囷。","阖闾城西云水阔，南北舟航日阗噎。","春花秋月闭门看，八十年来几兴灭。","泥龟曳尾宁诧神，沟断庙尊俱失真。","万牛回首歌孔柏，少陵岂是知心人。","樗日老，翁日健，尘海桑田几回变。","人道孙枝却不如，前年选入明光殿。"]},{"t":"秦府纪善林介庵挽诗","f":"七言律诗","c":["五十飘然便挂冠，向来城府掉头看。","高踪自与鸿飞杳，短世频惊蝶梦残。","絮酒何年奠冥漠，囊金他日记汍澜。","哀歌不尽思贤意，尘海风波正渺漫。"]},{"t":"送乡僧","f":"七言律诗","c":["乾坤无物碍行踪，又送孤云入九峰。","林鹤暗惊空外锡，海鲸先报佛前钟。","金衣拂晓承新露，丈室凝尘记旧封。","应识西来祖师意，逢人莫浪演三宗。"]},{"t":"冬至朝贺","f":"七言律诗","c":["璿管灰飞宿霭消，紫宸班动御香飘。","貔貅列仗开弓剑，芝羽充廷杂佩貂。","长日光中瞻黼扆，卿云影里听箫韶。","愿言圣德同阳长，永从夔龙集治朝。"]},{"t":"乙夘正月抑之以疾告归盖有为也作春雪歌送之","f":"七言古诗","c":["昨夜西堂春梦好，已向池边觅芳草。","雪花日暮忽满城，无乃天欲留君行。","惊飞乱舞不自制，黄雪冥冥直侵地。","公子城东醉未归，将军塞上愁无寐。","此时念君当别离，官河千里冰未澌。","仆夫宵装待明发，车轮凌兢马蹄滑。","旗亭呼酒强劝君，明朝望君越与秦。","丈夫结束自有地，征途药饵宜相亲。","玉河东堤旧行路，冒雪送君从此去。","无限幽怀不易论，回首西垣万银树。"]},{"t":"上苑闻鸠","f":"七言古诗","c":["春波溶溶宫柳低，春云漠漠斑鸠啼。","柳阴渐深看不见，时复数声金殿西。","青绳辇路无尘土，鸣鞘不来日亭午。","高树低枝相应呼，似惜田农望时雨。","农人望雨心如渴，鸠啼日暮声不歇。","乾明门前春气深，太液池头烟水阔。","烟水微茫连别殿，忽去还啼画楼畔。","柳密花深不再闻，时复宫壶坠银箭。","忆昨至尊亲劝农，青旂黛耜临春风。","一声此日彻天耳，碧霄几见回重瞳。","八年海宇歌太平，春田处处斑鸠声。","绿秧刺波桑椹青，却忆江南村落行。"]},{"t":"春雨","f":"七言律诗","c":["麦苗侵垄黍含滋，微雨东来似有期。","凉拂画楼分迥野，润兼红杏点清池。","丰穰竟惬三农望，造化宁于一物私。","想得宸游同众喜，彩帘高捲看飞丝。"]},{"t":"内阁赏芍药次韵二首 其一","f":"七言律诗","c":["层城紫阁对阴阴，天与名花著意深。","素瓣巧攒怜玉带，醉颜微晕侧檀心。","一时胜赏谁当继，前辈流芳故许寻。","拟和阳春歌浩态，斜阳步屧几沉吟。"]},{"t":"内阁赏芍药次韵二首 其二","f":"七言律诗","c":["紫泥封后玉堂归，阁吏钩帘午漏稀。","花事直于今烂漫，赏心犹自惜芳菲。","官厨次第传宫酝，城日参差散锦帷。","不似维扬谶金紫，年来春色满黄扉。"]},{"t":"午日即事","f":"七言绝句","c":["节物相催似转蓬，御筵仍见綵丝红。","君王未押群臣燕，先酌蒲觞寿两宫。"]},{"t":"桐隐为龚九成赋","f":"五言古诗","c":["凤凰起丹穴，不息凡木枝。","飞飞度中州，正值轩虞时。","六律既以谐，九德被弦徽。","回瞻紫山岑，青桐映朝曦。","醴泉漱其根，祥飙扇萎蕤。","一敛赤霄羽，永日共娱嬉。","由来千仞心，岂有稻粱思。","黄鹄淩紫烟，一往无还期。","云鹏六月息，荒忽经天池。","古来高尚徒，不必皆颍箕。","终南隔人世，达士供一嗤。","方寸有万里，何须裂冠緌。","我歌桐隐篇，想象卷阿诗。","君王富车马，迟尔看来仪。"]},{"t":"题扇送同年奚从之使海南","f":"七言绝句","c":["仙人乘槎南海去，祖席燕市已分冰。","把赠金陵半轮月，为君随处扫炎蒸。"]},{"t":"有草名雁来红者茎叶如鸡冠而无花得霜红甚俗呼老少年或画以贻樗翁良德南夫因赋以为寿予亦继作","f":"五言古诗","c":["凉风过林薄，众绿俱以萎。","嫣然丛苇间，见此春花姿。","物变理趋朽，化工岂其私。","老螳缘其颠，顾盼如有思。","物情怜晚荣，予亦怀安期。","因之发孤咏，持玩惜芳时。"]},{"t":"送宗都运廷威之长芦","f":"五言古诗","c":["我家东海居，目击鹾丁苦。","民劳莫如农，衣食自王土。","输官赢斗升，小大得濡喣。","溟沙列万灶，勺合尽官府。","肩箱入连仓，私鬻剪为虏。","燎薪与募直，一一挂文簿。","商课或不充，输钱为市补。","缗镪非天坠，贸易复何所。","不应为法初，乃尔自相牾。","公私两煎迫，称贷日旁午。","穷年困炎歊，肉尽继肝膂。","坐令兼并徒，旦暮收拾伍。","微文牵积弊，鱼烂不可举。","常思桑孔意，宁料遽如许。","必逢忠爱士，重为整机杼。","宗君沧州行，倚任切当宁。","北南虽殊风，物久理同蛊。","执炎思冷风，久亢觊霖雨。","便文止须臾，垂名动千古。","予言未可穷，君行念靡盬。"]},{"t":"送同年施亨父令固始","f":"七言律诗","c":["霄汉初分列宿光，固陵回首是桐乡。","驿程到日齐封尽，乡信回时郢树苍。","莫以官曹殊内外，直须政事抚流亡。","老成人物经纶手，遴选应无负庙堂。"]},{"t":"送沈良臣赴南雄守","f":"七言律诗","c":["南安旧俗思张守，又喜南雄得使君。","五岭封疆元不改，三吴人物并能文。","香凝画阁晨听事，风捲朱旗晓看耘。","正使勋名照青简，未须违远叹红云。"]},{"t":"南雄北界南安民以负担为利数起争焉张公汝弼守南安为正疆界而二邦之讼息故诗语及之秋郊观稼","f":"古风","c":["金天高迥霜日晶，原田靡靡黄云平。","老农携馌坐田首，梨枣缀树光晶荧。","儿童笑呼驱鸟雀，落日村巷多欢声。","我行按辔为助喜，感叹欲去还徐行。","前年江南雨连月，百谷烂死秋无成。","去年山东仍苦旱，塍尾兆坼横庚庚。","室中啼呼道傍卧，岂有束穗酬深耕。","今年丰稔信可乐，却思旧日还心惊。","茫茫禹甸极四海，安得是处皆丰盈。","君不见紫瑶草，俱长物，惟有丰年妇子宁。"]},{"t":"徐希曾母寿六十","f":"七言律诗","c":["天上春衣绚綵霞，庭前慈竹间黄花。","仙家岁月看初遍，圣主恩波未有涯。","青镜自知双鬓在，玉梭曾度五更赊。","遥知孙子称觞罢，犹自从容问鹿车。"]},{"t":"嘉兴蹇贰守六十得子","f":"七言律诗","c":["青雀东飞入海云，梦熊新兆协生申。","天将福胤怡眉寿，人向箕裘卜世臣。","那用铅砂还汉鼎，直须花甲度庄椿。","无由共酌鸳湖渌，一睹天家五色麟。"]},{"t":"题画送李大尹","f":"七言绝句","c":["云白天青映海山，使君花县白云间。","山中老稚收成毕，齐望双凫日下还。"]},{"t":"冶斋先生挽诗","f":"七言律诗","c":["猎猎红旌动驿舟，萧萧行李不禁秋。","盐梅已觖苍生望，樗栎虚惭药笼收。","圣眷有隆馀恤典，国谋谁与记先忧。","西风一掬羊昙泪，东去遥添逝水流。"]},{"t":"挹泉","f":"五言古诗","c":["寒泉出幽谷，上有长松林。","我行林谷间，毛发增萧森。","脱缨不忍濯，竟日临清深。","清深堪娱嬉，感彼潢污池。","当其在山时，泓澄亦如斯。","皓质本易涅，素心亦难持。","谁能幽谷里，相对弄珠玑。"]},{"t":"城南别墅","f":"七言律诗","c":["梦里南徐漏未残，角巾回首便商颜。","傍村花竹多侵市，背郭亭台远见山。","身世百年云变尽，功名千古鸟飞还。","寻常诸杜频来往，赌酒敲诗亦未閒。"]},{"t":"送方与义赴资阳得读字丙辰斋居作","f":"七言古诗","c":["阳精行天明四目，孽狐潜形狡兔伏。","太微郎位发光润，万里炎荒起迁逐。","平生未识晋鄙阳，邂逅幸饯忠州陆。","男儿有身许家国，风波雨云随反覆。","资阳虽远实壮县，次第皇恩此牵复。","古来直躬多坎坷，毕竟纲常系吾属。","眼前琐细犹不弃，如君岂合长碌碌。","天衢峥嵘岁华尽，车轮宵脂马晨粟。","峨嵋西南望松桂，已觉春阳动幽谷。","从来自许百鍊钢，此去人看九秋菊。","微之一折轻自坏，元城百挫无转足。","两公遗事炳丹青，牙签时整西风读。"]},{"t":"斋居和同馆曹良金刑部韵","f":"七言律诗","c":["华月分光映列躔，白云元共紫微连。","炉熏茗盌还今夕，阁试堂书又隔年。","功业要看归宿地，赓酬不碍往来篇。","欲驱蹇劣追神骏，拨尽寒灰午夜前。"]},{"t":"送殷通判之严州","f":"七言律诗","c":["三百危滩走急流，万重山色护严州。","人家树里开图画，驿吏花间候綵舟。","骏足岂应今日展，高名合向晚年收。","子陵祠庙云霞上，为想春风露冕游。"]},{"t":"乌木扇歌","f":"古风","c":["南蕃乌查乌角光，剡溪溪藤色比霜。","两物迢迢天一方，阿谁妙手巧裁量。","坐令皎月生筐箱，金花点缀七宝装。","牙箫钿靥回光芒，为君鼓舞生清凉。","回思故国云茫茫，枯蔓朽株纷路傍。","人生贵贱岂有常，牺尊沟断同根芳。","君不见金门六月清暑殿，犹堪舒卷奉君王。"]},{"t":"陪李子阳吴克温二太史杭世卿吏部游城东潘氏园赋得流水","f":"七言律诗","c":["玉泉山前看滥觞，凫鹥翔集菰蒲香。","远波明灭带城阙，别派宛转通林塘。","褰衣经涉孺子喜，展席俯视尘襟凉。","斜阳上马傍堤去，极目东流思故乡。"]},{"t":"游香山","f":"七言律诗","c":["几年尘里说登山，涉涧穿林路几盘。","碧树楼台深见寺，红云城阙远平阑。","廊僧揖客多乡语，春菜登盘称野餐。","斜日催人强归去，欲从羸马谢朝冠。"]},{"t":"送李原复之南京刑部","f":"七言律诗","c":["水云亭上坐论诗，眼见红芳落酒卮。","好景一番连孟夏，故人相继作分司。","风波道路君应识，冰檗心怀我旧知。","两字哀矜一尊酒，临歧不唱渭城词。"]},{"t":"升彼高堂为毛太安人寿","f":"古风","c":["升彼高堂，酌其兕觥。","兕觥欣欣，春酒载盈。","维彼硕人，是介是承。","硕人雍雍，厥德洵美。","载其有家，维惠恭止。","维惠恭止，休其承祉。","其祉伊何，兰茁其芽。","处也家宝，出维国华。","国华有辉，维帝宠嘉。","锡之鸾书，曰汝之报。","汝考汝母，汝迪汝教。","维往莫追，生也永耀。","硕人拜命，弗掖弗持。","珠翟霞裳，象服孔宜。","邦人来观，秩秩其仪。","其仪秩秩，其容有怿。","乃筵斯堂，乃几斯席。","硕人燕胥，笾豆有绎。","维南有山，维东有海。","硕人寿考，终燕乐岂。","山石弗砺，海波弗尘。","维彼硕人，于千百春。"]},{"t":"双桂堂为宜兴张世麟世凤赋","f":"楚辞体","c":["美人出南国，文采并娴都。","风云一朝会，联步起天衢。","伯也空冀北，叔兮照三吴。","何异同根桂，分庭各敷腴。","春风会京邑，闾里增欢娱。","联芳世所羡，况此一岁俱。","峨峨双桂堂，丽榜辉新图。","清芬既不异，茂干宜相扶。","昔闻云间陆，亦有眉山苏。","往迹炳如在，师贤在吾徒。","皇风发雅奏，金石间笙竽。","愿附棠华咏，千秋扬令模。"]},{"t":"题竹","f":"五言绝句","c":["悬石嵌青空，下临湘江水。","中宵明月来，照见青鸾尾。"]},{"t":"送王敬止使朝鲜","f":"五言古诗","c":["大人值兴运，避地开东藩。","八条一以施，礼俗仪中原。","燕满中扰乱，淳风久仍存。","流传扶馀慈，至性天所惇。","真德颂唐运，金石振清温。","至今云海上，想象扶桑暾。","皇帝膺宝历，威德被鱼豚。","维东实首顺，圭组继胀膰。","赴告谨终始，宠数亦殷繁。","皇皇使者车，中天下旂幡。","共瞻天人姿，照耀东海垠。","宇宙有大界，中华有常尊。","奉使固有体，专对非徒言。","春风海山道，注目盼回轩。"]},{"t":"送李太史希贤提学浙江","f":"五言古诗","c":["吴越连云海，蓬瀛切斗枢。","皇仁无内外，宪府敕文儒。","左掖天低户，西清月在隅。","法冠初著豸，文笔近提朱。","甄别推明鉴，陶镕属大炉。","化源深涤溉，皇路俨驰驱。","帖括经言病，雕镌士习殊。","洗心端有待，简命的非徒。","列屋思明烛，停云怅据梧。","真淳钦雅度，洒落见长图。","梁栋时方重，昌苓世并须。","未应嗟远别，回首是清都。"]},{"t":"送杨邃庵提学陕西","f":"七言律诗","c":["海内声华四十春，向来江汉梦犹新。","门墙愧不参诸子，祖席何期列从宾。","东壁二星终近斗，南徐一水又通秦。","平生万里真无负，到处青云满后尘。"]},{"t":"送沈云松还上海","f":"七言绝句","c":["已觉人间万事全，钟情犹为别离牵。","但令消息年年好，即是斑衣舞膝前。"]},{"t":"送沈明本教泰顺","f":"七言律诗","c":["欲别无言意万重，扁舟望望过江东。","名场自昔有遗恨，学海几年成此翁。","人向中朝愧山简，天教南士识胡公。","云门雁荡经行处，为想肩舆入画中。"]},{"t":"送沈鸣岐教寿昌","f":"七言律诗","c":["七里滩头倚短篷，锦云峰里坐春风。","旧来鸑鷟文犹炳，老去骅骝气尚雄。","人世几番云作雨，功名千古鸟飞空。","何当共酌桐江水，一洗从前鄙吝胸。"]},{"t":"送李子阳先生归省","f":"七言律诗","c":["朝下西清月未沉，东门冠盖簇儒林。","湖山梦里三年别，风雨秋前一夜心。","后阁承欢青鸟集，前星回望綵云深。","潘家林外春阴在，还许追陪继赏音。"]},{"t":"送王伯安下第还馀姚","f":"七言律诗","c":["五色光中炫早曦，丹山秋日凤南飞。","常疑劲翮冲霄惯，未信中原结网稀。","吴越天连双阙迥，蓬莱云近一星辉。","杏花江上春如海，莫待西风吹绿衣。"]},{"t":"题莆田郭氏世美卷 其一","f":"七言绝句","c":["酂侯传国魏谟封，七叶貂蝉四世公。","我赋郭家三孝子，万年人纪列清风。"]},{"t":"题莆田郭氏世美卷 其二","f":"七言绝句","c":["壶山苍翠入闽天，曾见参军哭墓年。","生死靖康南北路，可知当日事昭然。"]},{"t":"题莆田郭氏世美卷 其三","f":"七言绝句","c":["一家纯孝祖孙同，狂卒何知亦敛戎。","看取弟兄争死日，古人何必是褒融。"]},{"t":"题莆田郭氏世美卷 其四","f":"七言绝句","c":["一命初沾竟力辞，清漳心事鬼神知。","平生不惯谈茫昧，欲与先生赋瑞芝。"]},{"t":"恒斋为体斋宗伯弟曰谦赋 其一","f":"七言绝句","c":["浮云天地倦西东，一语南人契始终。","自古良医比良相，传家正尔不须同。"]},{"t":"恒斋为体斋宗伯弟曰谦赋 其二","f":"七言绝句","c":["粉署微垣列弟兄，青囊留我万山行。","年来悟得雷风象，不向人间取近名。"]},{"t":"送石训导之临湘 其一","f":"七言绝句","c":["令弟清台著绣衣，一毡还与郑虔宜。","过湘不用轻为赋，圣代崇儒正此时。"]},{"t":"送石训导之临湘 其二","f":"七言绝句","c":["天岳山前倚短篷，目穷飞鸟没晴空。","平生万里江湖念，都付春风化雨中。"]},{"t":"送华文光尊甫南归","f":"七言律诗","c":["数行官柳带城斜，又送庞公上小车。","天上神驹方独步，江南乔木几名家。","山当朔野霜先结，水绕官河路不差。","闻道家君北来近，相逢何处整乌纱。"]},{"t":"送郭鲁瞻知山阴为砺斋太史作","f":"七言律诗","c":["我家简子山阴日，清昼垂帘一事无。","遗俗未应忘旧老，好官须自出吾儒。","青春日月当周道，黄甲风云入壮图。","别有故人簪彩笔，金鳌峰顶候双凫。"]},{"t":"寿罗子文父得钟山芝","f":"七言律诗","c":["龙蟠山下郁青葱，紫盖分明五叶通。","灵秀独钟麟趾地，寿昌多应鹤髯翁。","歌传汉府空闻调，食著仙经是有功。","拟掇芳腴荐清醑，夜深飞梦绕江东。"]},{"t":"杨启祥金兰","f":"七言古诗","c":["煮胶和金金作泥，捣蓝染楮光砑脂。","杨郎醉把离骚词，幽意已在沅湘湄。","须臾光风荡朝曦，林隈水曲皆春姿。","丛石卧羊低竹枝，紫茎绿叶芳菲菲。","佳人远游春不归，蘼芜绿满孤帆迟。","愁来罢琴抚瑶徽，临图更觉同心稀。","愿采芳香遥寄之，江湖阔远波浪危，空梁落月渺予思。"]},{"t":"送苏伯诚太史提学江西","f":"七言律诗","c":["郁孤台下驻旌旄，鹄立诸生拥绣袍。","新命北来天语重，故乡南望岭云高。","欧阳旧俗尧藩冠，许国遗宗汉署豪。","有待一番时雨遍，归来东观理风骚。"]},{"t":"堵氏母七十","f":"七言律诗","c":["纨布萧然古孟光，向来闺阃意何长。","不将本分矜流俗，直以孤贞代义方。","年与日添频把酒，心随兰死只留香。","良人地下应含笑，青鬓于今浅带霜。"]},{"t":"重送刘文瑞有怀顾颐弘先生","f":"七言律诗","c":["太息颐翁不可招，离亭东望客心劳。","贻书恨不当时早，归兴何如此日高。","尘世百年终剧戏，溪山随处足游遨。","只应未及君家祖，烂醉春风拥二豪。"]},{"t":"严以德送女至留半月归赋长句为别","f":"七言古诗","c":["我弟之妇君家甥，君女还作吾儿妇。","天然两姓若萝葛，不独朱陈誇世旧。","忆昨与君初结言，望松楼下开宾筵。","友松老人执杯酒，千金一诺须臾边。","微官系人不能去，五载停云渺江树。","向平心事两自知，山阔水遥关百虑。","西风鱼雁交梭驰，君来不来使我疑。","不知今夕是何夕，把酒却送君南归。","君来官河尚舟楫，君归河梁积冰雪。","故人分手自不堪，况复钟情初远别。","钟情远别不须嗟，儿今有室女有家。","官道附书如驿置，春江放棹若仙槎。","人情得陇还望蜀，我已安排洗孙局。","明年此日待君来，玉果犀钱遍童仆。"]},{"t":"题雪竹送陈生归吴","f":"七言绝句","c":["虎丘山下雪晴时，拄杖敲门自一奇。","京邑归来看图画，春盘玉版斗青丝。"]},{"t":"崔民瞻郎中父母同寿","f":"七言律诗","c":["万里晴空倦鸟归，祝融峰下旧柴扉。","手栽堂树皆堪芘，坐对云山已息机。","长日溪鲜堪入馔，新年宫锦又添衣。","孟光同德还同岁，何止人间七十稀。"]},{"t":"送赵悦梅","f":"七言律诗","c":["北来行李报家君，归棹还迎潞渚春。","两岁风光动梅柳，一时冠盖集荀陈。","无穷渌蚁尊中满，有约青山梦里频。","长向西风听佳信，阿戎官况只清贫。"]},{"t":"戊寅四月廿八日录至此叹息久之时天常殁矣保定赵守浚河筑桥诗为傅北潭太史作","f":"七言律诗","c":["郁郁平阡带古壕，沈沈新绿卧虹腰。","滹沱不复思王霸，溱洧何烦济国侨。","千里桑麻分雨露，一时粉绘杂风谣。","他年三辅收遗事，应续黄图第几条。"]},{"t":"题孙良辅所藏小景四幅 其一","f":"七言绝句","c":["野桃山杏各乘春，多事刘郎为怆神。","六百年来只如此，一番花老一番新。"]},{"t":"题孙良辅所藏小景四幅 其二","f":"七言绝句","c":["坛杏无花到水莲，中间辽阔二千年。","窗前风月湖边景，只恐丹青未易传。"]},{"t":"题孙良辅所藏小景四幅 其三","f":"七言绝句","c":["欲出未出峰顶月，将栖不栖林杪禽。","曾踏长安软红土，方识幽人此夜心。"]},{"t":"题孙良辅所藏小景四幅 其四","f":"七言绝句","c":["旧识襄阳孟浩然，蹇驴冲雪据吟鞍。","老来自怯溪桥滑，便作林逋一样看。"]},{"t":"送周先生出守嘉兴","f":"七言律诗","c":["雪后燕山画不如，东华晴旭散朝车。","黄迷禁柳辞龙仗，红逗江花引隼旟。","西浙几年忧困弊，南宫当日记吹嘘。","丈夫五马寻常事，泚笔勋名俟特书。"]},{"t":"季本清给事父母双寿","f":"七言古诗","c":["画帘花暖春云香，金尊酒满蒲萄光。","玉童双歌按清商，门前珠履来成行。","凤生三雏一雏翔，淩历紫清栖柏梁。","两雏膝下斑衣裳，春风对舞送霞觞。","山中之臞炼铅霜，洁身独立遗天常。","槁项黄馘同枯桑，人生七十齐高堂。","腰有绿绶怀银章，俯仰无愧终康强。","滑甘滫瀡供时尝，三山弱水是何方。"]},{"t":"蒋监事济民出主靖安簿盖不得于其长也为题其秋塘白鹭图送之","f":"七言绝句","c":["曾逐青云上绣衣，龙墀晴日飏朝晖。","天风不碍江湖迹，还向秋塘自在飞。"]},{"t":"题毛维勤所藏禹门三跃图","f":"七言绝句","c":["一夕风雷动九重，春江回首万鰅鳙。","云泥只尺从人辨，诸葛南阳本是龙。"]},{"t":"题陈克明竹","f":"七言绝句","c":["日永湖山桧影斜，微风时堕紫藤花。","道人无限江南意，更写筼筜向客誇。"]},{"t":"送赵明嗣袭职之金陵","f":"古风","c":["锦衣将军燕蓟郎，面围红玉颜清扬。","全家旧住双阙旁，一门诸父皆周行。","阿翁昔日事先皇，金戈日侍殿东厢，一日不见回清光。","将军后出亦堂堂，韬钤间续诗书香。","十三学书临硬黄，十五百步穿垂杨。","二十辞家宦南国，已觉万里前无当。","圣人南面驭八荒，风尘不动塞草长。","将军功业何所见，可惜龙剑明秋霜。","龙剑明霜龙不如，莲花凿镂金蟠挐，但令不试慎勿疏。","君不见金张之子世宿卫江东，虽好岂是将军居。"]},{"t":"梦作朝退步至南亭诗有步入南亭路不难落花红衬紫苔斑之句感而有作","f":"七言绝句","c":["一自看花入上林，溪山长是梦中寻。","不知谁辟南亭路，又向朝回发短吟。"]},{"t":"出郭 其一","f":"七言律诗","c":["出郭频瞻尺五天，雨馀云物更清妍。","楼高紫凤中天见，山跃青龙到海旋。","香径细寻芳草入，酒帘低傍绿杨悬。","微官自笑成何事，閒过东风又一年。"]},{"t":"出郭 其二","f":"七言律诗","c":["好景城南四月天，游人容冶百花妍。","红惊小辇流莺起，绿衬阳坡细马旋。","风里游丝晴自袅，雨馀新月晚初悬。","春光容易空抛却，频倒芳樽莫问年。"]},{"t":"阎太守复任西安","f":"五言律诗","c":["好去西安守，还乘五马车。","封疆参井旧，民物汉唐馀。","会府人咸喜，铨曹最已书。","儿童候公久，归驾莫纾徐。"]},{"t":"王舍人孟端为华处士作耕渔图久而失去其孙珵访求得之","f":"古风","c":["舍人善竹兼善画，源流本是湖州派。","湖州之画掩以竹，舍人妙思紬不足。","耕渔之图谁所传，华家明珠海上还。","家声不愧见父祖，元气有托留人间。","川原靡靡高复低，东村网罟西村犁。","长鞭驱烟入深树，小艇载雨归前溪。","溪鱼正肥春酒熟，百斛新输官廪粟。","酒酣月出歌一声，何处高门有华屋。","浮生不逮斯人早，前辈风流迹如扫。","银钩金错发天机，何幸典刑犹此老。","舍人寸纸时共珍，华郎见图如见亲。","乾坤无穷百年速，撝诃安得烦鬼神。","君不见平泉树石散诸贵，此子此孙今几人。"]},{"t":"萧升荣母曾孺人挽诗 其一","f":"五言律诗","c":["堂北霜风紧，天涯客梦催。","犹看衣线在，不及诰鸾回。","遗德良人感，新铭阁老裁。","前山松柏迥，猿鹤助悲哀。"]},{"t":"萧升荣母曾孺人挽诗 其二","f":"五言律诗","c":["氛沴交行日，乡邻出次时。","情惟舅姑重，义不死生移。","执礼神应鉴，怜孤族并推。","小郎今长大，衰杖有馀悲。"]},{"t":"闻蛙","f":"五言古诗","c":["入秋足霖雨，颇长南池渌。","鸣蛙欣所遇，日夕鼓其族。","喧喧未渠已，隐隐撼吾屋。","群和杂蛄蚓，间噪警鹅鹜。","已惊西堂梦，复乱城南读。","孔公乃纪实，周生斯矫俗。","鼓吹本吾厌，矧兹强称目。","盐调恧胹熊，灰洒念燔菊。","顾兹繁有徒，一一胜掩扑。","维天运四时，万品均化育。","妍媸与细大，赋受咸自足。","春阳鸣鹂鹒，寒雨悲蛩蠋。","时至理则然，天机讵能伏。","可憎谅多在，君意偶斯属。","不见趸与蛇，无声日衷毒。"]},{"t":"亚圣嗣孙翰林五经博士元蒙恩赠封父母","f":"五言古诗","c":["尼邱降神圣，鸿化流无疆。","三迁毓明德，重光丽秋阳。","周辙竟不西，斯贤复遑遑。","坐令百代下，掩卷悲齐梁。","博士几叶孙，逢时迈虞唐。","通籍联禁从，鸣玉司烝尝。","仍于报功典，再衍酬恩章。","煌煌紫鸾书，照耀东山傍。","逝者不可作，萱枝独芬芳。","永怀五鼎意，先后同悲凉。","予亦章甫士，诗书沐馀光。","顾兹盛明典，何以称褒扬。","共惟神明胄，允矣万夫望。","惟圣始孝弟，惟皇眷忠良。","怀哉复何言，尔祖训有常。"]},{"t":"寿少师谦斋先生七十","f":"七言古诗","c":["太微无云星汉明，商飙按节回玉衡。","土阶六叶飞尧蓂，岁在戊申申甫生。","甲戌仲舒杨大庭，引翼房杜登蓬瀛。","金钟玉律谐颂声，圣人龙潜资六经。","缃麻日侍龙楼清，有时石室翻金縢。","甲子周岁龙飞腾，白麻首出金瓯名。","司马入府毡裘惊，十年海宇歌太平。","如皋如夔连茹征，鸾鹄济济充皇扃。","并包细大靡矜争，香山日夕思旧盟。","帝恩非常归未能，黄扉日晏下紫清。","寿觞百斛分金茎，谁欤寿者公与卿。","次者乃是銮坡英，天佑我皇惟纯精。","钟灵毓秀归老成，往昔宵寐通精灵。","先知已属范高平，麟袍五色腰玉横。","巍然百辟瞻仪刑，氓饥欲粟寒欲缯。","公无言归劳圣情，年年此辰称兕觥。"]},{"t":"送毛彦伯","f":"七言律诗","c":["议论相逢便伟然，省华诸子固多贤。","风云幸接鸿飞后，乡国仍看樾荫连。","两月客程还膝下，几宵归梦又江边。","春衣好作重云锦，令祖新秋又八千。"]},{"t":"送李师文令将乐","f":"七言律诗","c":["建业秋风歌鹿鸣，同时龙李最知名。","一筹已惜三年后，百里犹烦匹马行。","星出紫垣南去迥，水经闽岭北来清。","馀杭令尹新祠庙，香火于今更有情。"]},{"t":"爱鹤为海虞曹舜祥赋","f":"五言古诗","c":["青田双白鹤，脱略尘凡姿。","东海有逸民，心赏同幽奇。","天质不自媚，野情谅难羁。","逍遥云海间，永与鸡群辞。","鹤也诚可人，爱鹤人可知。","人有异于鹤，贾鞭眩黄栀。","骎寻不自觉，沦没共污缁。","君子拟鸾凤，憸壬乃鸮鸱。","我歌爱鹤篇，继彼乘轩词。"]},{"t":"米元晖小景一幅浅色积成高五六寸长不二尺而渺然有千里之势为赋六言","f":"古风","c":["芳树春酣雨后，薄云横带山腰。","极目青萦白缭，江南何处迢迢。"]},{"t":"樗老杨翁挽诗 其一","f":"五言律诗","c":["昔年同馆士，频岁泣霜风。","又接樗翁讣，其如洛社空。","行身汉阴叟，避世鹿门翁。","渐觉沧洲远，烟波日夜东。"]},{"t":"樗老杨翁挽诗 其二","f":"五言律诗","c":["道为无心得，才因不用全。","子看青琐贵，身到白头年。","太史春秋志，中台琬琰镌。","新坟才四尺，佳气日苍然。"]},{"t":"樗老杨翁挽诗 其三","f":"五言律诗","c":["海雁依时到，庭花不再红。","通家锦囊在，入室穗帷空。","歌哭同杯酒，江湖想钓筒。","真淳那复见，落日起悲风。"]},{"t":"厉处士挽诗","f":"五言律诗","c":["末路嗟何似，江湖见此奇。","能于外物薄，不逆故人欺。","淳孝真堪传，馀言尽可师。","九原逢德耀，无愧白头词。"]},{"t":"九日卫景玉西庄赋","f":"古风","c":["前年重阳燕城南，去年重阳小山前。","今年重阳西郭下，青山碧树开芳筵。","前年坐客黄与李，去年去作南曹吏。","今年坐客罗八九，一半相看非旧岁。","不才濩落无所施，三年坐食尻生胝。","主人爱客我不去，年年对举黄花卮。","西清步出长安道，一带青山远相撩。","霜风拂衣声摵摵，寒日映帽光杲杲。","入门下马耳已清，刘东胡琴薛鸾筝。","新声共爱白翎雀，浮云不动黄龙城。","黄龙古城秋草里，狐狸钻穴荆棘横。","石家郎君从失足，四百馀载胡风腥。","西风慷慨对斜日，只此便合倾千觥。","主人有酒，客无庸辞。","千古在前，后亦如斯。","中间可乐，其与几时。","谓君不信上高处，燕丹郭隗冢累累。"]},{"t":"十日南山宅尊乡会分得东字","f":"七言律诗","c":["摇落龙山夕照空，衣冠高会凤城东。","从渠海内风流盛，输我尊前笑语同。","几处黄花如故里，他年绿野感秋蓬。","晚来白发颓中坐，欲改南山号醉翁。"]},{"t":"题史引之所藏长江六月图","f":"七言古诗","c":["长松泠泠生昼寒，高岩侧缀青琅玕。","阳坡宛转行朱阑，青莎滑腻碧藓斑。","红桥直走淩惊湍，下接孤屿高㠝岏。","隔江青山如伏羱，柴扉草堂相对安。","渔舟缥缈青林端，樵童牧叟时往还。","群山忽断百里宽，青蒲绿藻萦微澜。","临江飞阁丛井干，江流石角随弯环。","前山转深势未残，层崖复磴劳跻攀。","上方寂寞空禅关，平林演迤临江干。","江回山尽路险艰，飞梁侧卧波潺潺。","江流自此入渺漫，遥山一抹天际看。","东京画史真高閒，故将山水穷瑰观。","岷峨嘉陵远草殚，九华落星扬子湾。","晴洲历历被芳兰，美人不来空浩叹。","疾风吹尘暗燕山，金星龙尾冰攒攒。","燔熊炽豹光赫殷，为君炙兔扫冰纨。","君归终日山水间，肯忆羸马随朝班。"]},{"t":"十月四日同韩国器中书张时行吉士饯刘御史文焕还赴尊乡会于陆太仆第得夕字","f":"五言古诗","c":["东城送客罢，觚棱动暝色。","尊乡奉严戒，后至有明谪。","挥鞭不返顾，望望淩紫陌。","同行韩与张，先后互驱策。","我马才本下，此日殊努力。","及门见僮骑，相顾如有得。","主人闻客来，索带命殽炙。","众宾已沾醉，为我还促席。","劝酬略登降，问劳杂谐剧。","写情会有赋，探韵止馀夕。","飞觞不假借，阁笔岸予帻。","清时自难遇，胜会固鲜袭。","今晨复何晨，烂漫挹珠珀。","矧兹乡邻聚，更觉情景适。","南斟出珍藏，北馔割鲜硕。","虽微霜橙荐，时菊尚可摘。","寒更近尤长，城柝时漫击。","华镫蔼馀辉，落月沉坏璧。","欢悰不可竟，明发会有役。","据鞍谢主人，璇标已东北。"]},{"t":"十一月朔张南山寿日","f":"七言律诗","c":["一自登名立从班，周旋长在五云间。","官阶四品中兼外，书法三吴柳继颜。","退食有时乘褐马，趋朝满目是青山。","蓬台此日群仙会，风雪犹应许扣关。"]},{"t":"送袁良辅还封丘","f":"七言律诗","c":["闻道双凫晓欲飞，锦笺红烛夜裁诗。","月明古寺嗟人远，寒压重裘觉岁驰。","卓令至今佳传在，山公休道荐书迟。","黄金台下西南路，眼见青骢入奏时。"]},{"t":"董虞臣辰溪八景为赋其二 其一 石桥仙迹","f":"七言律诗","c":["云根一片压中流，曾是仙人玉斧修。","绝岸巧通平野去，细波长共远山浮。","苔纹想象空飞舄，树影参差壑驾舟。","借问碧阑容点笔，淩风我欲试清游。"]},{"t":"董虞臣辰溪八景为赋其二 其二 猛峒新庄","f":"七言律诗","c":["桃花不记武陵源，峒里人间别有天。","罨画溪山明白昼，接云禾黍自丰年。","前冈饮犊逢巢父，别浦移舟渡辋川。","问著主人无一事，久抛金甲事春田。"]},{"t":"冬至感怀","f":"七言绝句","c":["浮世侵寻四十将，劳生何以称冠裳。","回思丁未看辛丑，别有愁根更是长。"]},{"t":"戊午元日候朝和冬至韵","f":"七言绝句","c":["尘途役役苦迎将，五色谁从补舜裳。","坐拥槐枝候明发，忧端不数漏声长。"]},{"t":"谒文山祠次同游诸公韵","f":"七言律诗","c":["东风一梦过钱塘，直自元丰兆靖康。","终岁诸公讲和战，到头赤手树纲常。","生前骨肉山河碎，身后辉光日月长。","新庙城南更雄丽，公忠遗种讵荒凉。"]},{"t":"人日乡里会归曹良金秋官寄示咏怀新句明日斋所奉答","f":"七言律诗","c":["薄寒催酒斗新年，犹是郊斋一日前。","事往旧游真作梦，诗来险韵恰逢咽。","莺调歌舌方求友，柳著官黄欲试绵。","子建平生最萧洒，壮怀宁许豆秸然。"]},{"t":"同年斋院中朝振同戴御史元之宿僧舍宪清南夫有诗嘲之往返良苦予最后作为之解围","f":"七言律诗","c":["清晓诗筒入递频，夜窗虚榻看横陈。","贾馀竞欲收三捷，戒狃予方息两民。","掖竹本因枝带叶，胡卢岂必画非真。","西堂三日伊蒲馔，且共瞿昙讲幻身。"]},{"t":"同年刘直之父母双寿","f":"七言律诗","c":["东望蓬莱极海云，仙筹满屋旧曾闻。","老馀骢马留桓典，归卧青山共少君。","华发笑看明镜在，綵丝犹忆画帘分。","高堂岁晚长生燕，还折梅花映宝薰。"]},{"t":"纪梦寄文宿诸友","f":"七言律诗","c":["客舍春来觉梦多，黄衫连夕报登科。","七星散落云中斗，独鹤高乘树杪柯。","捷足故人俱绿鬓，关心乡社渺沧波。","从今不作停云望，倾耳雷门听凯歌。"]},{"t":"送汪进之令永嘉","f":"七言律诗","c":["马上相逢识未真，论交已是十年人。","风云聚散惊浮世，霄汉飞腾有健身。","奉日岂应忘近主，鸣琴聊欲试亲民。","东风百里温州路，谁看桃花满县春。"]},{"t":"赋得瀛海奎光送马良佐先生之南院","f":"七言古诗","c":["仙家苍茫云海东，海光上与星辰通。","昭回万象森布列，灵景独应图书宫。","宫中明星十有六，一一紫焰舒长虹。","珠宫贝阙相荡漾，顷刻万状难为容。","群仙无事亦来往，鸾鹤隐见空明中。","翩然一鹤下南斗，流辉万丈惊蛟龙。","蛟龙惊遁海天净，惟有匹练悬高空。","紫宫东南纵遐眺，晴霞五色交青红。","天孙停梭赤霄上，指点毫末分纤秾。","帝傍丝纶要经纬，旋轸不待星躔终。","石渠延阁五云绕，紫泥黄纸三更封。","悬知不学卯金子，馀光反借青藜公。"]},{"t":"题萱桂图送徐理之父子","f":"七言绝句","c":["白头人对綵衣裳，本自无忧不待忘。","谁写萱花傍丛桂，要看雏凤挹天香。"]},{"t":"蒋国器往岁南归予苦头风不得送赋诗有记取他年说今日冷云疏雨出都门之句今再至而归予亦病中天复阴雨俯仰今昔为之慨然","f":"七言律诗","c":["五载京华两赋归，客心都似宦情微。","天应有意还留舌，雨亦何心惯湿衣。","长路不须怀近事，旧题浑已谶先几。","小昆山下农田早，为想秋风蟹稻肥。"]},{"t":"徐子容祖母寿八十三","f":"七言古诗","c":["春湖映空光一碧，春日烘云成五色。","金堂仙人燕王母，云影波光乱瑶席。","麟洲别来几清浅，兰叶萱枝翠如剪。","笑轮花甲问东风，八十三年供一莞。","杨花扑帘春昼迟，鸾笙幻眇朱弦稀。","瑶环涓秀瑜珥润，戏舞绕膝争含饴。","就中一孙俊而奇，珊瑚玉树含春晖。","担簦上国未能去，几日目断孤云飞。","西风八月仙桂黄，手携鹗书还故乡。","仙人一笑开北堂，重帘复幔皆天香。","男儿悦亲宁碌碌，作诗献寿还拭目。"]},{"t":"邹时鸣父母双寿","f":"七言律诗","c":["玉陛风光动綵裾，鹊声先已报江鱼。","鸾回两检新封敕，龙卧三湘旧隐居。","喜气并添凝望里，宾筵相压小春馀。","无因得与升堂拜，长傍红云想使车。"]},{"t":"家僮摘槐芽","f":"七言律诗","c":["小奴携筐绿掩苒，斜日归自东邻家。","青精未试仙子诀，泠淘的见诗翁誇。","人间正味竟何在，天地育物真无涯。","紫莼青荇更不恶，高秋谁泛三江槎。"]},{"t":"送王约赴河间县丞","f":"七言律诗","c":["平原西北古瀛洲，长记征车半日留。","山接全燕从地起，河分二水带城流。","千年王泽诗书古，永日丞厅竹树幽。","好去王郎更清白，龙门一局未应休。"]},{"t":"挽苏廷玉","f":"七言绝句","c":["到处江湖识此翁，几番倾廪惠疲癃。","灵岩山下一片石，叹息高踪已梦中。"]},{"t":"何处士赏静亭","f":"七言律诗","c":["万里松州限蜀川，风流幕府重当年。","筹边屡上金城略，退食还歌菉竹篇。","意外云山争自媚，环中风月许谁传。","瀼西茅屋长邻近，相望孤鸿落照边。"]},{"t":"送可晚吴翁","f":"七言律诗","c":["十里山塘接虎丘，隐翁家近白蘋洲。","偶来暂别延陵庙，欲去还同孺子舟。","云里綵衣高捧日，雨中黄菊苦思秋。","经年正有庭闱念，为酌离觞悔远游。"]},{"t":"送谢司仓","f":"五言律诗","c":["宁知信宜邑，乃在古高州。","地接朱鸢近，天连碧海浮。","官仓馀火米，土俗罢绵裘。","莫作炎蒸虑，男儿重远游。"]},{"t":"书饶贡士友爱堂卷 其一","f":"七言绝句","c":["江雨红垂荆树花，草堂千里梦京华。","无人为续池塘句，长向春风忆谢家。"]},{"t":"书饶贡士友爱堂卷 其二","f":"七言绝句","c":["风雨长安旅食孤，夜窗灯火说江湖。","红尘下马东城路，来看饶家友爱图。"]},{"t":"送夏良惠","f":"五言古诗","c":["君从澄江来，还望澄江去。","澄江渺千里，孰是君归处。","连连波上山，历历沙边树。","长安多亲知，青云在指顾。","一行拂尘衣，高意竟莫禦。","淩江望农烟，憩石呼晚渡。","芳阡笑儿童，佳木散徒御。","问讯钓鱼竿，汀洲未云暮。"]},{"t":"送宋惟德分教池州","f":"七言绝句","c":["池阳风物似长沙，第一名山是九华。","输与能诗宋文学，芙蓉影里岸乌纱。"]},{"t":"送王汝昭考绩还南乐","f":"七言律诗","c":["鸣玉薰风下紫清，日华流采照君明。","重来一鹗秋期近，暂去双凫晓翼轻。","封域未踰关辅地，别离无奈故人情。","归轮入境应频驻，一路棠阴父老迎。"]},{"t":"送汪县丞还吴兴 其一","f":"七言绝句","c":["吴绵百箧练千箱，岁占东南第一纲。","不似朱家贡花石，九重龙衮要文章。"]},{"t":"送汪县丞还吴兴 其二","f":"七言绝句","c":["洞庭烟浪接吴兴，使者归舟画里行。","浮玉山前万松底，好诗多为别来生。"]},{"t":"题李徵伯扇","f":"五言绝句","c":["新雨蕉叶大，云根生昼阴。","只此可永日，何必弦鸣琴。"]},{"t":"题赵希文所藏王孟仁小景","f":"七言古诗","c":["柳丝如烟散晴风，小桃野树交青红。","芳洲细草何丰茸，绿波远与青天同。","遥山西入空濛中，扁舟兀坐谁氏翁。","物色似是天随公，惊麇骇鹿不可踪。","此日此意殊从容，自从挟书朝帝宫。","十年梦寐劳江东，长桥飞盖连垂虹。","尚想烟雨推孤篷，偶然一笑岂易逢。","丹青信有缩地功，燕山六月苦蕴隆。","开轩对此情无穷，谁欤往者吾其从。"]},{"t":"送盛世虔兼简严以德 其一","f":"七言绝句","c":["红云千里隔江关，容易看君独往还。","留得锦笺无恙在，不教空到小吴山。"]},{"t":"送盛世虔兼简严以德 其二","f":"七言绝句","c":["东河日日望兰舟，远客新年已倦游。","为忆相逢话京邸，红菱白藕正清秋。"]},{"t":"书吴通判焚黄卷","f":"七言律诗","c":["淮甸风烟接海门，甘棠随处绿阴蕃。","人传旧德歌三异，帝有新恩贲九原。","华表月明苍树合，宝函春动彩云翻。","乡人应悔籯金误，衰草荒坟泣断猿。"]},{"t":"送杨启祥","f":"七言古诗","c":["杨生画兰近无敌，挥笔使金如使墨。","玄缯绀楮随所遇，入手光风灿朝日。","湘江南北几千里，收拾都归笔锋里。","閒来天上弄秋光，落笔便得天颜喜。","有时片纸出人间，传看一日遍九廛。","五侯七贵争莫致，时复挥翰骚人前。","西风八月吹锦衣，掉手还向江南归。","汀洲蘼芜寒更绿，木叶时傍孤帆飞。","回首思君何处切，南薰殿里午风微。"]},{"t":"八月六日周北野宅尊乡会雨不能赴先是予招客亦值大雨","f":"五言律诗","c":["秋雨亦无赖，偏欺我与君。","每当开燕日，故作满城云。","未说初春旱，何如后夜闻。","一般尤足恨，红湿从伶裙。"]},{"t":"孝松为故华亭贰尹吴君赋","f":"楚辞体","c":["君昔哦松古华亭，我方挟书游县城。","流风善政尚能忆，未省至孝通神明。","郎君京华报君讣，握手道边双涕横。","潜光隐德有如此，如君岂独堪为丞。","乾坤茫茫日月速，斯人已复从先茔。","茔前郁郁万松树，总是君手栽培成。","乡人重君不忍斥，指点苍翠歌仪刑。","秋霜春雨几悲怆，大篇长句何铿鍧。","松兮节操本自贞，何幸遇君增令名。","田家紫荆尚千岁，何况美与参骞并。","我歌孝松君敬听，古来万化由家庭。","行将东海甘棠树，并入朱弦流颂声。"]},{"t":"乡人徐景晖老而丧子游京师意象悲甚将别赠此","f":"七言律诗","c":["早向丹山识凤雏，十年清梦隔江湖。","偶来聚首惊霜鬓，忽漫长歌缺唾壶。","春雨南洲生杜若，夕阳西崦近桑榆。","扁舟挥手渡江去，从此人间谢畏途。"]},{"t":"东海先生有表弟褚君跛一足先生呼为鹧鸪叟输赋入京求此诗","f":"七言古诗","c":["有叟有叟名鹧鸪，壮年意气亦豪疏。","豪行不顾一足拘，苦吟赢得全身癯。","有儿不令左右扶，独携短筇朝帝都。","县吏睢盱索官租，儿职催科翁代输。","输完妇子得宁居，老身健在百不虞。","西风官亭倾别壶，亭树哑哑啼乳乌，似是忧翁步趑趄。","乌不能言意有馀，何不啼向吴城隅。"]},{"t":"宋宫蹴鞠图","f":"七言绝句","c":["甲马营中五色光，天将一统付真王。","后园踏鞠宁为戏，犹有萧娘卧榻傍。"]},{"t":"题画送夏时臣尹龙游","f":"七言绝句","c":["红叶西风吹客衣，江边行李立多时。","舟师亦解衢人喜，横棹中流歌竹枝。"]},{"t":"新安郑氏四节坊","f":"五言古诗","c":["卫乱共氏理，周兴比干封。","义节本天授，褒扬系皇风。","閒披新安志，仰企荥阳宗。","烈烈四女士，允为男子雄。","世运有迁革，英风浩无穷。","高闳丽云汉，大字腾蛟龙。","在殷比三仁，于宋齐五忠。","世有长乐老，此地无经从。"]},{"t":"送少师谦斋先生致政归义兴","f":"七言律诗","c":["逢掖登庸玉带归，近来亲见古应稀。","两朝旧学传黄卷，一代完名映紫微。","西洛园池增胜槩，东城冠盖掩前辉。","门墙剩有抠趋地，还许相从认钓矶。"]},{"t":"题画马","f":"古风","c":["吴兴公子人中英，文学之外百艺精。","龙纹鸟迹穷变态，落笔万类无潜形。","画家难工在狗马，即物计数皆天成。","平生所见凡几本，如形在鉴影在灯。","君家此幅得何处，真迹似是来吴兴。","前行三匹骏且狞，急鞚恐作蛟龙腾。","一匹顾类未肯行，一匹欲卧垂青缨。","中间一匹骨如堵，四蹄犹带交河冰。","紫衫奚官发鬅鬙，胡靴短靿带红鞓。","当年内厩事毛仲，几随仙仗过华清。","兴亡百变物尽化，惟有遗迹留丹青。","摩挲绢素三叹息，毛鬣似觉雄风生。","君不见千金尚买死后骨，此马此人君勿轻。"]},{"t":"塞上谣 其一","f":"七言绝句","c":["十月龙沙百草乾，嫖姚乘胜逐呼韩。","关中更有萧丞相，千里无忧给饷难。"]},{"t":"塞上谣 其二","f":"七言绝句","c":["千顷膏腴紫塞秋，健儿耕作贵人收。","金城遗迹犹堪按，只在忠良与国谋。"]},{"t":"题松鹤图为周太守寿","f":"五言古诗","c":["翩翩双白鹤，飞自瑶台阴。","玄裳既修整，缟袂亦萧森。","乔林纵远步，虚壑引清音。","俛仰各有得，逍遥清涧浔。","达人事当世，雅志本云林。","悬车不待岁，戢羽思高寻。","何异松间鹤，飘飖云汉心。","嘉诞宾友集，初筵列朋簪。","鸣丝送旨酒，抗节起高吟。","白日丽华栋，簪犀炫钩金。","招要香山翁，笑傲白云岑。","岁岁但如此，焉知寒暑侵。"]},{"t":"邹静修挽诗","f":"七言律诗","c":["好景耆年正合閒，背堂花竹面楼山。","祖风田画交游里，家法王凝伯仲间。","尘梦一宵惊汗漫，舞衣当日记斓斑。","伤心玉井峰头叶，谁共沧洲载月还。"]},{"t":"陈清泉挽诗","f":"七言律诗","c":["短世匆匆春梦同，蜉蝣蜾裸空西东。","眼中寿考已如此，膝下子孙谁似公。","纪德前身太丘长，游仙此去云台翁。","清风来往雁山下，应笑白发悲儿童。"]},{"t":"题姜少卿廷宪墨竹","f":"五言绝句","c":["草草临池墨，萧萧落叶风。","高情不可见，怅望越江东。"]},{"t":"送程克晦","f":"古风","c":["春阳迟迟风奕奕，滦河潞河冻俱释。","河边官柳千万株，一一长条曲尘色。","小车载酒沿堤去，目逐行舟不能住。","攀条弄色临晚风，却忆前年别君处。","君家奕世廊庙人，暂蹶霜蹄何足云。","南山积书充四库，西洛奥旨穷三坟。","山深昼长风日美，把卷临流思千里。","有书数寄南来鸿，慎勿待、建邺西风吹桂子。"]},{"t":"秦一元自通山尹调归善李文瑞索诗送之","f":"七言绝句","c":["青云早折桂林枝，鄂渚鸣琴有去思。","为爱罗浮峰顶月，清光犹得照朱丝。"]},{"t":"陈汝砺宪使自云南入觐升左方伯","f":"五言律诗","c":["朔云逢入觐，南纪送归藩。","地昔埋轮旧，官今列岳尊。","冰霜回晚烈，风日散春温。","定遣炎州物，秋毫识帝恩。"]},{"t":"东圃题陈明之菊期南夫二郎","f":"七言绝句","c":["日出东轩积雪融，菊芽兰茁竞春工。","君看石畔丛丛碧，已办西风一丈红。"]},{"t":"吴汝玉自公安赴会试以例格不许","f":"七言律诗","c":["吴郎自负知何似，一落荆南便十秋。","夜榻偶然同举酒，春风几处独登楼。","名场接轸分胡越，剑气中宵看斗牛。","已识行藏非在我，江湖何地不优游。"]},{"t":"月楼为杨尚絅赋 其一","f":"七言绝句","c":["飞盖桥头踏月华，顺流东去是君家。","晓风依约凭阑处，隔浦金盆漾浅沙。"]},{"t":"月楼为杨尚絅赋 其二","f":"七言绝句","c":["层轩高栋切云浮，纵有阑干不碍秋。","谁在隔江歌水调，清寒重忆广庭游。"]},{"t":"题王敬止所藏陈明之菊二首 其一","f":"五言绝句","c":["云根翳金英，零露杂芳草。","忆昨南山行，相逢正秋晓。"]},{"t":"题王敬止所藏陈明之菊二首 其二","f":"五言绝句","c":["王郎东使年，金绯照云海。","馀辉贲园芳，岁晚犹采采。"]},{"t":"偶书 其一","f":"七言绝句","c":["万事人间不可期，云中日日候来仪。","九苞自爱桑榆暖，惭愧西风碧树枝。"]},{"t":"偶书 其二","f":"七言绝句","c":["鱼腹隐刀犹可测，牛头有角岂难知。","寒泉渴饮真破甑，更向青冥学忍饥。"]},{"t":"李方伯挽诗","f":"七言律诗","c":["玉节新移自汴郊，缄题千里托神交。","有怀旱岁为霖雨，无地青山酹束茅。","南楚遗民怨芳草，西江归榇泣潜蛟。","诸郎不忝长平裔，云路争看丽九苞。"]},{"t":"书感","f":"五言律诗","c":["九十百里半，一篑千仞基。","少壮必有立，晚节乃堪持。","感彼日暮者，眷此青阳时。","婉娈不自爱，瓦裂当告谁。"]},{"t":"袁澄夫顾东曙寄诗各次其韵 其一","f":"七言律诗","c":["夜归连得故人诗，二妙谁令聚一时。","感旧不知吾慷慨，论才宁合子栖迟。","花当春半方堪赏，杯到愁来只自持。","只尺龙潭笑游地，扶摇今日望天池。"]},{"t":"袁澄夫顾东曙寄诗各次其韵 其二","f":"七言律诗","c":["生世端如雪上鸿，一尊犹记别时同。","云山有梦寻常到，江水无情日夜东。","未许文章真我辈，尚馀礼乐待诸公。","他年只恐西亭鹤，哀怨西风穗帐空。"]},{"t":"送胡仲光分务清江浦","f":"七言律诗","c":["计省郎官白发新，抡才元是玉堂人。","不将粉黛从时样，尽有风流愧后尘。","淮海又成千里别，山林犹是十年身。","秋风会有离群思，还向清江采白蘋。"]},{"t":"送林光甫分教上犹","f":"七言律诗","c":["行尽西江是上犹，南来五岭入云浮。","官曹不厌诗书冷，风物且为山水留。","虚市早春梅子大，畬田初夏稻花稠。","公馀我欲烦骑马，一访张公铁汉楼。"]},{"t":"沙阳徐复礼持曹宗孝书来却归省亲还赴南雍秋试","f":"七言律诗","c":["剑岭西南不断青，七峰罗立凤冈横。","弦歌里俗誇新尹，江海奇珍见此生。","远信恰随春雁至，归心先逐暮云征。","扶摇更觉南溟近，为想西风六翮轻。"]},{"t":"寄寿何以仁御医用匏翁韵","f":"七言律诗","c":["松间倚几逐阴迁，竹里茶铛扫叶然。","老去益知閒有味，丹成不恨世无传。","风尘笑我方为客，云海如君更羡仙。","翘首碧山丛桂底，一尊相属定何年。"]},{"t":"送谭贡士拱之入南雍","f":"七言律诗","c":["陋巷频烦枉刺笺，入门风格故翩然。","云衢继美看诸父，璧水蜚英及壮年。","师友尽观南国士，平安时报上江船。","清秋桂子金陵月，还比长安一样圆。"]},{"t":"送丁指挥","f":"古风","c":["丁将军，家习武，身好文，一生读书思致君。","君门射策不得意，俛著兜鍪发如猬。","男儿岂必皆明经，叔皮定远俱成名。","阴山尚有强梁客，听我秋弓霹雳声。"]},{"t":"送任希贤分教云和","f":"七言律诗","c":["古栝风烟接四明，旧家文学最知名。","承恩尚及青毡在，怀土潜惊白发生。","春雨菁莪遥送喜，秋风棠棣独关情。","祗应此后池塘梦，长共飞云绕凤城。"]},{"t":"题书堂二小画 其一","f":"七言绝句","c":["收却吴蚕八茧丝，草虫连夜促鸣机。","内家见此谁能解，游子江南正忆归。"]},{"t":"题书堂二小画 其二","f":"古风","c":["蒹葭倚空未老，蓼花被水初红。","我觉蜻蜓得意，翾飞来往薰风。"]},{"t":"两峰书屋","f":"五言古诗","c":["青山相对起，我屋住中间。","读书有时倦，曳履看青山。","峰头云气来，飞翠入窗户。","相逢载酒人，却度前冈去。","摊书石床上，偶坐窗前树。","微风山半来，松花落无数。","斜阳度西岭，返照松下石。","莓苔新雨过，灼烁炫金碧。","湖东海月出，山半竹窗虚。","斜白棂间壁，分明见蠹鱼。","明月照前峰，影向北峰落。","幽人夜启扉，惊去松梢鹤。","湖头三尺雨，峰顶云一寸。","雨止山依然，琴书得馀润。","自有两峰来，几人此高卧。","掩卷问青山，岩花向人堕。"]},{"t":"春试锁院日闻刑部奏举邵郎中天衢任方面众许作诗送行已而得福建按察副使","f":"七言律诗","c":["剡报初传自棘闱，使星今已向东维。","一时戏语今成谶，两月清欢合有诗。","云近紫垣明绣豸，日临沧海动朱旗。","还朝便作三年别，未放秋霜点鬓丝。"]},{"t":"送徐子容下第归洞庭","f":"七言律诗","c":["长安城中十日雨，马首不见纤尘飞。","群峰远想湖上碧，一鹤独向秋前归。","青云缓步更自稳，宝剑频拭还增辉。","江头今夕谁共语，船窗落月明絺衣。"]},{"t":"何丘山生日会以疾不赴","f":"七言律诗","c":["西第南楼迹已尘，北轩长夏更宜人。","年华如此便千古，汤饼不须愁众宾。","炎日病躯妨跃马，绿阴高柳正欹巾。","一番又负花前醉，遥听笙歌聒四邻。"]},{"t":"湘水飞云","f":"五言律诗","c":["客有潇湘意，新图展白云。","天边几晴雨，坐里日氛氲。","聚爱桑阴茂，行怜雁影分。","新年多喜气，五色变龙纹。"]},{"t":"西苑观太液莲圆殿古松及进冰者各记以诗 其一","f":"五言古诗","c":["亭亭芙蓉花，独出清沚中。","青天飞綵云，堕此明镜空。","杲日耀华色，炯然临晓风。","天质岂不丽，自无桃李容。","窈窕灵洲远，逶迤仙苑通。","永谢蔓草缠，寂寞甘自红。"]},{"t":"西苑观太液莲圆殿古松及进冰者各记以诗 其二","f":"五言古诗","c":["层城出云雨，其上多古松。","但观郁苍苍，莫记植者功。","众鸟不敢栖，恐是跋地龙。","回影拂金瓦，疏枝吟天风。","翠华有时来，绮绣交玲珑。","吾闻泰山植，耻受秦人封。","物巨宜有灵，时清多幸逢。","培植不厌厚，乾坤固无穷。"]},{"t":"西苑观太液莲圆殿古松及进冰者各记以诗 其三","f":"五言古诗","c":["凌人慎时令，初夏进寒冰。","天阙自旷迥，龙楼晨更清。","金盘未及荐，洞户秋风生。","瑶姬玉笋指，仙袂六铢轻。","持玩更调笑，柔纤映红明。","岂识单衣子，冲寒镵冱溟。"]},{"t":"王汉英通政母八十","f":"七言古诗","c":["银台先生发如漆，太君高堂新八十。","朝回迎客花底揖，花枝拂衣红一色。","折花奉觞拜膝席，君家太君藐姑射。","太君沾醉朱颜溢，鸾笙入房侍儿掖。","后堂歌声綵云隔，主人留宾还促席。","青衣传语催劝客，太君万寿客无出。","从此年年作生日，记取明朝是重七。"]},{"t":"题颜山人画送刘可大先生归五羊","f":"古风","c":["山人胸中山万重，傍吞云梦涵太空。","落笔天机横复纵，须臾万象分纤秾。","大山盘盘云与连，小山江面如浮烟。","江长山远望不极，彷佛孤帆疑上天。","高岩飞流散冰雪，转出深林凡几折。","上方台殿空烟霏，下界尘嚣此中绝。","林回路转地益清，垂杨一径通幽亭。","先生高坐客不去，终日扁舟相对树。","平桥浅水带远村，青林茅屋春氲氲。","儿孙生长不相识，鸡犬有时中夜闻。","山人昔年侍明光，填门造请皆侯王。","熊姿犀角日点缀，局束不奈冠与裳。","兹图旷逸知有以，无乃赐金归去放笔临潇湘。","风流太史同州彦，乞归几奏金銮殿。","离觞载举索我歌，不觉飞蝇污东绢。","山人山人今有无，江湖落日愁烟芜。","玉堂挥翰须健手，碧山长啸非良谟。","北来倘有阳关意，好写瀛洲春燕图。"]},{"t":"七月十五日久旱而雨同启衷给事送林宗清 其一","f":"七言绝句","c":["夜窗题诗风雨集，想得行人喜欲狂。","领取官河三尺水，连宵通闸放归航。"]},{"t":"七月十五日久旱而雨同启衷给事送林宗清 其二","f":"七言绝句","c":["左谏声华日月边，故人身到九重天。","山中桂树今无恙，好赋淮南第二篇。"]},{"t":"陆仪宾使还过吴省亲","f":"五言古诗","c":["萧史乘鸾去，千秋尚綵衣。","来陪双阙拜，行望五湖归。","故老争先睹，高堂谢夕违。","山迎秋晚翠，门映海东晖。","腰袅金重络，芙蓉画两旂。","舞疑天上别，歌听月中稀。","仙醴频添蚁，宫罗叠送绯。","一尊欢不尽，又逐彩云飞。"]},{"t":"题野庄卷","f":"五言古诗","c":["秋风吹庭树，落叶满空除。","閒寻野庄句，感我丘园居。","丘园正收穫，此日乐有馀。","亲交亦相念，奈此川陆迂。","尔庄复何许，言在南浦隅。","同处百里间，原田料相如。","欲往念未可，抚时空郁纡。","聊咏寄吾志，行哉归荷锄。"]},{"t":"送石城李先生祭告阙里","f":"七言律诗","c":["簪绂清斋出禁林，尼山秋色正萧森。","雷风岂有金縢警，玉帛深悬黼座心。","此日羹墙亲仰止，平生海岱快登临。","皇华不用歌离别，并入新宫播雅音。"]},{"t":"送汤尧德从事西川","f":"五言律诗","c":["好去皇华使，相将万里行。","冰霜乌府节，风物锦官城。","驿骑春山丽，文书夜案清。","成名在年少，乡社莫牵情。"]},{"t":"九日招天章","f":"七言绝句","c":["蓟北江东路几千，万重心事别三年。","官程算得无多日，莫为渊明靳酒钱。"]},{"t":"篁墩先生挽诗","f":"五言古诗","c":["理学龙门后，文章太史公。","蜚腾当景运，简注切渊衷。","载笔皇猷润，传经帝业崇。","芬华沾草木，名姓熟儿童。","琬琰镌磨遍，川源涤溉空。","为霖须海内，骑尾忽天东。","往事浮云改，遗书列屋充。","掀髯怀指授，擿埴叹颛蒙。","怅望仙衢远，追攀逸驾穷。","南山秋月夜，愁断白杨风。"]},{"t":"进士熊世芳太仆陆献臣先生令新建时所造士也奉使过家先生赋诗为其尊人寿要予同作","f":"七言律诗","c":["邂逅春风识凤雏，又随群彦送轺车。","人看白发迎门日，路是青云发轫初。","寿酒正宜桑落后，舞衣犹带御香馀。","只应喜杀洪都尹，亲见挥金为买书。"]},{"t":"彭景武出守过家索诗为其尊人寿","f":"五言古诗","c":["振铎俱成绩，悬车不待年。","青山同洛社，红日在尧天。","名德存诸老，勋庸付后贤。","庭趋看五马，堂集记三鳣。","天与龄如鹤，人知祖姓篯。","寿杯醲若露，仙果大于拳。","俨雅吴黉像，飘摇蠡浦船。","圣恩殊未艾，玉帛伫登延。"]},{"t":"与原复饮时章宅夜冒雪归马上联句","f":"七言律诗","c":["灞桥诗思玉河东，客散重城夜向中。","皓白暗欺云路月，清寒时拂帽檐风。","十年江外孤篷远，此夕灯前一盏同。","明发趋朝看晴景，水精浑琢大明宫。"]},{"t":"次日夜酌用前韵 其一","f":"七言律诗","c":["明朝尘海各西东，莫惜清欢此夜中。","韵好不妨还用雪，杯深那复畏冲风。","阅来世事常多感，语到心期每自同。","飞矢夺枭成一笑，插花犹忆醉南宫。"]},{"t":"次日夜酌用前韵 其二","f":"七言律诗","c":["插花犹忆醉南宫，尊酒三年此会同。","嘉绩已看书上考，醉吟何惜到春风。","楸枰的历棋分角，壶耳铿鍧矢跃中。","回首不堪凝望眼，白云长满五湖东。"]},{"t":"李叔渊父寿七十八","f":"七言律诗","c":["世味真应染指休，太行千亩即菟裘。","天书有宠红裁锦，春酒无时绿满瓯。","到处烟霞宜杖屦，会心花鸟自林丘。","新年八十相将近，更伴庄椿一度秋。"]},{"t":"御医杨信之故宅在玉河东涯有花竹山石之胜时行借居有作次韵","f":"七言律诗","c":["满城车马此堂閒，招隐真堪赋小山。","花竹四时春不断，琴书列屋昼常关。","开尊又喜逢青眼，携手还思弄碧潺。","却怪相期数相迕，早朝常隔殿西班。"]},{"t":"记十一月十九夜梦","f":"七言古诗","c":["夜梦飞行万山顶，下视黄河如汲绠。","仰观明星万银饼，青天倒垂碧瑶鼎。","大冶神光赤霞炯，我暂窥之百夫警。","东北玄云突如猛，上冲层霄失参井。","若华欲舒震方炳，人间寂寥万物瞑。"]},{"t":"送原复","f":"七言律诗","c":["阙下恩光动锦袍，东行未觉故山遥。","云当驿路还停马，酒溢春杯拟颂椒。","归日诸园花并发，拜时双鬓雪全消。","何因暂作称觞客，醉拥蓝舆过午桥。"]},{"t":"江西傅生复立其远祖学士初庵书院于其乡体斋宗伯先生属为赋诗","f":"七言律诗","c":["前朝学士有闻孙，能读家书习旧闻。","远道不辞来上国，名山时为访遗文。","青毡次第还初观，白马联翩向暮云。","遥忆精庐清夜永，一灯还与列斋分。"]},{"t":"庭树着雪宛若梅花遣兴一首","f":"五言古诗","c":["朔风吹庭树，岁晚益萧疏。","同云散微雪，披拂下寒虚。","旖旎轻点缀，芳华在须臾。","感此岁寒物，念我田园居。","岂不信假合，凭轩亦欣如。"]},{"t":"冬夜德卿希大徵伯过访","f":"五言古诗","c":["良夜宾友集，开尊坐南轩。","华月照两楹，炽炭回春暄。","妙语入肯綮，雅歌振清温。","共言会晤难，菲恶愧盘飧。","且复延兹赏，明发又尘樊。"]},{"t":"雪中思南夫迥碧楼戏简","f":"七言绝句","c":["迥碧新题几首成，无人曾见雪天清。","晚来剧有山阴兴，忆著袁安未敢行。"]},{"t":"除夕招王德馨","f":"七言绝句","c":["客舍长安岁屡迁，屠苏明日又新年。","共君只向灯前醉，免与儿童计后先。"]},{"t":"送僧还妙严已未斋居泰鲁山僧舍作","f":"七言律诗","c":["鹤城西北古招提，十载长安梦不迷。","我正凭阑送归目，君来卓锡话留题。","邯郸枕里三生速，瀛海天南一雁低。","幽径小轩何日到，碧流长绕画廊西。"]},{"t":"再赋","f":"五言古诗","c":["夜宿端公房，念与永公别。","青灯淡疏棂，起坐见微月。","野鹤飞无定，笼鹰动遭掣。","翩然思南翔，神爽渺飞越。","精蓝古城隈，台殿高嵽嵲。","幽房回曲径，只尺人境绝。","公持桑下意，我忆云门袜。","他年续清游，还放西潭枻。"]},{"t":"庚申斋居和钱世恒佥宪","f":"七言律诗","c":["频年僧室共郊斋，引接多惭降等侪。","诗老渐看过大历，语真时复到无怀。","好风先夕知清道，朗月中天想燎柴。","明日衢尊又承庆，还同既醉舞尧阶。"]},{"t":"庆成燕和张南山","f":"七言律诗","c":["日高仙跸殿东来，鹄立帘前候扇开。","舞队夹门参马象，衢尊当陛绕云雷。","宠承天语亲教坐，清列卿班独许陪。","连日玉河惊纸贵，遍传新制咏台莱。"]},{"t":"前题奉次侍读白先生韵","f":"七言律诗","c":["紫盖前头拥八鸾，日华流彩映天颜。","升中庆衍三朝会，供奉筵高六品班。","众乐送觞仙调缓，诸番入队舞衣斑。","明朝齐和阳春曲，谁复周京咏北山。"]},{"t":"和孚若咏雪三首 其一","f":"七言律诗","c":["微阳犹伏地中雷，寒勒江云势未回。","啁哳渐多篱外雀，浮沉频拨瓮头醅。","占年有喜先知麦，拟赋无能且用梅。","晓起江山尽银海，更容神女著芦灰。"]},{"t":"和孚若咏雪三首 其二","f":"七言律诗","c":["帘旌不动晓来风，一刻瑶花满太空。","神用莫窥龙变化，幽踪谁别兔雌雄。","先生东郭行应遍，公子西园兴未穷。","便欲君王借千骑，夜驱残甲出云中。"]},{"t":"和孚若咏雪三首 其三","f":"七言律诗","c":["书生裘褐自无兼，雪意连旬未解严。","天上烂开群玉府，人间那有却寒帘。","檐栖白凤遥分势，阙映苍龙已没尖。","能赋只应输子建，百篇信口不停占。"]},{"t":"再和煮雪雪山二首 其一","f":"七言律诗","c":["玉铉金觞未许拈，陶家风致我何嫌。","云英一化春无迹，乳脚初翻火正炎。","真乐故应儿女笑，清欢那得故人兼。","风窗细啜诗成后，何物中边数蜜甜。"]},{"t":"再和煮雪雪山二首 其二","f":"七言律诗","c":["群儿痴绝不知寒，搏雪中庭作幻观。","忽讶海波晨涌地，更疑华顶夜凭阑。","斜侵院竹惊枝短，清逼皋禽觉袂单。","不用孙龙较同异，浮生只合此俱看。"]},{"t":"并蒂瓜榴为钱世恒赋","f":"五言古诗","c":["瓜蔓远更硕，榴房寒始红。","由来重嘉实，不必当春风。","君看小山植，朱碧秋重重。","间出或偶尔，俱骈岂人工。","必有千里驹，为君叶维熊。","如机云轼辙，方驾凌紫虹。","善颂敢云我，深培本缘公。","他年记父执，无忽丹青功。"]},{"t":"元夕匏翁宅次马宗勉少卿韵","f":"七言律诗","c":["瀛海风光自一家，衣冠此日共清华。","奉常彩笔飞千兔，学士银屏簇万花。","看到春城无此盛，传来郢曲拜君嘉。","宾筵喜气晨犹在，散作东园五色霞。"]},{"t":"再和匏翁韵","f":"七言律诗","c":["玉署东来第一厅，元宵灯火灿银屏。","青云幸接诸公武，白雪犹疑隔岁听。","江海几人思旧雨，烟霄此地拱繁星。","宁知起草明光夜，别有金莲彻晓停。"]},{"t":"遣天彝归省 其一","f":"五言律诗","c":["遣汝宁容易，高堂念久违。","书将锦字寄，心傍白云飞。","干誉知吾意，承欢羡尔归。","有怀言莫尽，愁立到斜晖。"]},{"t":"遣天彝归省 其二","f":"五言律诗","c":["地是承家重，年今抱子馀。","出门初托汝，念别正愁予。","乡党先亲旧，川途慎起居。","由来荣故里，非必在高车。"]},{"t":"遣天彝归省 其三","f":"五言律诗","c":["吾家寒薄味，汝顷及亲尝。","莫以花间日，都忘叶上霜。","容仪师抑抑，裘马戒扬扬。","自古谦恭子，名高禄寿昌。"]},{"t":"遣天彝归省 其四","f":"五言律诗","c":["槿花随日殒，松柏入云高。","树德由先世，沾恩到尔曹。","亲贤衣袭麝，从恶火消膏。","看取盘中粟，耕耘亦甚劳。"]},{"t":"遣天彝归省 其五","f":"五言律诗","c":["八年违故里，此别更悬心。","伎俩人看汝，承传始自今。","罗囊知不带，缃卷亦时寻。","勿忘临行语，风来伫好音。"]},{"t":"和良金咏雪","f":"七言律诗","c":["白战功成四百年，骚坛弧矢到君拈。","中天屡合鴐鹅阵，小帐犹歌阿鹊盐。","弄影月娥回缟练，散花天女敛柔尖。","不辞强步同高韵，鸿迹春来几处添。"]},{"t":"送陈瑞卿还临清为其子天泽赋","f":"五言古诗","c":["驱车戒行迈，复此官道周。","昔来冰雪交，今还风日柔。","青骢系柳枝，好鸟鸣相求。","冠盖罗四筵，眷言各绸缪。","感此自难别，况怀瓜葛忧。","清源雄剧地，南北当襟喉。","选代苦不易，眷毗良以优。","暂割骨肉恩，且为旬月留。","长安富车马，迟尔看来游。"]},{"t":"送东平守张元之赴黎平","f":"五言律诗","c":["东州棠树好，又剖越南鱼。","地域衡潭尽，星文翼轸馀。","长才须历试，远俗贺宁居。","已有侏㒧子，循山候隼旟。"]},{"t":"嘲卫景玉","f":"七言绝句","c":["闻说城西射雁归，水清沙冷雁高飞。","将军不是无长箭，为惜春风好羽衣。"]},{"t":"题张通判春江载月图","f":"五言律诗","c":["月出大江平，仙舟上国行。","回帆混天影，发棹动春声。","远树光疑湿，虚窗梦与清。","知君济川具，聊复试初程。"]},{"t":"送李徵伯之曲阜","f":"五言古诗","c":["远游君未曾，发轫便东鲁。","平生仰止心，一往了千古。","尼聃本通家，复此缔姻与。","岂徒升门堂，行且窥奥序。","君才自豪宕，云梦口吞吐。","兹行信天假，为尔辟襟宇。","冥搜穷日观，旷览极鳌屿。","必有浩荡辞，凌风振珩瑀。","念君千金躯，垂堂有前语。","圣言本非外，吾道足自取。","归哉慎勿迟，高堂念风雨。"]},{"t":"又次钱世恩韵","f":"五言律诗","c":["问道趋东鲁，联舆有稚圭。","侍闱看乍远，吟辖动还齐。","观海云浮地，登山月傍梯。","预知篇翰富，双从锦囊奚。"]},{"t":"访陈时雨不遇次刘文敷韵","f":"七言绝句","c":["童子应门语自真，锦囊何处觅阳春。","刘郎莫叹空归去，更有斜阳独坐人。"]},{"t":"毛閒翁百岁预寿","f":"五言古诗","c":["天子十四载，昭阳纪灵辰。","间翁寿百岁，弧筵启青春。","孙子天上归，板舆奉慈亲。","扶携献春酒，盛事倾海滨。","我明始驭宇，元气会九垠。","历岁三十馀，六合熙同仁。","翁实生此时，所得固已淳。","葆真遗世网，委顺随化钧。","自从结发来，白首如一晨。","譬彼凌寒松，本异凡卉伦。","动息有至理，往来无杂宾。","閒居谈往事，听者疑古人。","尝言十六七，文皇当北巡。","金舆映朝日，目睹天人真。","自攀鼎湖龙，五拜重光新。","虽微海田变，冠盖几湮沦。","念此劝翁饮，无负尊前身。","南山晚更绿，时菊长精神。","悠然东篱下，想见无怀民。","愿得假羽翼，杖几承清尘。","作诗预为寿，转盻莺花瞵。","从今岁一篇，积卷如车轮。"]},{"t":"兵部侍郎杨公挽诗","f":"七言律诗","c":["乞归未许更承恩，总为朝廷仗老臣。","帷幄尚纡千里策，冰霜已瘁百年身。","中州清气还嵩洛，后代公言属缙绅。","一卷昆山去思录，便应谈笑离风尘。"]},{"t":"寿刘碧窗","f":"七言律诗","c":["半欹乌帽引清觞，无柰斑衣绕膝长。","百岁好怀当此日，一年佳节尚重阳。","黄花近竹深承露，绿橘辞林浅带霜。","既醉有诗还自庆，只应身健咏时康。"]},{"t":"题潞河别意卷","f":"七言绝句","c":["两字功名一剑歌，舟航南北乱机梭。","夕阳沙上流连意，只有青山见最多。"]},{"t":"春江漫兴","f":"古风","c":["人间七贵五侯，江湖蒻笠羊裘。","细雨鸳鸯沙上，微风舴艋船头。","侬家五湖迤东，此意于君更浓。","一派桃花流水，十年马首西风。"]},{"t":"送友人","f":"七言律诗","c":["清凉国里列仙儒，坐拥溪山画不如。","黄卷上堂朝日后，青衿分閤晚灯初。","晴岚捲翠遥侵户，瀑水分光欲浸裾。","便欲从君寻九曲，隐屏仙掌更萦纡。"]},{"t":"送刘宗哲进士尹束鹿","f":"五言律诗","c":["长材宜德选，望邑丽神州。","黄甲非身贵，青箱本国谋。","弦歌深里巷，雨露足田畴。","矫首西山月，清光夜夜秋。"]},{"t":"孚若时章约九日广恩寺登高雨不及赴","f":"七言律诗","c":["白云观西红叶堆，重阳有约携尊罍。","游人不出看白雨，老僧闭户生青苔。","乾坤此景复几尔，造化于物何廉哉。","未能骑马且独酌，菊花许我明朝开。"]},{"t":"戴溪山挽诗 其一","f":"七言绝句","c":["海鹤东飞不记程，溪山犹是昔时清。","城门傥有重来日，应笑儿童白发生。"]},{"t":"戴溪山挽诗 其二","f":"七言绝句","c":["末俗崎岖巧智多，纷纷夭札柰愁何。","青山不尽思公意，落日空闻伐木歌。"]},{"t":"赋栖翠楼送曹良金出使归省","f":"古风","c":["群山绕湖湖绕山，高楼突起湖山间。","湖光如蓝山如黛，云近百里趋凭阑。","主人不出日高坐，笑弄烟雾招云鸾。","云鸾空飞渺无迹，但见苍苍竹树相回环。","芳荪小松亦何意，点缀几格娱清閒。","大郎新归自天上，春衣五色宫花斑。","楼前拜舞楼上醉，山水亦似回欢颜。","烟凝不知晚色改，潦尽更觉湖波宽。","登高作赋远莫致，目极吴江枫叶丹。"]},{"t":"送罗允恕归省","f":"七言律诗","c":["满庭兰玉翠交加，近日西江更几家。","累叶书香传祖父，同时科甲际亨嘉。","三秋别思初惊雁，五色宫袍重染霞。","为问山中閒太史，也应飞梦向东华。"]},{"t":"题石田春江钓鱼图","f":"七言律诗","c":["重江迢递水烟通，天设沧洲著钓翁。","返照入山迷紫翠，平林过雨杂青红。","閒边岁月真输子，忙里莺花正恼公。","为问中流容点笔，扁舟画我载泠风。"]},{"t":"题竹送阮大经还金陵","f":"七言绝句","c":["十载江东忆旧游，竹林斜日坐深秋。","长安道上红尘满，赖有清风消客愁。"]},{"t":"谭雅祥使归寿母","f":"七言律诗","c":["皇华夹道拥归装，喜气遥看满北堂。","天上瑞云垂五彩，人间佳节傍重阳。","早时贤范熊丸在，再世诸孙玉树长。","七十一峰青在望，若为登拜捧霞觞。"]},{"t":"罗先生归田八景为赋其四 其一 三顾书台","f":"五言古诗","c":["云表三青巘，萧生昔栖迟。","缃素久已散，荒台仍故基。","落日循岭圃，逍遥面崔嵬。","当年选幽胜，花竹绕阶墀。","千龄亦未远，俯仰有馀悲。","勿讶岩居子，缅想希安期。"]},{"t":"罗先生归田八景为赋其四 其二 双溪道院","f":"五言古诗","c":["双溪走岩麓，上有真仙居。","萧爽荫珠树，虚閒开玉除。","先生读易罢，杖屦或来于。","东寮紫鸾笙，西馆青霞裾。","招摇弭绛节，想象凌清都。","日暮篮舆去，天风送步虚。"]},{"t":"罗先生归田八景为赋其四 其三 中林社鼓","f":"五言古诗","c":["高榆荫灵境，秩祀岁有虔。","烹羊击我鼓，老稚走纷然。","落日更起舞，酣歌间骈阗。","少壮远行役，投老归农田。","乡邻既无故，孙子亦多贤。","但愿岁常稔，听此终馀年。"]},{"t":"罗先生归田八景为赋其四 其四 古寺梵钟","f":"五言古诗","c":["梅花搅我梦，欹枕五更初。","头陀闵群昧，霜金吼桐鱼。","一击尘梦醒，再声灵襟虚。","须臾万籁动，鸣鸡遍前墟。","起坐视檐隙，明星犹在隅。","却忆长安日，整冠趋朝车。"]},{"t":"送刘景星教肥乡","f":"七言律诗","c":["常日黄梁说梦游，明朝匹马度邯沟。","山连王屋排空下，云在天门抱日浮。","枕里卢生迷岁月，皮间季野有阳秋。","丈夫功业时来建，肯向青藜叹白头。"]},{"t":"孚若出示乃兄九三先生瑶草篇敬题其后","f":"五言古诗","c":["达人遗世网，心与元化冥。","高居养灵和，土石被华精。","英英庭下草，罗骈不知名。","明冰比皓质，文玉擢修茎。","群芳不敢伍，煜煜扬翘英。","我愿采掇之，恐是玉山粳。","持以莳千亩，媲彼尧阶蓂。","路远伤后时，怅望吴峰青。","载歌小阮词，感我金兰生。","青云果善颂，白雪宛遗声。","馀芳倘许拾，相携泛蓬瀛。"]},{"t":"为卢悦清题竹四首 其一","f":"五言绝句","c":["卢郎老益清，正似雪中竹。","岁寒林下游，还许王猷续。"]},{"t":"为卢悦清题竹四首 其二","f":"五言绝句","c":["雷雨过前溪，竹色犹黯惨。","泥中有龙孙，戢戢露头颔。"]},{"t":"为卢悦清题竹四首 其三","f":"五言绝句","c":["风吹楚云去，一半在君山。","帝子不可见，江空闻佩环。"]},{"t":"为卢悦清题竹四首 其四","f":"五言绝句","c":["凌晨步东林，满地散珩瑀。","举头见朝阳，傍有青鸾舞。"]},{"t":"沈石田画杨君谦僧普泰雪夜谈玄图","f":"七言绝句","c":["石田山水此第一，仪曹鲁山迹亦奇。","月明满天雪在地，听取两翁无语时。"]},{"t":"为定默然题吴僧画兰二首 其一","f":"古风","c":["猗猗芳兰，在彼幽谷。","孰为我徒，清泉修竹。","清泉涓涓，修竹苍苍。","荪也可人，蔚乎相望。","明窗若空，左右图史。","永言诸君，乐自今始。"]},{"t":"为定默然题吴僧画兰二首 其二","f":"古风","c":["吴有高人，得笔三昧。","洒墨飞空，坠不沾地。","化为幽兰，殊妙特妍。","相所于归，繄定默然。","煜煜者兰，岩岩者石。","咨尔丛林，兹焉作式。"]},{"t":"山水小景","f":"七言绝句","c":["江柳青青带薄烟，鸬鹚飞尽水如天。","幽人看得青山熟，一任东风拍钓船。"]},{"t":"送费千户袭职还松","f":"七言律诗","c":["流水平林带郭斜，将军门巷野人家。","百年勋荫馀乔木，三月春风想落花。","何日燕游还此地，向来谈笑即抟沙。","王师未斩楼兰首，看尔腰间似莫邪。"]},{"t":"和许启衷给事春日","f":"七言绝句","c":["细雨閒门客到稀，偶临池水见晴晖。","浮萍本是风中絮，争得还随柳絮飞。"]},{"t":"即事和前人","f":"七言律诗","c":["新出燕雏不记归，清晨捲帘到夕晖。","苔痕渐于细雨长，榆荚正得斜风飞。","北边稍喜烽火息，南国却嗔鱼雁稀。","赖得相期有钟子，未应终遣壮心违。"]},{"t":"邃庵","f":"古风","c":["达人隐城市，端居穆幽深。","虽当车马交，而无尘土侵。","侧径入迤?，层轩递明阴。","萧森间水竹，窈窕想云岑。","朝回隐几坐，幽意宛山林。","想当缔构初，岂有远世心。","抗席展图史，分庭盍朋簪。","覃恩穷海岳，清言振璆琳。","譬彼九皋唳，风听彻重阴。","鸿飞二十载，俯仰成古今。","高云复南逝，何时续幽寻。","行窝倘有作，千里续遗音。"]},{"t":"送杨承家","f":"五言古诗","c":["邃翁天下奇，之子亦超越。","琅玕映珊瑚，文采争焕发。","识君虽未几，一见眸已豁。","方期托芝兰，告别何仓卒。","江东名胜地，京口豪隽窟。","槐黄逼秋期，腹笥撑突兀。","三杯脱宝剑，百步挽明月。","穿杨何足奇，会见石羽没。","清江柳方绵，紫陌花未歇。","晴空正无云，万里见孤鹘。"]},{"t":"送宫谕李子阳先生赴南京太常少卿","f":"七言律诗","c":["典学东朝旧史臣，南台礼乐荷新恩。","百年景运当熙洽，三代遗文入讨论。","花竹竞誇官署好，江山深拱帝京尊。","只愁未了閒居赋，又被东风催北辕。"]},{"t":"刘舜卿祖父母挽诗","f":"五言律诗","c":["极目襄垣道，萧萧落叶秋。","人犹避骢马，梦已隔丹丘。","比穴看明镜，同归想玉楼。","馀芳知未歇，孙子在瀛洲。"]},{"t":"沈廷用以尺籍事来京却归赋别","f":"七言律诗","c":["老去江湖气未消，欲将长剑倚云霄。","十年几作登楼梦，一笑元非折简招。","枥下尽馀宛騕袅，军中谁是霍嫖姚。","浩歌一曲指归路，白鹤城西又晚潮。"]},{"t":"送张信卿知归德州","f":"五言律诗","c":["短亭官柳下，长路酒杯前。","待解薰风缆，频回落日鞭。","龚黄新宠命，梁宋古山川。","去去应传得，歌谣满日边。"]},{"t":"送陈玉畴提学南畿","f":"五言古诗","c":["圣学久不讲，斯文日陵夷。","纷纷事佔毕，青黄互镌追。","岂无豪隽人，柰此场屋縻。","离章务迎合，出意追新奇。","公言著简册，启彼捷径岐。","坐令青衿子，释耒拾秉遗。","所操谅如此，即事吁可知。","陈侯儒林彦，宪府久声驰。","以彼冰檗操，树此文章麾。","色笑春雨霁，槚楚秋霜威。","矧伊根本地，允矣列郡规。","指挥苟有向，风行草争靡。","走也章句士，久堕荆棘蹊。","前瞻若有见，内顾靡所施。","六籍本大道，旁搜竟奚为。","赠言剧深愿，迥澜此其时。"]},{"t":"石邦秀侍御再按陕西乃弟翰检先生索赋 其一","f":"七言绝句","c":["又见皇华映陕郊，遗民应念使君劳。","关河尚有风尘警，弹压还须在绣袍。"]},{"t":"石邦秀侍御再按陕西乃弟翰检先生索赋 其二","f":"七言绝句","c":["青云双凤立朝阳，綵笔春生白简霜。","心识西行非远别，夜来绿草满池塘。"]},{"t":"沈士登初入学梦人诵诗有细丝曾钓海鳌来之句是岁集选得富春丞乃子陵隐处因赠此诗","f":"七言律诗","c":["梦里金鳌忆细丝，桐江只在富春西。","久知万事皆前定，肯向浮生叹不齐。","坐上溪山明画鹢，人间岁月等醯鸡。","两株松外千竿竹，吟得新诗到处题。"]},{"t":"蒋济民自光禄署丞调主靖安簿满考入京乞致仕赋以送之","f":"七言律诗","c":["黄龙浦南云水乡，八月鲈鱼三尺长。","远游不柰乡思苦，归去正及秋风凉。","内朝供奉参鹭羽，西江抚字留甘棠。","丈夫事业无小大，看取老圃寒花香。"]},{"t":"王师仁少宰挽诗","f":"七言律诗","c":["曾瞻旌旆立江边，过眼棠阴二十年。","黄阁盐梅閒老手，青山松桂富新篇。","人高晚节踰三让，帝有馀恩贲九泉。","拟奠生刍不知处，碧云无际海南天。"]},{"t":"王思德寄歙研吴笺","f":"七言律诗","c":["歙样新传胜紫琳，函封远自柏台深。","隐光似截波间玉，涵润长流月畔金。","笺素一时争焕发，烟霞当日记追寻。","西江使节冰霜重，泚笔銮坡伫好音。"]},{"t":"东阙池上作次杭世卿吏部韵","f":"七言律诗","c":["灵沼溶溶雨欲飞，水东林苑望中微。","云光倒涌金堤去，寒色遥从锦树归。","诗出镐京歌在藻，地因龙首忆承晖。","君王自是稀游衍，鱼鸟无从识画衣。"]},{"t":"李徵伯挽诗 其一","f":"五言古诗","c":["鸣雨送残夜，青灯黯无光。","坐念绝代人，今古永相望。","美德岂足恃，令我初志荒。","忽复疑梦假，衾襚已充箱。","掩涕不忍视，起步空徊徨。"]},{"t":"李徵伯挽诗 其二","f":"五言古诗","c":["忆昨听鹤亭，与君初接言。","神交四千里，从此成弟昆。","诵我避水书，意气蔼兰荪。","十年事几变，俯仰犹旦昏。","已矣萧朱心，伤哉复谁论。"]},{"t":"李徵伯挽诗 其三","f":"五言古诗","c":["间岁苦离索，旧游若云萍。","与君每共叹，忍复此长瞑。","元龙按近甸，旦暮涕已零。","遥遥两汪子，此信何时聆。","虚檐团云影，永夜双烛荧。","清欢可复继，即此成千龄。"]},{"t":"李徵伯挽诗 其四","f":"五言古诗","c":["数短得气清，才高与时龉。","黄鹄当摩空，岂复须再举。","乃知摧折意，造物忍如许。","空梁飘素帷，幽架落残楮。","矫首青云衢，槐黄泪如雨。"]},{"t":"李徵伯挽诗 其五","f":"五言古诗","c":["元宾既无禄，长吉亦早亡。","古人泪未尽，今子重夭伤。","憎能岂天心，念此谁纪纲。","綵㡛饰文木，袭君锦绣肠。","下入三泉底，千秋长閟藏。","惟应箕尾际，永夜腾光芒。"]},{"t":"李徵伯挽诗 其六","f":"五言古诗","c":["生死犹寤寐，昔人屡言之。","梦君执我手，明言两无疑。","问死恨草草，怀存亦依依。","及论重来理，调笑名我痴。","肯綮出妙语，徘徊指还岐。","幽林犹彷佛，高垄俨崔嵬。","永念结沉痛，萧条谁与归。"]},{"t":"松岭长春为周淳甫母寿","f":"七言律诗","c":["匡山回望翠成林，春色分明此地深。","雨露独承千载润，冰霜不异一生心。","高标彷佛丹梯外，佳气氤氲碧涧浔。","何日潘园奉周览，东风十里步清阴。"]},{"t":"张廷肃宪副致仕归中途得二郎子德捷报","f":"七言律诗","c":["先生绣斧辞荣日，令子青云擢秀年。","宦辙九霄馀熟路，书香一脉是真传。","傍阶霜菊深承露，夹户星榆欲造天。","惆怅无因接宾燕，碧山回望渺风烟。"]},{"t":"画马为内学生题","f":"七言律诗","c":["毵毵嫩绿垂杨短，冉冉晴沙御堤软。","骅骝行惯稳不惊，圉人徐牵不教远。","飞黄食料三品丰，青丝络首飘风騣。","曾见沙场征战苦，方知此物是真龙。"]},{"t":"冬至谒陵次允升太史送行韵","f":"七言律诗","c":["出门愁望北风骄，百里园陵亦未遥。","馀雪印堤尘不动，诸山迎日雾全消。","松楸夹道如前日，冠佩中天限此宵。","想得群仙会朝罢，并瞻云物庆丰饶。"]},{"t":"雪山次吴宁庵先生韵 其一","f":"七言律诗","c":["夸娥失喜巨灵号，腾六平分缩地劳。","孤牖忽惊银海立，两峰谁论玉山高。","嵚岩似欲生云母，融液犹堪瀹涧毛。","为报朝阳莫相妒，先生吟笔正翻涛。"]},{"t":"雪山次吴宁庵先生韵 其二","f":"七言律诗","c":["未雪风姨已怒号，为山无乃雪重劳。","人间牟麦明年富，坐里蓬婆一夜高。","目眩有时还拄笏，神游他日想寒毛。","阳坡数曲如溪涧，应待春风送海涛。"]},{"t":"良金秋官录囚江右有发其同官不谨事者所司衔旧怨窜君名其中调东昌督马通判众知其诬而莫与辨也诗以送之","f":"七言律诗","c":["东观图书共昔年，西曹风月许联编。","论心合在青云上，抚事空嗟白璧前。","晓日鹓鸿犹尺只，春风駉駜又三千。","池鱼塞马俱休论，且读南华第一篇。"]},{"t":"壬戌元宵应制绝句八首 其一","f":"七言绝句","c":["楼前灯火合彤霞，云里箫韶引翠华。","散出黄柑齐拜赐，玉皇遥在七香车。"]},{"t":"壬戌元宵应制绝句八首 其二","f":"七言绝句","c":["两宫慈寿极尊亲，圣主承欢一万春。","放出金莲长不谢，扶来玉辇静无尘。"]},{"t":"壬戌元宵应制绝句八首 其三","f":"七言绝句","c":["银幡赐了敕观灯，次第风光满镐京。","看到筵前鸠拂舞，九农春事已关情。"]},{"t":"壬戌元宵应制绝句八首 其四","f":"七言绝句","c":["华星宝月满长安，绣屋金釭夜未阑。","遥望千门起庭燎，尚宫先辇奏回銮。"]},{"t":"壬戌元宵应制绝句八首 其五","f":"七言绝句","c":["紫坛回仗溢天津，特策金吾弛夜巡。","为有蕃禧助阳令，六街花柳一时新。"]},{"t":"壬戌元宵应制绝句八首 其六","f":"七言绝句","c":["宵旰忧勤十五年，鳌山灯火亦初筵。","小臣未识鱼龙戏，中宴先歌蟋蟀篇。"]},{"t":"壬戌元宵应制绝句八首 其七","f":"七言绝句","c":["紫檀红蜡夜频添，万岁声中乐未厌。","华月正当云母障，微风莫动水精帘。"]},{"t":"壬戌元宵应制绝句八首 其八","f":"七言绝句","c":["乾清前殿夜将分，万烛交光绚綵云。","传敕明朝散灯宴，词臣好进劝农文。"]},{"t":"后二日有旨再赋律诗四首 其一","f":"七言律诗","c":["乐岁逢春物物宜，圣人行乐是乘时。","天垂玉烛三千纪，地涌金莲十万枝。","星阁捲帘红日近，虹桥按曲綵云迟。","愿因欢庆思幽隐，更法光明事缉熙。"]},{"t":"后二日有旨再赋律诗四首 其二","f":"七言律诗","c":["千灯高列奏宫悬，五凤齐飞拱御筵。","春到上元真富贵，月临双阙正清圆。","甘泉西北长无警，瀛海中间大有年。","暂弛金吾三夕禁，未妨宣室九宾延。"]},{"t":"后二日有旨再赋律诗四首 其三","f":"七言律诗","c":["好景新春属上元，蓬山排日会群仙。","丛金间玉灯千树，翔凤回鸾月一天。","直以升平留燕赏，肯将光景付流连。","綵云遥望笙歌合，知奏邠风第几篇。"]},{"t":"后二日有旨再赋律诗四首 其四","f":"七言律诗","c":["紫皇宫阙夜通明，飞阁回廊白昼行。","宸极本同天下乐，霓裳不度月中声。","河山表里归全盛，云物光华溢太清。","愿祝圣人千万寿，年年灯火看升平。"]},{"t":"许百户从军普安州至潞渚卒时其子鲁从予游赋此吊之","f":"七言律诗","c":["拟作燕歌赠粤行，剑棱中断不成声。","一天冻雨红旗敛，万里炎烟碧草横。","假息忍看徵侧在，裹尸谁吊伏波营。","伤心最忆湖阴路，垂柳閒门几送迎。"]},{"t":"郊行忆徵伯与德卿希大联句 其一","f":"七言律诗","c":["故人丘垄望中孤，古木荒村旧路纡。","野奠有怀空酹酒，交游无兴更携壶。","人间流落文章在，梦里依稀涕泪枯。","此日九原如可作，问君曾记玉楼无。"]},{"t":"郊行忆徵伯与德卿希大联句 其二","f":"七言律诗","c":["把笔英姿在眼中，笑谈曾共此堂东。","乾坤苍莽游何处，花雪追随梦未终。","价重连城惊毁璧，气消神骏想追风。","悲歌亦是伤春调，却与伤春调不同。"]},{"t":"郊行忆徵伯与德卿希大联句 其三","f":"七言律诗","c":["石桥归路又斜阳，旧日经行宛未忘。","何物山川收间气，向来星斗避寒芒。","青乌未卜前冈吉，白雪空传下里章。","一滴九泉今定到，骑龙休问白云乡。"]},{"t":"送道士周翠岩还松江","f":"七言律诗","c":["飙轮不到海东头，梦里三山日夜浮。","归去有时应驾鹤，别来几处见乘牛。","风清晓殿思金磬，云淡春空送綵辀。","借问赤松千载后，幅巾还许伴清游。"]},{"t":"送萧指挥还金山","f":"七言律诗","c":["将军承宠出明光，归骑东风满路香。","家有六韬藏虎豹，身堪百战扫豺狼。","北来烽火边无警，南去波涛海不扬。","细柳绕营春日静，雅歌谁与共壶觞。"]},{"t":"寄高曾唯","f":"七言律诗","c":["千里南河入望赊，美人有约赋皇华。","乡音不远经冬雁，云路常瞻八月槎。","官好水曹清彻底，名高玉树净无瑕。","北堂春日花如锦，时向公馀奉小车。"]},{"t":"送吴汝玉下第用己未春韵","f":"七言律诗","c":["建业西风忆系舟，燕台此别又经秋。","也知和璧终传世，恨向荆江复倚楼。","且莫临岐伤远道，要须游刃视全牛。","长安春色年年似，一样王孙烂漫游。"]},{"t":"送百户徐钦袭职还松江","f":"七言律诗","c":["曲墙垂柳荫清池，十载高门路不迷。","尽说柏舟同节苦，惊看玉树与云齐。","恩光晓日瞻龙仗，行色秋风入马蹄。","拂拭家藏旧弓剑，从今步步上丹梯。"]},{"t":"赋蟠桃图为张时震父母寿","f":"七言律诗","c":["玄洲髣髴海东涯，海岸蟠桃大比瓜。","画入彩缣疑着雾，望迷仙苑欲生霞。","稀年令德真相配，紫府丹台别是家。","我欲金壶借馀墨，一枝并写杏园花。"]},{"t":"维扬魏文璧工诗能琴善画幅巾布袍游京师萧然不与尘土杂将还与德卿御史各赋诗送之","f":"七言律诗","c":["清沟绿树绕江都，树里人家画不如。","舣棹十年同过鸟，临流此日羡閒居。","乾坤老眼丹青在，江海神游梦寐馀。","西北月湖连甓社，几时携手弄明珠。"]},{"t":"题扇寿爱蔬吴先生尊人","f":"七言绝句","c":["江海归来一幅巾，东风八十四回春。","日长勘罢参同契，坐对青山即故人。"]},{"t":"泰和萧生将赴临汀驿留三日为予写真赋此为赠 其一","f":"七言绝句","c":["本自烟江坐钓矶，春风强使著荷衣。","不知面目从来假，更与萧郎问是非。"]},{"t":"泰和萧生将赴临汀驿留三日为予写真赋此为赠 其二","f":"七言绝句","c":["南望临汀路八千，皇华四牡日纷然。","江湖或有商岩相，倘可因君送上天。"]},{"t":"送张晦夫长史之沂州","f":"七言律诗","c":["犹记征车逐后尘，离亭回首十经春。","衣冠稷下谁公右，礼乐河间合此新。","长日横经当便坐，有时纡锦见乡邻。","绿杨骑马城坳路，应向西风忆故人。"]},{"t":"还金行为叔武郎中赠济南姚龙","f":"七言古诗","c":["故人留金儿不闻，故人已死人谁云。","昨日结交今有变，何况天涯生死分。","延州挂剑事已矣，济南高风见吾子。","金还故人事则已，事吾当然非有以，江海千秋歌义士。"]},{"t":"送宁庵学士赴南院","f":"七言律诗","c":["紫清仙吏亦分曹，瀛海晴虹隔翠涛。","词下掖垣花欲动，讲回前殿日初高。","城临秋水迎飞盖，阁倚春风想运毫。","为谢白云荆渚上，楼船不似北河劳。"]},{"t":"送盛春雨还吴","f":"七言律诗","c":["未来消息满长安，小住何妨趣驾还。","海内正悬春雨望，山中谁放夏云閒。","每寻燕语多高论，转觉鸿飞不易攀。","翘首阊门烟月路，几时携酒扣玄关。"]},{"t":"哭次儿天叙寄两弟五首 其一","f":"五言古诗","c":["孤根托浅土，所赖众叶扶。","斧斤日相寻，谁能不伤枯。","根伤叶乃落，叶落根转孤。","不知天地仁，根也真何辜。","仰天天苍苍，扣地惟黄垆。","有语不可道，泪下如倾珠。"]},{"t":"哭次儿天叙寄两弟五首 其二","f":"五言古诗","c":["虎狼亦爱子，乌鸟亦恋雏。","生子不能庇，悲恨当何如。","伯也归故乡，漂泊无宁居。","仲子最孝谨，性复爱诗书。","百方挠其中，一病辞寒庐。","垂死与母言，血泪沾衣裾。","沈思不忍道，命也有生初。"]},{"t":"哭次儿天叙寄两弟五首 其三","f":"五言古诗","c":["养蠹伤桂根，击鼠伤定盆。","盆伤鼠故在，桂死蠹转蕃。","明明世间事，瞀乱与谁论。","吾儿曾闵性，至死无馀言。","念之益我痛，作诗愬烦冤。"]},{"t":"哭次儿天叙寄两弟五首 其四","f":"五言古诗","c":["十年住京国，日与忧患随。","逢人得家信，十书九攒眉。","芝兰日以瘁，荆棘日以肥。","宿累本在我，馀殃及吾儿。","种树已结子，养雏已能飞。","一朝委尘土，烦冤当告谁。"]},{"t":"哭次儿天叙寄两弟五首 其五","f":"五言古诗","c":["汝母初来时，骨肉共团栾。","依依恋微禄，幸尔免饥寒。","负乘知有愧，酷罚倘可宽。","弱女在旅殡，十年犹苦酸。","如何复及尔，中道摧羽翰。","萧条古僧房，兄妹两孤单。","疏窗对寒雨，念之伤肺肝。","何当归尔魂，恸哭淞水干。"]},{"t":"乔时章除瑞安侯训导侯实慈寿宫弟时章内翰师召子也","f":"七言律诗","c":["长乐清风动内朝，汉宫阴马宋高曹。","外家多福遵慈训，西塾延宾得隽髦。","永日青襟环讲坐，有时红烛对挥毫。","相看益重酬恩地，身是銮坡旧凤毛。"]},{"t":"南有蛮为阴子淑宪副作","f":"古风","c":["南有蛮，穴都匀，反乎覆，傲以嚚。","反噬厥主戕我民，鸱张四顾掠且焚。","繄阴侯，算若神，戢我武，绥以文。","绥之弗来歼乃群，蛮破胆，伏以驯。","释不问，弘我仁，豕入其笠吾谁嗔。","呜呼普安城，亦吾人，一不戒，血成津。","胡为不遣当使君，呜呼胡为不遣当使君。"]},{"t":"程德望祠部于书室前凿池作亭秋望落成而正之内翰适至因名其亭曰登月室曰聚奎要予同赋 其一","f":"五言古诗","c":["方塘开我前，明月出我东。","仙人骑鹤来，憩我亭之中。","调笑弄月影，徘徊吟天风。","夜久月渐高，光满池若空。","遗我丹桂枝，自携白芙蓉。","飘然凌风去，千秋怀德容。"]},{"t":"程德望祠部于书室前凿池作亭秋望落成而正之内翰适至因名其亭曰登月室曰聚奎要予同赋 其二","f":"五言古诗","c":["文星近东壁，煌煌照图书。","千秋五纬聚，煜煜联明珠。","岂徒兆文运，皇步跻亨衢。","美哉君子堂，春风迓簪裾。","高会既有以，嘉名谅非虚。","君看庭下人，星斗罗襟襦。","高朗自今始，太史徵明符。"]},{"t":"送汤千户还吴","f":"七言律诗","c":["留守将军金虎符，明光传警肃周庐。","新恩宠拜双龙阙，别路光生驷马车。","投笔书生终刻印，入关童子已抛繻。","楼船八月吴江燕，谁共雕盘荐玉鱼。"]},{"t":"宗伯傅体齐先生挽诗","f":"七言律诗","c":["两朝名德重儒绅，西掖南宫列近臣。","典礼百年归考论，文章四海入陶钧。","春风遽撤朝回座，夜月徒伤画里神。","地下青溪定相待，霓旌先后想纷纶。"]},{"t":"送顾汝馨","f":"七言律诗","c":["通家人物旧知名，十载相看倍眼明。","捧檄君方感毛义，思贤我复到颠闳。","青云未觉流芳远，白发多应别路生。","无限羁愁与乡思，并先秋雁过吴城。"]},{"t":"舜臣以诗慰问次韵","f":"七言律诗","c":["故人千里寄新诗，正是愁人阁泪时。","黄鸟有情依灌木，碧萝无命托松枝。","寻思往事多艰阻，却悟深盟是祸基。","长叹一回还自慰，重哀宁望老天知。"]},{"t":"卫景玉生辰席上作","f":"七言律诗","c":["我生于君后三算，我及君游已十年。","浮世升沈几搔首，高秋风物又登筵。","银钩欲转薇花月，金兽初腾柏子烟。","他日仙班只今定，丹梯须让海鸥先。"]},{"t":"戏简王汝楫","f":"七言绝句","c":["短日西风木叶飞，游人无处不思归。","连廒百室如云峙，肯念吴儿未授衣。"]},{"t":"方石先生季父逸老以宝庆守致仕先生名其居曰悬车旧第宝庆殁先生有诗命次其韵","f":"七言律诗","c":["执鞭无地候巾车，逸老编中识面初。","露冕犹闻下江汉，云山谁与画衡庐。","青槐古柏京尘远，寒日西风宰树疏。","莫向方岩诵哀些，竹林回首正欷歔。"]},{"t":"题画鹊","f":"七言绝句","c":["朝阳欲上万年枝，九色光芒射绀衣。","昨夜银河济灵驾，露华寒湿未禁飞。"]},{"t":"题花鸟二绝 其一","f":"七言绝句","c":["边鸾不起林良老，海内丹青合到谁。","晴日窗间弄沙鸟，楚烟湘树不胜思。"]},{"t":"题花鸟二绝 其二","f":"七言绝句","c":["黄凫不食聚沙觜，芦鸡相将踏清泚。","飞燕翩翩软风里，江乡春晴景如此。"]},{"t":"五马行赠宋舜和之广信","f":"七言古诗","c":["翩翩五马城东隅，车载两轓兼隼旟。","雪晴尘清马蹄健，长鸣跋地当云衢。","汉家太守唐刺史，握节专城殿千里。","古来青史亦吾人，肯使诸公尽专美。","西江望君如望云，驱车跃马无逡巡。","闻道群偷先出境，已识新侯是宋均。"]},{"t":"送赵起龙兼简其季父济民","f":"七言律诗","c":["白鹤城西是旧游，赵家亭馆菊花秋。","乡关客邸劳魂梦，风物天涯惜去留。","高隐久应忘世味，美材还合树勋猷。","竹林会语从容地，真诀参同可再紬。"]},{"t":"送吴克常南京光禄监事","f":"七言律诗","c":["通家亲戚故乡人，临别相逢意转亲。","晤语留连下城日，宦程迢递促车尘。","高冈合止冲霄翼，浅水宁容纵壑鳞。","朱雀乌衣壮游地，为君惆怅十年春。"]},{"t":"送朱文宿谒告东还","f":"七言律诗","c":["天寒游子正思家，手把离觞感物华。","乡梦五更犹禁漏，归轩千里即仙槎。","庭萱屡报东风鹊，宫锦争看上苑花。","同学故人应问我，绿莎春雨候江沙。"]},{"t":"十二月十一日进会典","f":"七言律诗","c":["黄盖亭亭拥赭函，箫韶声起殿东南。","百年盛事中天见，八圣深仁薄海覃。","尧典合从虞史润，周官不假汉儒参。","愿言善述光前训，竹帛千秋作美谈。"]},{"t":"明日宴礼部","f":"七言律诗","c":["大官供帐称殊恩，队舞番歌出内园。","礼肃上公尊奭旦，书成新典迈虞轩。","雍容不止过三爵，披览何由望九阍。","经幄小臣沾醉甚，但歌天保对尧尊。"]},{"t":"送沈继昌","f":"七言律诗","c":["丝纶阁里凤凰毛，五彩朝阳映碧霄。","出使口衔天语重，拜辞衣傍御香飘。","里门驻节惊梅蕊，驿路逢春问柳条。","为忆圣情深眷倚，肯耽山水后趋朝。"]},{"t":"戴宝之祖韶轩翁挽诗","f":"七言律诗","c":["西风林壑晚凄其，叹息仪刑不可追。","天地并临刲股夕，里闾相泣盖棺时。","谋深丰芑金楼册，心切苞桑白傅词。","翘首玉辉原上路，几人下马读穹碑。"]},{"t":"廿一日夜坐忆亡儿 其一","f":"七言绝句","c":["清夜长吟动四邻，吟成人静独沾巾。","不知此段缠绵意，天地相关复几人。"]},{"t":"廿一日夜坐忆亡儿 其二","f":"七言绝句","c":["视不成形举目存，青灯一盏近黄昏。","彭殇竟是谁分出，妄使瞿昙欲断恩。"]},{"t":"茅山书屋","f":"七言律诗","c":["小茅山下三间屋，养默斋中万卷书。","竹帛散馀嗟往事，海桑迁后复吾庐。","檐头树色低侵帙，门里泉流曲贯除。","想见日长佔毕倦，时来凭槛数游鱼。"]},{"t":"封知府叶公挽诗","f":"七言律诗","c":["百岁閒身五马封，向来江海复谁同。","门阑庆建看诸子，兄弟椿津对两翁。","身后诗书方自远，眼前林壑便忧空。","碧山烟雨淮南路，尚想扁舟理钓筒。"]},{"t":"次韵启衷给事病后见寄","f":"七言律诗","c":["宋玉杨朱各有悲，杜陵曾借草堂资。","由来造物多儿戏，毕竟风流是我师。","梦里青山休作意，眼前黄卷足新知。","春风几日开西馆，聊欲携尊问所疑。"]},{"t":"赋僮仆欢迎贺叔武尊人都宪致仕","f":"五言古诗","c":["陶令还家日，欢迎走仆僮。","人间长见画，林下复添公。","物色殊相近，遭逢夐不同。","飞腾会明盛，扬历践昭融。","苕水犹遗爱，横山早息戎。","全归渠亦喜，远涉路何穷。","指点桑榆茂，传观里巷空。","挽衣参稚子，扶杖杂村翁。","黄菊霜前约，青山雨后功。","行藏自吾道，消息任天工。","晚景看如此，皇恩信有终。","丹青如解写，何羡洛城东。"]},{"t":"题学生画","f":"七言律诗","c":["枝头野花红欲语，草绿犹带朝来雨。","狂蜂浪蝶不自持，下上东风作容与。","画师好手亦难逢，陶成已老况孙龙。","南薰殿里和丹粉，犹堪一笑解天容。"]},{"t":"送史景贤同知考绩","f":"五言古诗","c":["君侯北州英，淳直自天予。","青云二十载，安驾何容与。","朅来东吴郡，已复三刈黍。","庞统足方展，休徵名日举。","于焉朝天行，万里看凤翥。","尧门开九重，舜目周万宇。","才良合高位，疲瘵念慈父。","舟行望不尽，目断斜阳渚。"]},{"t":"月桂秋香送刘生还宜春应举","f":"古风","c":["月桂生月宫，一月一开落。","逢秋气弥盛，芬馥遍寥廓。","世人望影空裴?，刘郎自是神仙才。","兄弟相携月中去，正值秋风花烂开。","嫦娥玉手亲折赠，双枝香满黄金台。"]},{"t":"姚平夫挽诗","f":"五言律诗","c":["完节非今日，清心自昔年。","由来孤竹操，不逐艳阳迁。","旅殡烦僚友，归装富简编。","尚馀潜德在，合并鲁男传。"]},{"t":"华听竹挽诗","f":"五言律诗","c":["好在延祥竹，秋风日日情。","幽人不复到，虚节为谁清。","干蛊名无愧，贻谋事有成。","乡邦听舆论，合附孝门铭。"]},{"t":"次韵王用常下第写怀","f":"七言律诗","c":["漫说龙蟠与蠖伸，亨衢何遽不为迍。","才如贾谊宁终斥，美若陈平岂惯贫。","岐路只于忙里错，头颅须识本来真。","眼前掬水翻荷地，一笑相看剩几人。"]},{"t":"近为儿侄辈屈澄夫先生于小园东曙有诗次韵二首 其一","f":"七言律诗","c":["久知矾弟忆梅兄，又见新篇月露呈。","虚馆可能留国士，旧游端喜袭香名。","骚坛此日初申令，棋社何人敢订盟。","尽有残膏被来裔，未应飘泊叹浮生。"]},{"t":"近为儿侄辈屈澄夫先生于小园东曙有诗次韵二首 其二","f":"七言律诗","c":["安车久不到岩阿，水部无人复姓何。","秋浦白云天际远，夕阳红树屋边多。","笔精又展郇公帖，才钝愁闻郢客歌。","眼底桐枝未盈把，几时亲见十寻过。"]},{"t":"初至芸轩宅夜坐联句","f":"七言律诗","c":["良夜城南旧草堂，十年重继此灯光。","文章翰苑声华重，懒散林泉鬓发苍。","庭树看于前日大，酒杯偏向故人长。","出门翘首梅花月，又见天心转一阳。"]},{"t":"次高进之韵","f":"五言律诗","c":["读书思力行，挟策几凝想。","纷纷事酬对，顾影数离像。","譬彼旱岁槔，久矣困俯仰。","知言何敢云，有愧钟期赏。"]},{"t":"数日不过东园澄夫先生有月桂诗见示且归功于封殖之厚次韵奉答时腊月朔也","f":"七言绝句","c":["看花久不到墙东，不道寒丛也自红。","培殖可能符善颂，故应嘉气与君同。"]},{"t":"子南兄弟联取科名此予所素期而果不缪者计偕北上酌酒赋诗皆平居游处言语精神之实不复以文而故人情厚者当自慨然也","f":"七言律诗","c":["短屋疏帘野水边，几宵灯火共周旋。","联飞本拟看三凤，吉梦先教协两犍。","远道风尘初旅食，清朝簪冕是家传。","临岐不尽平生意，山海当年有喻篇。"]},{"t":"新蔡张孝子以乙丑岁寿七十其子什贰守松江松人为瀛海奇观图以赠为赋长句","f":"古风","c":["海山桃花千岁红，海日下照珠玲珑。","诸山卓立金芙蓉，直上正值浮离宫。","飞霞紫气流无穷，缟衣孤骞背青空。","下视六合尘溟濛，尘区逼隘鸟触笼。","井蛙瓮鸡纷蠛蠓，划然翘首骇所逢。","欲往从之渺难踪，先生七十颜如童。","前身乃是浮休翁，别来海波几桑蓬。","旧游历历宛目中，七还九转非吾功。","至行自与神明通，丹台峨峨银阙重。","姓名已隶东皇公，他年飙轮许相从。","还驾此，鹤来江东。"]},{"t":"题萧指挥便面","f":"七言绝句","c":["云海东南道路长，海山云树共苍苍。","扁舟何日寻萧史，一望蓬莱入渺茫。"]},{"t":"望云思亲图","f":"七言律诗","c":["白云飞空往复还，行人道上坐长叹。","亲庭偶与云路值，云飞宁与人相关。","梁公去来几千载，抚卷为君增叹嘅。","天涯望云伤客心，膝前一刻千黄金。"]},{"t":"往在京师赵君希德有南游之约四月廿五风雨中忽相见于东楼留两月别去将由金陵视其侄锦衣君而归赋此为赠","f":"七言律诗","c":["极目燕云望海鸿，江楼一笑雨兼风。","行边戏语三年约，梦里清欢两月同。","归棹细穿汀草绿，别尊新剥水菱红。","京华南北多亲旧，为说音书近懒通。"]},{"t":"杏东","f":"五言律诗","c":["为觅董仙家，春山满杏花。","朝阳三亩地，返照一林霞。","厚德初乡里，幽栖几岁华。","长生容我问，应不在丹砂。"]},{"t":"松岩","f":"五言古诗","c":["孤松何亭亭，孤生岩之阿。","俯视千仞溪，仰瞻郁嵯峨。","嵯峨不可攀，劳心其如何。","空谷无馀音，伐檀有遗歌。","惟应负苓子，千载重来过。"]},{"t":"傍鸥亭","f":"楚辞体","c":["江南水乡多白鸥，水神封作烟波侯。","主人作亭江水上，却傍鸥鸟为邻州。","鸥飞有时渡江去，小亭终日临江住。","亭兮傍鸥鸥傍亭，君其问诸忘机生。"]},{"t":"同年宋良佐巡按得代以书留别赋此寄赠 其一","f":"七言绝句","c":["黄叶柴门忆驻鞍，瓜期屈指又秋残。","玉尊不及沙头饯，明月长留海上寒。"]},{"t":"同年宋良佐巡按得代以书留别赋此寄赠 其二","f":"七言绝句","c":["十载青云逐后尘，冰霜此日见阳春。","书生别有迂谈在，拟托阳关赠故人。"]},{"t":"同年宋良佐巡按得代以书留别赋此寄赠 其三","f":"七言绝句","c":["百年天下是金瓯，根柢东南此四州。","同日震惊非小异，使君何以慰宸忧。"]},{"t":"同年宋良佐巡按得代以书留别赋此寄赠 其四","f":"七言绝句","c":["亩税丁庸自祖宗，巧名新意日重重。","归班第一章封奏，民力东南久已穷。"]},{"t":"同年宋良佐巡按得代以书留别赋此寄赠 其五","f":"七言绝句","c":["袨服奇装巧日增，百金财可一缣成。","苇帘布缘黄絁被，时为封章达圣明。"]},{"t":"同年宋良佐巡按得代以书留别赋此寄赠 其六","f":"七言绝句","c":["圣人初政日方升，独立台端仗老成。","一道歌谣听不尽，须知四海望升平。"]},{"t":"里生杨和为令尹张侯写百禽从凤图","f":"古风","c":["云间一峰名凤凰，峰形宛类凤飞翔。","凤飞百鸟争趋跄，林峦涧谷皆文章。","德辉一閟几千霜，空有遗迹留青苍。","贤明令君起番易，胸襟五色云锦香。","尚书双履出尚方，云飞飘然来帝乡。","和风甘雨相扶将，物无疵疠年谷穰。","疲癃鼓舞歌循良，有如凤凰集高冈。","百禽从之鸣锵锵，乃知往迹未为祥。","杨生妙手边与王，生绡数幅写朝阳。","抢榆喧啾俛复昂，菲红闪翠杂丹黄。","九苞凝立和以庄，鹰鹯鸮鹘雕鹗鸧。","外若矫亢中已降，云中阿阁金榜长。","晓日照耀腾金光，一飞下视堪舆方。","旧巢依然朱栱傍，即都归圣协宫商。","坐见四海登虞唐，圣人南面垂衣裳。","一峰回首，惟有春云十里郁郁封甘棠。"]},{"t":"送李原复佥宪岭南","f":"古风","c":["君昔还家我为客，客邸论诗坐连夕。","酒壶棋局间嘲诙，眼底十年犹历历。","君今为客我留家，南云望望渺天涯。","钟情已怀儿女恋，回首况对江梅花。","梅花的的映空碧，君到南中我应北。","南与北，转暌违，梅花心事更谁知。","岁寒冰雪金台下，犹可因风寄一枝。"]},{"t":"味梅图","f":"七言绝句","c":["羊酪莼羹各有宜，崇桃积季漫多姿。","岁寒一种真滋味，只许龙山处士知。"]},{"t":"丙寅春胡大声自桐庐守参政湖藩过松话旧诵予送通守殷君诗因用韵赋以识别","f":"七言律诗","c":["人物西江第一流，八年麾盖滞东州。","新恩宠亚三湘镇，远道争迎五两舟。","春宴喜闻京国语，云帆高望渚宫收。","公馀为有江湖思，还采蘋花寄旧游。"]},{"t":"曕云图","f":"古风","c":["昔年白云飞，亲在高堂思。","我归今日白云飞，亲在重泉空泪垂。","云飞天边无定所，到处瞻云泪如雨。","重泉冥冥閟长夜，云光不到泉台下。","如令孝子勿思亲，应是青天断却云。"]},{"t":"寿钱玉涧","f":"古风","c":["玉涧水，清且深，流不息，穷古今。","山头雨歇百谷聚，白虹一道来沈沈。","涧傍老人眼双碧，手弄涧泉坐白石。","泉流到海几清浅，明年花甲从头转。","酿涧水，作春醅，采涧芹，荐寿杯。","沐浴饮食无凶菑，此中自可度千岁，何必跨鹤游蓬莱。"]},{"t":"经锄别业","f":"七言律诗","c":["昔年劬学带经锄，万卷新开垄上居。","沈浸何妨问晴雨，经纶聊复试菑畬。","晚风檐隙垂秧马，残月窗间落蠹鱼。","莘野彭丘谁近远，诗成转觉爱吾庐。"]},{"t":"林塘晓霁","f":"七言律诗","c":["海日初照天苍凉，远村近村浮浅黄。","垂杨两岸不见水，中间一道开天光。","游蜂薨薨高下飞，乳燕拂水翻乌衣。","老农携锄放田水，平陂簇簇秧针肥。"]},{"t":"五月晦日同汪教授集傅教谕鼎顾东曙戚舜和刘文瑞俞民威游黄耳祠归用席间联句韵却寄诸公","f":"七言律诗","c":["红桃夹竹记初来，重到槐阴满绿苔。","城郭几番风雨过，山林依旧佛灯开。","莫论往事催霜鬓，且续新吟逭酒杯。","最可白云知我意，瞰窗临水久徘徊。"]},{"t":"琴泉","f":"五言古诗","c":["泠泠石上泉，衎衎松下琴。","泉流合琴奏，为君写清心。","天风岩际来，舞乱长松阴。","舍琴面流泉，风水有馀音。","悠然遂忘去，华月上青林。"]},{"t":"简华峰教谕乞莲栽 其一","f":"七言绝句","c":["园亭无竹使人俗，池馆无莲也寂寥。","梦入镜湖当六月，接天青盖拥红桡。"]},{"t":"简华峰教谕乞莲栽 其二","f":"七言绝句","c":["行人秋早长安去，中夏分莲不太忙。","但有碧䇶传别酒，任他红里倚新妆。"]},{"t":"郡斋三咏次金贰守仲仁韵 其一 文笔峰","f":"七言律诗","c":["高压重城郡圃东，分明一笔倚青空。","云蒸不作昙花雨，神运遥生月殿风。","此日育王重锡号，向来毛颖谢论功。","李藩未试南山判，傥可提携入汉宫。"]},{"t":"郡斋三咏次金贰守仲仁韵 其二 水帘","f":"七言律诗","c":["空无海祲杂江氛，一片湘帘映楚云。","不捲几年长袅袅，平铺终日自沄沄。","康王谷口珠千斛，龙女机中线五纹。","更爱晚凉新月上，玉钩双与画檐分。"]},{"t":"郡斋三咏次金贰守仲仁韵 其三 花幄","f":"七言律诗","c":["亭下阑干曲曲通，浅红深紫斗帡幪。","低迷似欲留歌扇，缛丽深疑蠹女工。","浓渍一番高阁雨，生香不断画帘风。","绳床最爱清晨坐，满耳薨薨听蜜翁。"]},{"t":"郡博汪先生约观莲病目不及赴赋此奉谢兼简邑博傅先生龙渊负苓二徵士","f":"七言律诗","c":["濯缨亭下水如罗，二十年前倚槛歌。","春服久荒沂上路，荷花仍发镜川波。","飞觞自笑成孤坐，放棹谁能许再过。","见说华峰红十丈，有人携酒候烟萝。"]},{"t":"池莲著一花用前韵报诸公约花开就赏","f":"七言律诗","c":["不知风叶展青罗，愁断南湖水调歌。","汉女有情先委佩，洛妃无伴独淩波。","峰头玉井难为配，画里金屏不啻过。","已洗青尊酌芳露，要看文旆倚云萝。"]},{"t":"华峰莲开用前韵见招奉答","f":"七言律诗","c":["越女红妆盖绿罗，薰风长忆扣舷歌。","却从五纬联珠地，涌出双峰湛玉波。","此日凭阑增慷慨，当年挟册几经过。","洄渊落木无穷意，敢谓乔松择女罗。"]},{"t":"金仲仁母太孺人寿","f":"七言律诗","c":["翟茀初乘自粉闱，朱幡继宠又兰枝。","中州礼训娴觿佩，南国鲜芳入鼎滋。","七十再逢添算日，三千长记采桃时。","宾筵向晚笙歌沸，犹恨嫦娥出海迟。"]},{"t":"庭鹤再雏送刘太守参政陕西","f":"古风","c":["瑶台双白鹤，飞来栖我庭。","栖我庭，岁一伏，两雏生。","一雏死，两悲鸣。","松阴宛转巢复成，巢成复引两雏行。","丹砂犹隐顶，白雪已垂翎。","成都未识赵公马，缑岭那闻王子笙。","成都缑岭知何处，忽报主人留鹤去。","主人去去登岩廊，鹤亦双翎日夜长。","他年欲觅庭下迹，千仞遥同威凤翔。"]},{"t":"拙隐","f":"五言古诗","c":["时方贵巧辩，我口讷如壶。","时方务驰骋，我足挛如拘。","岂无当世心，老此田园居。","方凿不受枘，直钓难为渔。","以兹甘静退，庶以全吾初。","分井艺黍稷，引绳树松梧。","蓄酒为宾燕，明灯课儿书。","此外百无事，悠然弄玄珠。","山水足清晏，园林堪画图。","逍遥遂百岁，从人嗤守株。"]},{"t":"颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢 其一","f":"五言绝句","c":["三年望东林，几日又当别。","盈盈谷水波，一苇谁共折。"]},{"t":"颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢 其二","f":"五言绝句","c":["溪莼牵紫丝，念子良已久。","不在秋风前，不在秋风后。"]},{"t":"颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢 其三","f":"五言绝句","c":["寒瓜削成菹，入眼犹自绿。","借问长安儿，此味还知不。"]},{"t":"颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢 其四","f":"五言绝句","c":["泽国有幽人，城中稀复见。","曾观论史书，吾党有腼面。"]}]};